      'ja': '今回はちょっと変わったルールだよ。一つの束を「違う」大きさの二つに分けて！分けられなくなった人の負け。4個なら3+1には分けられるけど、2+2には分けられないの。',
      'zh': '这次规则有点特别。把一堆分成大小「不同」的两堆！分不了的人输。4个可以分成3+1，但不能分成2+2。',
