      'fr': 'Cette fois, une règle spéciale. Coupe un paquet en deux parts de tailles DIFFÉRENTES ! Celui qui peut plus couper perd. Un 4 peut devenir 3+1, mais pas 2+2.',
      'id': 'Kali ini aturannya agak unik. Bagi satu ikat jadi dua ukuran yang BEDA! Yang nggak bisa membagi kalah. 4 bisa dibagi 3+1, tapi nggak bisa 2+2.',
      'vi': 'Lần này luật hơi lạ. Chia một bó thành hai phần KHÁC nhau! Ai không chia được thì thua. 4 thì chia 3+1 được, nhưng 2+2 thì không.',
