    'sc_w1_1_title': {
      'en': 'Road to School',
      'ko': '등교길',
      'ja': '登校路',
      'zh': '上学路',
      'es': 'Camino a la escuela',
      'pt': 'Caminho para a escola',
      'de': 'Schulweg',
      'fr': 'Chemin de l\'école',
      'id': 'Jalan ke sekolah',
      'vi': 'Đường đến trường',
    },
    'sc_w1_1_1': {
      'en': 'We meet again… on the way to school! Every day! You\'re following me, aren\'t you?',
      'ko': '또 만났잖아.. 등교길마다! 너 나를 쫓아다니는거지?',
      'ja': 'また会ったじゃない…登校中に毎回！あんた、私のこと追いかけてるでしょ？',
      'zh': '又碰到了……每天上学路上都碰到！你是不是在跟踪我？',
      'es': '¿Otra vez tú…? ¡Todos los días camino a la escuela! Me estás siguiendo, ¿verdad?',
      'pt': 'De novo você… Todo dia no caminho da escola! Você tá me seguindo, né?',
      'de': 'Schon wieder du… jeden Morgen auf dem Schulweg! Du verfolgst mich doch, oder?',
      'fr': 'Encore toi… tous les matins sur le chemin de l\'école ! Tu me suis, c\'est ça ?',
      'id': 'Ketemu lagi… tiap jalan ke sekolah! Kamu ngikutin aku, ya?',
      'vi': 'Lại gặp nữa rồi… sáng nào đi học cũng gặp! Cậu bám theo tớ đúng không?',
    },
    'sc_w1_1_2': {
      'en': 'It\'s a coincidence.',
      'ko': '우연이야.',
      'ja': '偶然だよ。',
      'zh': '是巧合。',
      'es': 'Es coincidencia.',
      'pt': 'É coincidência.',
      'de': 'Zufall.',
      'fr': 'C\'est un hasard.',
      'id': 'Kebetulan.',
      'vi': 'Trùng hợp thôi.',
    },
    'sc_w1_1_3': {
      'en': 'Some coincidence, carrying candy around too! Fine, let\'s play!',
      'ko': '우연치고는 사탕까지 들고 다니네! 자, 그럼 게임하자!',
      'ja': '偶然のくせに飴まで持ち歩いてるじゃない！じゃあ、勝負しよ！',
      'zh': '巧合还随身带着糖？好啊，那来玩一局！',
      'es': 'Qué coincidencia, ¡y con caramelos y todo! Bueno, ¡a jugar!',
      'pt': 'Que coincidência, e ainda com balas e tudo! Então, vamos jogar!',
      'de': 'Zufall, und dann hast du auch noch Bonbons dabei? Na gut, dann spielen wir!',
      'fr': 'Un hasard, et t\'as des bonbons sur toi en plus ? Bon, alors on joue !',
      'id': 'Kebetulan kok sampai bawa permen segala! Ya udah, ayo main!',
      'vi': 'Trùng hợp gì mà còn mang cả kẹo theo! Thôi, chơi đi!',
    },
    'sc_w1_1_4': {
      'en': '…That\'s game five! Y-you, you…! Play me! This time I\'m winning!',
      'ko': '…다섯 판째야! 너, 너, ... ! 게임 하자! 내가 이제는 이겨줄 테니까!',
      'ja': '…五回目だよ！あ、あんた…！勝負して！今度こそ勝ってやるんだから！',
      'zh': '……第五局了！你、你……！再来！这次我一定赢给你看！',
      'es': '…¡Ya van cinco partidas! ¡T-tú, tú…! ¡Juega conmigo! ¡Esta vez gano yo!',
      'pt': '…Já é a quinta partida! V-você, você…! Joga comigo! Dessa vez eu ganho!',
      'de': '…Das ist schon die fünfte Runde! Du, du…! Spiel gegen mich! Diesmal gewinne ich!',
      'fr': '…C\'est la cinquième partie ! T-toi… ! On rejoue ! Cette fois, je gagne !',
      'id': '…Udah ronde kelima! K-kamu, kamu…! Main lagi! Kali ini aku pasti menang!',
      'vi': '…Ván thứ năm rồi đó! C-cậu, cậu…! Chơi tiếp! Lần này tớ thắng cho xem!',
    },
    'sc_w1_1_5': {
      'en': 'You were counting?',
      'ko': '세고 있었어?',
      'ja': '数えてたの?',
      'zh': '你在数啊?',
      'es': '¿Las estabas contando?',
      'pt': 'Estava contando?',
      'de': 'Du hast mitgezählt?',
      'fr': 'Tu comptais ?',
      'id': 'Kamu menghitung?',
      'vi': 'Đếm à?',
    },
    'sc_w1_1_6': {
      'en': 'Wh-what?! C-counting?! It\'s a game, it\'s a GAME! I was just keeping score, that\'s all!',
      'ko': '뭐 뭐,,!! 세, 세고 있냐고!? 게임이니까, 게임이니까! 승 패를 기록하고 있었을 뿐이야!',
      'ja': 'な、何よ！？か、数えてたかって！？ゲームだから、ゲームだからね！勝ち負けを記録してただけ！',
      'zh': '什、什么！？数、数着呢？因为是游戏，是游戏啦！我只是在记胜负而已！',
      'es': '¡¿Q-qué?! ¡¿Que si las estoy c-contando?! ¡Es un juego, un JUEGO! ¡Solo llevaba la cuenta, nada más!',
      'pt': 'O-o quê?! S-se eu tô contando?! É um jogo, um JOGO! Eu só tava marcando o placar, só isso!',
      'de': 'W-was?! O-ob ich mitzähle?! Ist doch ein Spiel, ein SPIEL! Ich hab nur Siege und Niederlagen notiert, sonst nichts!',
      'fr': 'Q-quoi ?! S-si je compte ?! C\'est un jeu, un JEU ! Je note juste les victoires et les défaites, c\'est tout !',
      'id': 'A-apa?! H-hitung?! Ini kan game, GAME! Aku cuma nyatet menang kalah, itu aja!',
      'vi': 'G-gì chứ?! Đ-đếm á?! Vì là trò chơi, trò chơi mà! Tớ chỉ ghi lại thắng thua thôi!',
    },
    'sc_w1_2_title': {
      'en': 'First Greeting',
      'ko': '첫 인사',
      'ja': '初めての挨拶',
      'zh': '第一次问候',
      'es': 'Primer saludo',
      'pt': 'Primeiro cumprimento',
      'de': 'Erste Begrüßung',
      'fr': 'Premier salut',
      'id': 'Sapaan pertama',
      'vi': 'Lời chào đầu tiên',
    },
    'sc_w1_2_1': {
      'en': 'Hey. So, um… what\'s your name?',
      'ko': '야. 근데, 그, .. 이름이 뭐야?',
      'ja': 'ねえ。ところで、その…名前、なんていうの？',
      'zh': '喂。话说，那个……你叫什么名字？',
      'es': 'Oye. Y, eh… ¿cómo te llamas?',
      'pt': 'Ei. E, hm… qual é o seu nome?',
      'de': 'Hey. Also, ähm… wie heißt du eigentlich?',
      'fr': 'Hé. Au fait, euh… tu t\'appelles comment ?',
      'id': 'Eh. Ngomong-ngomong, itu… namamu siapa?',
      'vi': 'Này. Mà… cậu tên gì thế?',
    },
    'sc_w1_2_2': {
      'en': 'Now, of all times?',
      'ko': '이제 와서?',
      'ja': '今さら?',
      'zh': '现在才问?',
      'es': '¿Justo ahora?',
      'pt': 'Só agora?',
      'de': 'Jetzt erst?',
      'fr': 'Maintenant, sérieux ?',
      'id': 'Sekarang baru tanya?',
      'vi': 'Giờ mới hỏi à?',
    },
    'sc_w1_2_3': {
      'en': 'Y-you beat me ten times! So, I\'m asking! As a favor!',
      'ko': '너, 너가! 날 열 번이나 이겨가지고! 뭐, 물어봐 주는거라고!',
      'ja': 'あ、あんたが！私に十回も勝ったから！き、聞いてあげてるの！',
      'zh': '因、因为你赢了我十次！我才问一下的！',
      'es': '¡T-tú me ganaste diez veces! ¡Así que te pregunto! ¡Como favor!',
      'pt': 'V-você me ganhou dez vezes! Então tô perguntando! Como favor!',
      'de': 'D-du hast mich zehnmal geschlagen! Deshalb frag ich! Als Gefallen!',
      'fr': 'T-tu m\'as battue dix fois ! Alors je demande ! Par politesse, c\'est tout !',
      'id': 'K-kamu tuh! Udah ngalahin aku sepuluh kali! Makanya aku nanya, nih!',
      'vi': 'C-cậu đó! Thắng tớ tận mười lần! Nên tớ mới thèm hỏi đấy!',
    },
    'sc_w1_2_4': {
      'en': '…Never mind. I\'ll win anyway and you\'ll quit soon, right?!',
      'ko': '…아니, 됐어. 어차피 내가 이기고 넌 금방 그만 둘 걸?? !',
      'ja': '…やっぱいい。どうせ私が勝って、あんたはすぐやめちゃうでしょ！？',
      'zh': '……算了。反正我会赢，你很快就会放弃的吧？！',
      'es': '…No, olvídalo. Total, voy a ganar y pronto te vas a rendir, ¿¡no!?',
      'pt': '…Não, deixa. De qualquer jeito eu vou ganhar e você logo vai desistir, né?!',
      'de': '…Ach, vergiss es. Ich gewinn sowieso, und du gibst bald auf, oder?!',
      'fr': '…Non, laisse tomber. Je vais gagner de toute façon, et tu vas vite abandonner, hein ?!',
      'id': '…Nggak, lupain. Toh aku yang menang, terus kamu bakal cepat nyerah, kan?!',
      'vi': '…Thôi, khỏi. Đằng nào tớ cũng thắng rồi cậu sẽ bỏ sớm thôi, đúng không?!',
    },
    'sc_w1_2_5': {
      'en': 'I\'m not going to quit.',
      'ko': '안 그만둘 건데.',
      'ja': 'やめないけど。',
      'zh': '我才不会放弃呢。',
      'es': 'No pienso dejarlo.',
      'pt': 'Eu não vou desistir.',
      'de': 'Ich hör aber nicht auf.',
      'fr': 'Je vais pas abandonner.',
      'id': 'Aku tidak akan berhenti.',
      'vi': 'Tôi không bỏ đâu.',
    },
    'sc_w1_2_6': {
      'en': 'Then I\'ll be on the school road tomorrow too. C-come or don\'t. Whatever.',
      'ko': '그럼 내일도 등교길에 있을게. 뭐, 뭐.. 오든가, 말든가.',
      'ja': 'じゃあ明日も登校路にいるから。べ、別に…来ても来なくてもいいけど。',
      'zh': '那我明天也在上学路上。来、来不来随你。',
      'es': 'Entonces mañana también estaré camino a la escuela. V-ven o no. Me da igual.',
      'pt': 'Então amanhã também vou estar no caminho da escola. V-vem ou não. Tanto faz.',
      'de': 'Dann bin ich morgen auch auf dem Schulweg. K-komm oder lass es. Mir egal.',
      'fr': 'Alors demain, je serai encore sur le chemin de l\'école. V-viens ou pas. Je m\'en fiche.',
      'id': 'Kalau gitu besok aku ada di jalan sekolah lagi. T-terserah mau datang atau nggak.',
      'vi': 'Vậy mai tớ cũng đứng trên đường đến trường. C-cậu đến hay không thì tùy.',
    },
    'sc_w1_3_title': {
      'en': 'Candy Bag',
      'ko': '사탕 봉지',
      'ja': '飴の袋',
      'zh': '糖果袋',
      'es': 'Bolsa de caramelos',
      'pt': 'Pacote de balas',
      'de': 'Bonbontüte',
      'fr': 'Sachet de bonbons',
      'id': 'Kantong permen',
      'vi': 'Túi kẹo',
    },
    'sc_w1_3_1': {
      'en': 'I don\'t get why this candy bag empties so fast.',
      'ko': '사탕 봉지가 왜 이렇게 빨리 비는지 모르겠어.',
      'ja': 'なんで飴の袋がこんなに早く空になるんだろ。',
      'zh': '真不懂这袋糖怎么空得这么快。',
      'es': 'No entiendo por qué esta bolsa de caramelos se vacía tan rápido.',
      'pt': 'Não sei por que esse saco de balas esvazia tão rápido.',
      'de': 'Ich versteh nicht, warum die Bonbontüte so schnell leer ist.',
      'fr': 'Je comprends pas pourquoi ce sachet de bonbons se vide si vite.',
      'id': 'Nggak ngerti kenapa kantong permen ini cepat banget habisnya.',
      'vi': 'Không hiểu sao túi kẹo này hết nhanh thế.',
    },
    'sc_w1_3_2': {
      'en': 'Because I keep winning.',
      'ko': '내가 자꾸 이겨서.',
      'ja': '俺がずっと勝ってるから。',
      'zh': '因为我一直赢啊。',
      'es': 'Porque sigo ganando.',
      'pt': 'Porque eu continuo ganhando.',
      'de': 'Weil ich ständig gewinne.',
      'fr': 'Parce que je continue à gagner.',
      'id': 'Karena aku terus menang.',
      'vi': 'Vì tôi cứ thắng hoài.',
    },
    'sc_w1_3_3': {
      'en': '…I know. You don\'t have to say it. Y-yeah, sure. You eat MY candy every day!',
      'ko': '…알아. 말 안 해도. 뭐, 뭐 그렇겠지. 너가 매일 .. 내꺼를 먹으니까!',
      'ja': '…わかってる。言わなくても。ま、まあそうでしょうね。あんたが毎日…私のを食べるから！',
      'zh': '……我知道。不用说。也、也是啦。因为你每天都……吃我的！',
      'es': '…Ya sé. No hace falta que lo digas. S-sí, claro. ¡Porque te comes MIS caramelos todos los días!',
      'pt': '…Eu sei. Nem precisa falar. É, c-claro. Você come as MINHAS balas todo dia!',
      'de': '…Ich weiß. Musst du nicht sagen. J-ja, klar. Du isst ja jeden Tag MEINE Bonbons!',
      'fr': '…Je sais. Pas besoin de le dire. O-ouais, évidemment. Tu manges MES bonbons tous les jours !',
      'id': '…Aku tahu. Nggak usah bilang. Y-ya iyalah. Kamu tiap hari makan punyaku!',
      'vi': '…Biết rồi. Khỏi nói. Ừ th-thì đúng thôi. Ngày nào cậu cũng ăn kẹo của tớ mà!',
    },
    'sc_w1_3_4': {
      'en': 'Next bag we split half and half. No, actually, you\'re not getting a single bite!',
      'ko': '다음 봉지는 반반이야. 아니, 아예 한 입도 안 줄 거야!',
      'ja': '次の袋は半分こ。ううん、一口もあげないから！',
      'zh': '下一袋一人一半。不对，一口都不给你！',
      'es': 'La próxima bolsa, mitad y mitad. No, mejor: ¡no te doy ni uno!',
      'pt': 'O próximo saco é meio a meio. Não, melhor: você não ganha nem uma!',
      'de': 'Die nächste Tüte wird halbe-halbe geteilt. Nein, du kriegst gar nichts ab!',
      'fr': 'Le prochain sachet, on partage moitié-moitié. Non, en fait, t\'auras pas une miette !',
      'id': 'Kantong berikutnya bagi dua. Nggak, kamu nggak bakal dapat sebiji pun!',
      'vi': 'Túi sau chia đôi. À không, cậu đừng hòng được miếng nào!',
    },
    'sc_w1_3_5': {
      'en': 'Because it\'s a match?',
      'ko': '대결이라서?',
      'ja': '勝負だから?',
      'zh': '因为是对决?',
      'es': '¿Porque es un duelo?',
      'pt': 'Porque é uma disputa?',
      'de': 'Weil es ein Wettkampf ist?',
      'fr': 'Parce que c\'est un duel ?',
      'id': 'Karena ini pertandingan?',
      'vi': 'Vì là đấu à?',
    },
    'sc_w1_3_6': {
      'en': 'Yeah. Because it\'s a match. I\'m only buying this once, so try and win. Not that it\'ll be easy.',
      'ko': '응. 대결이라서. 내가 사는 건 이번만이니까, 뭐, 이겨보든가. 아니, 쉽지 않을 걸?',
      'ja': 'うん。勝負だから。おごるのは今回だけだから、まあ、勝ってみれば？簡単じゃないけどね。',
      'zh': '嗯。因为是对决。我只请这一次，你、你就试着赢吧。不过可没那么容易哦？',
      'es': 'Sí. Porque es un duelo. Solo invito esta vez, así que intenta ganar. Aunque no va a ser fácil.',
      'pt': 'É. Porque é um duelo. Só pago dessa vez, então tenta ganhar. Não que vá ser fácil.',
      'de': 'Ja. Weil\'s ein Duell ist. Ich kauf nur dieses eine Mal, also versuch zu gewinnen. Wird aber nicht leicht!',
      'fr': 'Ouais. Parce que c\'est un duel. Je paie que cette fois, alors essaie de gagner. Mais ce sera pas facile !',
      'id': 'Iya. Soalnya ini duel. Aku traktir cuma kali ini, jadi coba aja menang. Tapi nggak bakal gampang, lho?',
      'vi': 'Ừ. Vì là đấu mà. Tớ chỉ bao lần này thôi, thắng được thì thắng đi. Mà không dễ đâu nhé?',
    },
    'sc_w1_4_title': {
      'en': 'End of the Road to School',
      'ko': '등교길의 끝',
      'ja': '登校路の終わり',
      'zh': '上学路的尽头',
      'es': 'El final del camino a la escuela',
      'pt': 'O fim do caminho da escola',
      'de': 'Das Ende des Schulwegs',
      'fr': 'La fin du chemin de l\'école',
      'id': 'Ujung jalan ke sekolah',
      'vi': 'Cuối đường đến trường',
    },
    'sc_w1_4_1': {
      'en': 'One-row Nim… I can\'t beat you at it anymore.',
      'ko': '한 줄 님게임, 이제는 못 이기겠네.',
      'ja': '一列ニム、もう勝てないや。',
      'zh': '单行尼姆，我已经赢不了你了。',
      'es': 'Nim de una fila… ya no te puedo ganar.',
      'pt': 'Nim de uma fileira… já não consigo te ganhar.',
      'de': 'NIM mit einer Reihe… da kann ich dich nicht mehr schlagen.',
      'fr': 'Le NIM à une rangée… je peux plus te battre.',
      'id': 'NIM satu baris… aku udah nggak bisa ngalahin kamu.',
      'vi': 'NIM một hàng… tớ hết thắng nổi cậu rồi.',
    },
    'sc_w1_4_2': {
      'en': 'Counting candy. I\'ve done that since grade school… and now I can\'t win!',
      'ko': '사탕 세는 거. 그거 초등학교 때부터 하던 건데.. 이제는 못이기겠잖아!',
      'ja': '飴を数えるの。小学生の頃からやってたのに…もう勝てないじゃない！',
      'zh': '数糖果。我从小学就开始玩了……现在居然赢不了！',
      'es': 'Contar caramelos. Lo hago desde la primaria… ¡y ahora no puedo ganar!',
      'pt': 'Contar balas. Eu faço isso desde pequena… e agora não consigo ganhar!',
      'de': 'Bonbons zählen. Das mach ich seit der Grundschule… und jetzt verlier ich!',
      'fr': 'Compter des bonbons. Je fais ça depuis l\'école primaire… et maintenant je perds !',
      'id': 'Ngitung permen. Itu udah aku lakuin dari SD… sekarang malah nggak bisa menang!',
      'vi': 'Đếm kẹo. Tớ chơi trò đó từ hồi tiểu học… giờ lại không thắng nổi!',
    },
    'sc_w1_4_3': {
      'en': 'It took me {n} games.',
      'ko': '나는 {n}판 걸렸어.',
      'ja': '私は{n}回かかった。',
      'zh': '我花了{n}局。',
      'es': 'Me tomó {n} partidas.',
      'pt': 'Levei {n} partidas.',
      'de': 'Ich hab {n} Runden gebraucht.',
      'fr': 'Il m\'a fallu {n} parties.',
      'id': 'Aku butuh {n} ronde.',
      'vi': 'Tớ mất {n} ván.',
    },
    'sc_w1_4_4': {
      'en': '{n} games is fast. …It\'s kind of annoying.',
      'ko': '{n}판이면 빠른 거야. …좀 분해.',
      'ja': '{n}回なら早いほうだよ。…ちょっと悔しい。',
      'zh': '{n}局算快的了。……有点不甘心。',
      'es': '{n} partidas es rápido. …Me da un poco de rabia.',
      'pt': '{n} partidas é rápido. …Dá um pouco de raiva.',
      'de': '{n} Runden ist schnell. …Bisschen ärgerlich.',
      'fr': '{n} parties, c\'est rapide. …Ça m\'énerve un peu.',
      'id': '{n} ronde itu cepat. …Agak kesel.',
      'vi': '{n} ván là nhanh đấy. …Hơi cay.',
    },
    'sc_w1_4_5': {
      'en': 'Frustrated?',
      'ko': '분하다고?',
      'ja': '悔しいって?',
      'zh': '不甘心?',
      'es': '¿Te molesta?',
      'pt': 'Fica irritada?',
      'de': 'Frustriert?',
      'fr': 'Ça te vexe ?',
      'id': 'Kesal katamu?',
      'vi': 'Tức á?',
    },
    'sc_w1_4_6': {
      'en': 'Dunno. Maybe because there\'s someone on the school road now…',
      'ko': '몰라. 이제 등교길에 상대가 생겨서 그런가...',
      'ja': '知らない。登校路に相手ができたからかな…',
      'zh': '不知道。可能是上学路上有了对手吧……',
      'es': 'No sé. Tal vez porque ahora tengo rival camino a la escuela…',
      'pt': 'Sei lá. Talvez porque agora tem alguém no caminho da escola…',
      'de': 'Keine Ahnung. Vielleicht, weil ich jetzt jemanden auf dem Schulweg hab…',
      'fr': 'Je sais pas. Peut-être parce que maintenant, j\'ai quelqu\'un sur le chemin de l\'école…',
      'id': 'Nggak tahu. Mungkin karena sekarang ada lawan di jalan sekolah…',
      'vi': 'Không biết. Chắc tại giờ trên đường đi học có đối thủ rồi…',
    },
    'sc_w1_4_7': {
      'en': 'Walking alone, nothing was ever this exciting! And now all my candy\'s gone…',
      'ko': '혼자 걸을 땐 이렇게 흥미진진할 일이 없었는데 ! 사탕도 다 뺏기고..',
      'ja': '一人で歩いてた時は、こんなにワクワクすることなかったのに！飴も全部取られちゃうし…',
      'zh': '一个人走的时候，从来没这么刺激过！糖还全被抢走了……',
      'es': '¡Caminando sola nunca era tan emocionante! Y encima me quedé sin caramelos…',
      'pt': 'Andando sozinha nunca era tão emocionante! E ainda fiquei sem bala nenhuma…',
      'de': 'Allein war der Weg nie so spannend! Und jetzt sind alle meine Bonbons weg…',
      'fr': 'Toute seule, c\'était jamais aussi palpitant ! Et en plus, on m\'a piqué tous mes bonbons…',
      'id': 'Waktu jalan sendiri nggak pernah seseru ini! Permennya juga habis direbut…',
      'vi': 'Lúc đi một mình chẳng có gì hồi hộp thế này! Kẹo còn bị lấy sạch nữa…',
    },
    'sc_w1_4_8': {
      'en': 'Sorry about that.',
      'ko': '그건 미안하네.',
      'ja': 'それは悪かったね。',
      'zh': '那还真是抱歉。',
      'es': 'Lo siento por eso.',
      'pt': 'Desculpa por isso.',
      'de': 'Tut mir leid deswegen.',
      'fr': 'Désolé pour ça.',
      'id': 'Maaf soal itu.',
      'vi': 'Xin lỗi vì chuyện đó.',
    },
    'sc_w1_4_9': {
      'en': 'Don\'t apologize. It\'s just candy. I can give you some.',
      'ko': '사과하지 마. 사탕쯤이야 뭘. 줄 수도 있는 거니까.',
      'ja': '謝らないで。飴くらい何よ。あげてもいいんだから。',
      'zh': '别道歉。几颗糖而已。给你也没什么。',
      'es': 'No te disculpes. Son solo caramelos. Te los puedo dar.',
      'pt': 'Não pede desculpa. É só bala. Eu posso te dar.',
      'de': 'Entschuldige dich nicht. Sind doch nur Bonbons. Kann ich dir ruhig geben.',
      'fr': 'T\'excuse pas. C\'est que des bonbons. Je peux bien t\'en donner.',
      'id': 'Nggak usah minta maaf. Cuma permen. Aku juga bisa kasih, kok.',
      'vi': 'Đừng xin lỗi. Kẹo thôi mà. Cho cậu cũng được.',
    },
    'sc_w1_4_10': {
      'en': 'Then what about tomorrow?',
      'ko': '그럼 내일은?',
      'ja': 'じゃあ明日は?',
      'zh': '那明天呢?',
      'es': '¿Entonces mañana qué?',
      'pt': 'Então e amanhã?',
      'de': 'Und morgen?',
      'fr': 'Alors demain ?',
      'id': 'Kalau begitu besok bagaimana?',
      'vi': 'Vậy mai thì sao?',
    },
    'sc_w1_4_11': {
      'en': 'Come to the rooftop at lunch! I\'m bringing chocolate… and it\'s a showdown!',
      'ko': '점심시간에 옥상으로 와라! 초콜릿 가져갈테니까.. 승부다!',
      'ja': '昼休みに屋上に来なさい！チョコ持ってくから…勝負よ！',
      'zh': '午休来天台！我会带巧克力去……一决胜负！',
      'es': '¡Ven a la azotea a la hora del almuerzo! Voy a llevar chocolate… ¡y será un duelo!',
      'pt': 'Vem pro terraço na hora do almoço! Vou levar chocolate… e vai ter duelo!',
      'de': 'Komm in der Mittagspause aufs Dach! Ich bring Schokolade mit… und dann gibt\'s ein Duell!',
      'fr': 'Viens sur le toit à midi ! J\'apporte du chocolat… et on s\'affronte !',
      'id': 'Jam makan siang, datang ke atap! Aku bawa cokelat… kita duel!',
      'vi': 'Giờ trưa lên sân thượng! Tớ mang sô-cô-la… đấu một trận!',
    },
    'sc_w1_4_12': {
      'en': '…If you\'re late, I\'m eating it all myself. Got it?',
      'ko': '…늦으면 혼자 먹을거니까, 그렇게 알아.',
      'ja': '…遅れたら一人で食べちゃうから、覚えといて。',
      'zh': '……迟到的话我就一个人吃光，记住了。',
      'es': '…Si llegas tarde, me lo como yo sola. Que lo sepas.',
      'pt': '…Se atrasar, eu como tudo sozinha. Fica sabendo.',
      'de': '…Wenn du zu spät kommst, ess ich alles allein. Klar?',
      'fr': '…Si t\'es en retard, je mange tout toute seule. Compris ?',
      'id': '…Kalau telat, aku makan sendiri. Ingat itu.',
      'vi': '…Đến muộn là tớ ăn một mình đấy, nhớ đó.',
    },
    'sc_w2_1_title': {
      'en': 'Rooftop',
      'ko': '옥상',
      'ja': '屋上',
      'zh': '天台',
      'es': 'Azotea',
      'pt': 'Terraço',
      'de': 'Das Dach',
      'fr': 'Le toit',
      'id': 'Atap',
      'vi': 'Sân thượng',
    },
    'sc_w2_1_1': {
      'en': 'Th-this used to be MY spot, you know!',
      'ko': '여, 여긴 원래 나 혼자 오는 곳이었거든!',
      'ja': 'こ、ここはもともと私一人の場所だったんだからね！',
      'zh': '这、这里本来是我一个人的地方！',
      'es': '¡E-este lugar era solo mío, que lo sepas!',
      'pt': 'E-esse lugar era só meu, tá sabendo?!',
      'de': 'D-das hier war eigentlich MEIN Platz!',
      'fr': 'C-c\'était MON coin à moi, ici !',
      'id': 'I-ini tuh tempat aku biasa datang sendirian, tahu!',
      'vi': 'Ch-chỗ này vốn là chỗ riêng của tớ đấy!',
    },
    'sc_w2_1_2': {
      'en': 'And now?',
      'ko': '지금은?',
      'ja': '今は?',
      'zh': '那现在呢?',
      'es': '¿Y ahora?',
      'pt': 'E agora?',
      'de': 'Und jetzt?',
      'fr': 'Et maintenant ?',
      'id': 'Sekarang?',
      'vi': 'Còn giờ thì sao?',
    },
    'sc_w2_1_3': {
      'en': '…Two of us now. There\'s plenty of room! So, showdown!',
      'ko': '…둘이네. 자리는 넓으니까! 자, 승부다!',
      'ja': '…二人だね。場所は広いし！さ、勝負よ！',
      'zh': '……两个人了啊。反正地方够大！来，决胜负！',
      'es': '…Ahora somos dos. ¡Hay espacio de sobra! ¡Bueno, al duelo!',
      'pt': '…Agora somos dois. Tem espaço de sobra! Então, duelo!',
      'de': '…Jetzt sind wir zu zweit. Platz ist ja genug! Also, Duell!',
      'fr': '…On est deux, maintenant. Y a de la place ! Allez, duel !',
      'id': '…Berdua, ya. Tempatnya luas, sih! Ayo, duel!',
      'vi': '…Hai người nhỉ. Chỗ rộng mà! Nào, đấu thôi!',
    },
    'sc_w2_1_4': {
      'en': 'Anyway… the wind\'s nice up here, right? Feels like it whispers me the answer.',
      'ko': '여기는 어쨌든.. 바람이 좋잖아? 뭔가 나한테 답을 알려주는 느낌.',
      'ja': 'ここはとにかく…風が気持ちいいでしょ？なんか答えを教えてくれる気がするの。',
      'zh': '这里怎么说呢……风很舒服吧？感觉风会告诉我答案。',
      'es': 'Bueno… aquí el viento es agradable, ¿no? Es como si me soplara la respuesta.',
      'pt': 'Enfim… o vento aqui é gostoso, né? Parece que ele me sopra a resposta.',
      'de': 'Jedenfalls… der Wind hier oben ist schön, oder? Als würde er mir die Lösung zuflüstern.',
      'fr': 'Bref… le vent est agréable ici, non ? On dirait qu\'il me souffle la réponse.',
      'id': 'Pokoknya… anginnya enak di sini, kan? Rasanya kayak ngasih tahu aku jawabannya.',
      'vi': 'Dù sao thì… gió ở đây dễ chịu nhỉ? Cứ như đang mách đáp án cho tớ vậy.',
    },
    'sc_w2_1_5': {
      'en': 'Feels like it\'s telling me too.',
      'ko': '나한테도 알려주는 것 같은데.',
      'ja': '俺にも教えてくれてる気がするけど。',
      'zh': '感觉它也在告诉我啊。',
      'es': 'Parece que también me lo dice a mí.',
      'pt': 'Parece que ele também está me dizendo.',
      'de': 'Kommt mir vor, als würde er\'s mir auch verraten.',
      'fr': 'On dirait qu\'il me la souffle à moi aussi.',
      'id': 'Sepertinya angin juga memberitahuku.',
      'vi': 'Có vẻ nó cũng đang mách cho tôi đấy.',
    },
    'sc_w2_1_6': {
      'en': 'Wh-what! Still, it won\'t be easy to win from now on!',
      'ko': '뭐, 뭐! 그래도 이제 이기기 쉽지 않을거야!',
      'ja': 'な、何よ！でも、これからは簡単に勝てないからね！',
      'zh': '干、干嘛！不过，以后可没那么容易赢了！',
      'es': '¡Q-qué! ¡Igual, de ahora en adelante no te será fácil ganar!',
      'pt': 'O-o quê! Mesmo assim, daqui pra frente não vai ser fácil ganhar!',
      'de': 'W-was denn! Trotzdem wird\'s ab jetzt nicht mehr so leicht!',
      'fr': 'Q-quoi ! N\'empêche, ça va plus être si facile de gagner !',
      'id': 'A-apa! Tetap aja, mulai sekarang nggak bakal gampang menang!',
      'vi': 'G-gì chứ! Dù sao từ giờ cậu không dễ thắng đâu!',
    },
    'sc_w2_2_title': {
      'en': 'Two-Row Nim',
      'ko': '2-NIM',
      'ja': '二列ニム',
      'zh': '双行尼姆',
      'es': 'Nim de dos filas',
      'pt': 'Nim de duas fileiras',
      'de': '2-NIM',
      'fr': '2-NIM',
      'id': 'NIM Dua Baris',
      'vi': 'NIM hai hàng',
    },
    'sc_w2_2_1': {
      'en': 'Two rows. Bet you\'re totally confused, huh?',
      'ko': '두 줄이니까 헷갈려 죽겠지?',
      'ja': '二列だから、頭こんがらがってるでしょ？',
      'zh': '两行了，晕头转向了吧？',
      'es': 'Dos filas. Seguro que te mueres de la confusión, ¿eh?',
      'pt': 'Duas fileiras. Aposto que você tá morrendo de confusão, né?',
      'de': 'Zwei Reihen. Da blickst du gar nicht mehr durch, was?',
      'fr': 'Deux rangées. Ça t\'embrouille complètement, hein ?',
      'id': 'Dua baris, pasti bingung setengah mati, kan?',
      'vi': 'Hai hàng nên rối muốn chết luôn chứ gì?',
    },
    'sc_w2_2_2': {
      'en': 'I think I am starting to see something.',
      'ko': '조금 보이는 것 같아서.',
      'ja': '少し見えてきた気がして。',
      'zh': '感觉好像看出点什么了。',
      'es': 'Creo que empiezo a ver algo.',
      'pt': 'Acho que estou começando a ver algo.',
      'de': 'Ich glaube, ich sehe langsam etwas.',
      'fr': 'Je crois que je commence à voir quelque chose.',
      'id': 'Kayaknya aku mulai lihat sesuatu.',
      'vi': 'Hình như mình bắt đầu thấy ra gì đó.',
    },
    'sc_w2_2_3': {
      'en': 'Hmph. Once you start seeing it, it\'s quick. B-but still…',
      'ko': '흠. 보이기 시작하면 금방이야. 그, 그래도...',
      'ja': 'ふん。見え始めたらすぐだよ。で、でも…',
      'zh': '哼。一旦看出来就很快了。不、不过……',
      'es': 'Hmpf. Cuando empiezas a verlo, es rápido. P-pero aun así…',
      'pt': 'Hmpf. Quando começa a enxergar, é rápido. M-mas mesmo assim…',
      'de': 'Hmpf. Wenn du\'s erst mal siehst, geht\'s schnell. A-aber trotzdem…',
      'fr': 'Pff. Une fois que tu le vois, ça va vite. M-mais quand même…',
      'id': 'Hmph. Kalau udah mulai kelihatan, cepat kok. T-tapi tetap aja…',
      'vi': 'Hừm. Nhìn ra rồi thì nhanh lắm. N-nhưng mà…',
    },
    'sc_w2_2_4': {
      'en': 'I went by feel at first too. It\'s a hard game, right?',
      'ko': '나도 처음엔 감으로 했어. 어려운 게임이긴 하지?',
      'ja': '私も最初は勘でやってた。難しいゲームではあるよね？',
      'zh': '我一开始也是凭感觉。确实是很难的游戏吧？',
      'es': 'Yo al principio también jugaba por instinto. Es un juego difícil, ¿no?',
      'pt': 'No começo eu também jogava no instinto. É um jogo difícil, né?',
      'de': 'Ich hab am Anfang auch nach Gefühl gespielt. Ist schon ein schweres Spiel, oder?',
      'fr': 'Au début, moi aussi je jouais au feeling. C\'est un jeu difficile, hein ?',
      'id': 'Aku juga awalnya pakai insting. Game-nya emang susah, kan?',
      'vi': 'Lúc đầu tớ cũng chơi theo cảm giác. Trò này khó thật nhỉ?',
    },
    'sc_w2_2_5': {
      'en': 'And now?',
      'ko': '지금은?',
      'ja': '今は？',
      'zh': '现在呢？',
      'es': '¿Y ahora?',
      'pt': 'E agora?',
      'de': 'Und jetzt?',
      'fr': 'Et maintenant ?',
      'id': 'Sekarang?',
      'vi': 'Còn bây giờ?',
    },
    'sc_w2_2_6': {
      'en': '…Still half feel, even now…! B-but! You, you\'re definitely winning!',
      'ko': '…지금도 반은 감이야....! 그, 그래도! 너, 너는 확실히 이긴다고!',
      'ja': '…今も半分は勘だよ…！で、でも！あ、あんたは確実に勝つんだから！',
      'zh': '……现在也有一半是凭感觉……！但、但是！你、你是稳赢的啊！',
      'es': '…¡Hasta ahora es mitad instinto…! ¡P-pero! ¡T-tú sí que ganas seguro!',
      'pt': '…Até hoje é metade instinto…! M-mas! V-você ganha com certeza!',
      'de': '…Ist immer noch halb Gefühl…! A-aber! D-du gewinnst ganz sicher!',
      'fr': '…Même maintenant, c\'est encore à moitié au feeling… ! M-mais ! T-toi, tu gagnes à coup sûr !',
      'id': '…Sekarang pun setengahnya masih insting…! T-tapi! K-kamu jelas bakal menang!',
      'vi': '…Giờ vẫn còn một nửa là cảm giác…! N-nhưng mà! C-cậu chắc chắn thắng đấy!',
    },
    'sc_w2_3_title': {
      'en': 'Before It Melts!',
      'ko': '녹기 전에!',
      'ja': '溶ける前に！',
      'zh': '化掉之前！',
      'es': '¡Antes de que se derrita!',
      'pt': 'Antes que derreta!',
      'de': 'Bevor sie schmilzt!',
      'fr': 'Avant qu\'il fonde !',
      'id': 'Sebelum Meleleh!',
      'vi': 'Trước khi tan!',
    },
    'sc_w2_3_1': {
      'en': 'One more game before the chocolate melts!',
      'ko': '초콜릿 녹기 전에 한 판 더 하자!',
      'ja': 'チョコが溶ける前にもう一回やろ！',
      'zh': '趁巧克力还没化，再来一局！',
      'es': '¡Una más antes de que se derrita el chocolate!',
      'pt': 'Mais uma antes que o chocolate derreta!',
      'de': 'Noch eine Runde, bevor die Schokolade schmilzt!',
      'fr': 'Encore une partie avant que le chocolat fonde !',
      'id': 'Satu ronde lagi sebelum cokelatnya meleleh!',
      'vi': 'Thêm một ván trước khi sô-cô-la tan!',
    },
    'sc_w2_3_2': {
      'en': 'You said that earlier too.',
      'ko': '아까도 그 말 했잖아.',
      'ja': 'さっきもそれ言ったじゃん。',
      'zh': '你刚才也这么说过。',
      'es': 'Ya dijiste eso hace un rato.',
      'pt': 'Você já disse isso antes.',
      'de': 'Das hast du vorhin auch schon gesagt.',
      'fr': 'T\'as déjà dit ça tout à l\'heure.',
      'id': 'Tadi kamu juga bilang begitu.',
      'vi': 'Nãy cậu cũng nói vậy rồi mà.',
    },
    'sc_w2_3_3': {
      'en': 'The chocolate hasn\'t melted yet! So, one more!',
      'ko': '초콜릿이 아직 안 녹았잖아! 그러니까 한 판 더!',
      'ja': 'チョコまだ溶けてないじゃない！だからもう一回！',
      'zh': '巧克力还没化呢！所以再来一局！',
      'es': '¡El chocolate todavía no se derrite! ¡Así que otra más!',
      'pt': 'O chocolate ainda não derreteu! Então, mais uma!',
      'de': 'Die Schokolade ist noch nicht geschmolzen! Also noch eine!',
      'fr': 'Le chocolat a pas encore fondu ! Donc encore une !',
      'id': 'Cokelatnya belum meleleh, kan! Jadi satu ronde lagi!',
      'vi': 'Sô-cô-la vẫn chưa tan mà! Nên thêm ván nữa!',
    },
    'sc_w2_3_4': {
      'en': 'Are you calculating, or just winging it? Your face is hilarious, lol.',
      'ko': '너 계산하면서 두는 거야? 아니면 막 두는거야? 표정이, ㅋㅋㅋ 웃긴걸?',
      'ja': 'あんた計算しながら打ってるの？それとも適当？顔が、ぷぷっ、ウケるんだけど？',
      'zh': '你是算着下的？还是乱下的？你那表情，哈哈哈，好好笑？',
      'es': '¿Juegas calculando o a lo loco? Tu cara es graciosísima, jajaja.',
