      'pt': 'N-não é nada demais! Qualquer um consegue se souber as regras. …Come mais um biscoito. Não é porque você me elogiou!',
      'de': 'D-das ist nichts Besonderes! Das kann jeder, der die Regeln kennt. …Nimm noch einen Keks. Nicht, weil du mich gelobt hast!',
      'fr': 'C-c\'est rien d\'impressionnant ! N\'importe qui peut le faire en connaissant les règles. …Reprends un cookie. C\'est pas parce que tu m\'as complimentée !',
      'id': 'B-bukan hal hebat, tahu! Siapa pun bisa kalau tahu aturannya …Makan kukis satu lagi. Bukan karena kamu muji, ya!',
      'vi': 'C-có gì giỏi đâu! Ai biết luật cũng làm được hết …Ăn thêm cái bánh quy đi. Không phải vì cậu khen đâu!',
    },
    'sc_w3_3_title': {
      'en': 'Sunset',
      'ko': '노을',
      'ja': '夕焼け',
      'zh': '晚霞',
      'es': 'Atardecer',
      'pt': 'Pôr do sol',
      'de': 'Abendrot',
      'fr': 'Coucher de soleil',
      'id': 'Senja',
      'vi': 'Hoàng hôn',
    },
    'sc_w3_3_1': {
      'en': 'At sunset the classroom is… n-never mind!',
      'ko': '노을 질 때 교실이… 아, 아무것도 아니야!',
      'ja': '夕焼けの教室って… な、なんでもない！',
      'zh': '晚霞里的教室…… 没、没什么！',
      'es': 'El salón al atardecer es… ¡n-nada, olvídalo!',
      'pt': 'A sala no pôr do sol é… n-nada, esquece!',
      'de': 'Bei Sonnenuntergang ist das Klassenzimmer… a-ach, nichts!',
      'fr': 'Au coucher du soleil, la classe est… r-rien, laisse tomber !',
      'id': 'Pas matahari terbenam, kelasnya… b-bukan apa-apa!',
      'vi': 'Lúc hoàng hôn, lớp học… k-không có gì!',
    },
    'sc_w3_3_2': {
      'en': 'You were going to say it\'s pretty, right?',
      'ko': '예쁘다고 하려던 거지?',
      'ja': 'きれいって言おうとしたでしょ？',
      'zh': '是想说很美吧？',
      'es': 'Ibas a decir que es bonito, ¿no?',
      'pt': 'Você ia dizer que é bonita, né?',
      'de': 'Du wolltest sagen, dass es schön ist, oder?',
      'fr': 'Tu allais dire qu\'elle est jolie, non ?',
      'id': 'Mau bilang cantik, kan?',
      'vi': 'Định nói là đẹp đúng không?',
    },
    'sc_w3_3_3': {
      'en': 'Was not! …Half right. HALF!',
      'ko': '아니거든! …반은 맞아. 반만!',
      'ja': '違うし！…半分は当たり。半分だけ！',
      'zh': '才不是！……猜对一半。只有一半！',
      'es': '¡Que no! …Bueno, la mitad. ¡Solo la MITAD!',
      'pt': 'Não ia! …Metade certo. Só METADE!',
      'de': 'Gar nicht! …Halb richtig. Nur HALB!',
      'fr': 'Pas du tout ! …À moitié vrai. À MOITIÉ !',
      'id': 'Bukan! …Setengahnya bener. Setengah aja!',
      'vi': 'Không phải! …Đúng một nửa. Một nửa thôi!',
    },
    'sc_w3_3_4': {
      'en': 'I-I didn\'t plan on watching it with you. That wasn\'t the plan!',
      'ko': '너, 너랑 같이 볼 줄은 몰랐어. 계획에 없었다고!',
      'ja': 'あ、あんたと一緒に見るなんて思ってなかった。予定になかったんだから！',
      'zh': '没、没想到会跟你一起看。不在计划里！',
      'es': 'N-no pensaba verlo contigo. ¡No estaba en mis planes!',
      'pt': 'E-eu não pensei que ia ver com você. Não tava nos planos!',
      'de': 'I-ich hatte nicht vor, das mit dir zusammen anzuschauen. Das war nicht geplant!',
      'fr': 'J-je pensais pas le regarder avec toi. C\'était pas prévu !',
      'id': 'A-aku nggak nyangka bakal lihat bareng kamu. Nggak ada di rencana!',
      'vi': 'T-tớ đâu ngờ sẽ ngắm cùng cậu. Không có trong kế hoạch!',
    },
    'sc_w3_3_5': {
      'en': 'Do you not like it?',
      'ko': '싫어?',
      'ja': '嫌?',
      'zh': '不喜欢吗?',
      'es': '¿No te gusta?',
      'pt': 'Não gosta?',
      'de': 'Ist es dir unangenehm?',
      'fr': 'Ça te dérange ?',
      'id': 'Tidak suka?',
      'vi': 'Không thích à?',
    },
    'sc_w3_3_6': {
      'en': 'I n-never said I hated it… It\'s fine. That much!',
      'ko': '싫, 싫다고는 안 했잖아… 뭐, 괜찮네. 그 정도!',
      'ja': 'い、嫌だなんて言ってないでしょ…まあ、いいんじゃない。それくらい！',
      'zh': '我、我又没说讨厌……嗯，还行吧。就那样！',
      'es': 'N-nunca dije que no me gustara… Está bien. ¡Hasta ahí!',
      'pt': 'E-eu nunca disse que não gostei… Tá bom. Até aí!',
      'de': 'I-ich hab nie gesagt, dass ich\'s nicht mag… Ist okay. So halbwegs!',
      'fr': 'J-j\'ai jamais dit que ça me plaisait pas… C\'est bien. Juste assez !',
      'id': 'A-aku nggak bilang nggak suka, kan… Ya, lumayan. Segitu aja!',
      'vi': 'T-tớ có nói ghét đâu… Ừ thì, cũng được. Chừng đó thôi!',
    },
    'sc_w3_4_title': {
      'en': 'An After-School Promise',
      'ko': '방과후의 약속',
      'ja': '放課後の約束',
      'zh': '放学后的约定',
      'es': 'Una promesa después de clase',
      'pt': 'Uma promessa depois da aula',
      'de': 'Ein Versprechen nach der Schule',
      'fr': 'Une promesse après les cours',
      'id': 'Janji sepulang sekolah',
      'vi': 'Lời hứa sau giờ học',
    },
    'sc_w3_4_1': {
      'en': 'You cleared three rows?! …Nim belongs to you now. Hmph.',
      'ko': '세 줄까지 다 깼어?! …님게임은 이제 네 거네. 흥.',
      'ja': '三列まで全部クリア！？…ニムはもうあんたのものだね。ふん。',
      'zh': '三行也全通关了？！……尼姆现在是你的了。哼。',
      'es': '¡¿Superaste hasta las tres filas?! …El Nim ya es tuyo. Hmpf.',
      'pt': 'Você zerou até as três fileiras?! …O Nim agora é seu. Hmpf.',
      'de': 'Du hast sogar drei Reihen geschafft?! …NIM gehört jetzt dir. Hmpf.',
      'fr': 'T\'as même fini les trois rangées ?! …Le NIM, c\'est à toi maintenant. Pff.',
      'id': 'Tiga baris juga tamat?! …NIM sekarang punyamu. Hmph.',
      'vi': 'Ba hàng cũng phá đảo luôn?! …NIM giờ là của cậu rồi. Hừ.',
    },
    'sc_w3_4_2': {
      'en': 'At first I thought you\'d quit soon. Everyone else did.',
      'ko': '처음엔 금방 그만둘 줄 알았어. 다들 그랬으니까.',
      'ja': '最初はすぐやめると思ってた。みんなそうだったから。',
      'zh': '一开始以为你很快就会放弃。因为大家都是这样。',
      'es': 'Al principio pensé que lo dejarías pronto. Todos lo hicieron.',
      'pt': 'No começo achei que você desistiria logo. Todo mundo desistiu.',
      'de': 'Am Anfang dachte ich, du hörst schnell wieder auf. Alle anderen haben das getan.',
      'fr': 'Au début je pensais que t\'abandonnerais vite. Tout le monde l\'a fait.',
      'id': 'Awalnya kukira kamu akan cepat berhenti. Soalnya semua orang begitu.',
      'vi': 'Lúc đầu tôi nghĩ cậu sẽ bỏ cuộc sớm. Vì ai cũng vậy cả.',
    },
    'sc_w3_4_3': {
      'en': 'Everyone?',
      'ko': '다들?',
      'ja': 'みんな?',
      'zh': '大家?',
      'es': '¿Todos?',
      'pt': 'Todo mundo?',
      'de': 'Alle?',
      'fr': 'Tout le monde ?',
      'id': 'Semua orang?',
      'vi': 'Ai cũng vậy?',
    },
    'sc_w3_4_4': {
      'en': 'Once I explained the rules, they all said it was boring and left. But y-you came every day. Even when you lost!',
      'ko': '규칙 알려주면 재미없다고 다 가더라. 근데 너, 너는 매일 왔잖아. 지는 날에도!',
      'ja': 'ルールを教えると、つまんないってみんな帰っちゃうの。でもあ、あんたは毎日来たじゃない。負けた日も！',
      'zh': '我一讲规则，大家就说无聊走掉了。可、可你每天都来。输了的日子也来！',
      'es': 'Cuando explicaba las reglas, todos decían que era aburrido y se iban. Pero t-tú viniste todos los días. ¡Hasta cuando perdías!',
      'pt': 'Quando eu explicava as regras, todo mundo achava chato e ia embora. Mas v-você veio todo dia. Até quando perdia!',
      'de': 'Wenn ich die Regeln erklärt hab, fanden\'s alle langweilig und sind gegangen. Aber d-du bist jeden Tag gekommen. Sogar wenn du verloren hast!',
      'fr': 'Dès que j\'expliquais les règles, tout le monde trouvait ça nul et partait. Mais t-toi, tu revenais tous les jours. Même quand tu perdais !',
      'id': 'Begitu kujelasin aturannya, semua bilang nggak seru terus pergi. Tapi k-kamu datang tiap hari. Bahkan pas kalah!',
      'vi': 'Tớ giảng luật xong là ai cũng chê chán rồi bỏ đi. Nhưng c-cậu thì ngày nào cũng đến. Cả hôm thua!',
    },
    'sc_w3_4_5': {
      'en': 'There were more days I lost.',
      'ko': '지는 날이 더 많았지.',
      'ja': '負ける日の方が多かったよ。',
      'zh': '输的日子更多呢。',
      'es': 'Hubo más días de derrota, la verdad.',
      'pt': 'Teve mais dias que eu perdi, na verdade.',
      'de': 'Es gab eher mehr Tage, an denen ich verloren hab.',
      'fr': 'Y avait plus de jours où je perdais, en fait.',
      'id': 'Hari-hari aku kalah malah lebih banyak.',
      'vi': 'Ngày thua còn nhiều hơn ấy chứ.',
    },
    'sc_w3_4_6': {
      'en': 'Th-that\'s the MOST annoying part! Losing and coming back smiling. I can\'t do that.',
      'ko': '그, 그게 제일 짜증나! 지고도 웃으면서 다시 오는 거. 나는 그거 못 하거든.',
      'ja': 'そ、それが一番ムカつくの！負けても笑ってまた来るとこ。私にはそれ、できないから。',
      'zh': '那、那才最气人！输了还笑着再来。我可做不到。',
      'es': '¡E-eso es lo que MÁS me molesta! Perder y volver sonriendo. Yo no puedo hacer eso.',
      'pt': 'I-isso é o que MAIS me irrita! Perder e voltar sorrindo. Eu não consigo fazer isso.',
      'de': 'D-das nervt am MEISTEN! Verlieren und lächelnd wiederkommen. Das kann ich nicht.',
      'fr': 'C-c\'est ça le PLUS énervant ! Perdre et revenir en souriant. Moi, j\'y arrive pas.',
      'id': 'I-itu yang paling nyebelin! Kalah tapi balik lagi sambil senyum. Aku nggak bisa begitu.',
      'vi': 'Đ-đó mới là cái đáng ghét nhất! Thua mà vẫn cười rồi quay lại. Tớ không làm được thế.',
    },
    'sc_w3_4_7': {
      'en': 'I borrowed the library key. For tonight! The stick game needs somewhere quiet.',
      'ko': '도서관 열쇠 빌렸어. 밤에! 막대과자 게임은 조용한 데서 해야 하니까.',
      'ja': '図書館の鍵、借りたよ。夜に！スティック菓子ゲームは静かなところでやらなきゃだから。',
      'zh': '我借了图书馆的钥匙。晚上用！饼干棒游戏得在安静的地方玩。',
      'es': 'Pedí prestada la llave de la biblioteca. ¡Para esta noche! El juego del palito hay que jugarlo en un lugar tranquilo.',
      'pt': 'Peguei emprestada a chave da biblioteca. Pra hoje à noite! O jogo do palito tem que ser num lugar quieto.',
      'de': 'Ich hab den Bibliotheksschlüssel ausgeliehen. Für heute Abend! Das Keksstangen-Spiel braucht Ruhe.',
      'fr': 'J\'ai emprunté la clé de la bibliothèque. Pour ce soir ! Le jeu du bâtonnet, ça se joue au calme.',
      'id': 'Aku pinjam kunci perpustakaan. Buat malam! Permainan Stik harus dimainin di tempat yang tenang.',
      'vi': 'Tớ mượn chìa khóa thư viện rồi. Buổi tối! Trò que bánh phải chơi chỗ yên tĩnh.',
    },
    'sc_w3_4_8': {
      'en': 'At night?',
      'ko': '밤에?',
      'ja': '夜に?',
      'zh': '晚上?',
      'es': '¿De noche?',
      'pt': 'De noite?',
      'de': 'Abends?',
      'fr': 'Le soir ?',
      'id': 'Malam hari?',
      'vi': 'Buổi tối à?',
    },
    'sc_w3_4_9': {
      'en': 'The librarian said it\'s okay if there\'s two of us. D-don\'t get the wrong idea! It\'s a rule!',
      'ko': '사서 선생님이 둘이면 괜찮대. 오, 오해하지 마! 규칙이 그렇대!',
      'ja': '司書の先生が二人ならいいって。か、勘違いしないでよ！そういう決まりなの！',
      'zh': '图书管理员老师说两个人就可以。别、别误会！是规定！',
      'es': 'La bibliotecaria dijo que si somos dos está bien. ¡N-no te hagas ideas raras! ¡Es la regla!',
      'pt': 'A bibliotecária disse que tudo bem se formos dois. N-não pensa besteira! É a regra!',
      'de': 'Die Bibliothekarin sagt, zu zweit ist es okay. V-versteh das nicht falsch! Das ist die Regel!',
      'fr': 'La bibliothécaire dit que c\'est bon si on est deux. V-va pas te faire des idées ! C\'est le règlement !',
      'id': 'Kata pustakawan, berdua boleh. J-jangan salah paham! Aturannya gitu!',
      'vi': 'Cô thủ thư bảo hai người thì được. Đ-đừng hiểu lầm! Luật vậy đó!',
    },
    'sc_w3_4_10': {
      'en': 'Are you asking me to go together?',
      'ko': '같이 가자는 거야?',
      'ja': '一緒に行こうってこと?',
      'zh': '是叫我一起去吗?',
      'es': '¿Me estás pidiendo que vayamos juntos?',
      'pt': 'Está me chamando pra irmos juntos?',
      'de': 'Fragst du mich, ob wir zusammen hingehen?',
      'fr': 'Tu me demandes d\'y aller ensemble ?',
      'id': 'Maksudnya ajak aku pergi bersama?',
      'vi': 'Ý cậu là rủ tôi đi cùng à?',
    },
    'sc_w3_4_11': {
      'en': '…I\'m not saying it twice. I-idiot.',
      'ko': '…두 번 말 안 해. 바, 바보야.',
      'ja': '…二回は言わない。バ、バカ。',
      'zh': '……我不说第二遍。笨、笨蛋。',
      'es': '…No lo voy a repetir. I-idiota.',
      'pt': '…Não vou repetir. I-idiota.',
      'de': '…Ich sag\'s nicht zweimal. I-Idiot.',
      'fr': '…Je le répéterai pas. I-idiot.',
      'id': '…Nggak bakal kuulang. B-bodoh.',
      'vi': '…Tớ không nói lần hai đâu. Đ-đồ ngốc.',
    },
    'sc_w3_4_12': {
      'en': 'I\'ll bring cookies. Eat them quietly in the library, got it?',
      'ko': '쿠키는 챙겨 갈게. 도서관에선 소리 안 나게 먹어야 돼, 알았지?',
      'ja': 'クッキーは持ってくね。図書館では音を立てずに食べるんだよ、わかった？',
      'zh': '饼干我会带上。在图书馆要吃得没声音，知道吗？',
      'es': 'Llevaré galletas. En la biblioteca hay que comerlas sin hacer ruido, ¿entendido?',
      'pt': 'Vou levar biscoitos. Na biblioteca tem que comer sem fazer barulho, entendeu?',
      'de': 'Ich bring Kekse mit. In der Bibliothek isst du sie aber leise, verstanden?',
      'fr': 'J\'apporte des cookies. À la bibliothèque, on les mange sans bruit, compris ?',
      'id': 'Kukisnya aku bawa. Di perpustakaan makannya jangan berisik, ngerti?',
      'vi': 'Tớ sẽ mang bánh quy. Ở thư viện phải ăn không ra tiếng, hiểu chưa?',
    },
    'sc_w4_1_title': {
      'en': 'Quietly',
      'ko': '조용히',
      'ja': '静かに',
      'zh': '安静点',
      'es': 'En silencio',
      'pt': 'Em silêncio',
      'de': 'Leise',
      'fr': 'En silence',
      'id': 'Diam-diam',
      'vi': 'Im lặng',
    },
    'sc_w4_1_1': {
      'en': 'Shh! Be quiet in the library.',
      'ko': '쉿! 도서관에선 조용히 해.',
      'ja': 'しっ！図書館では静かに。',
      'zh': '嘘！图书馆里要安静。',
      'es': '¡Shh! En la biblioteca se guarda silencio.',
      'pt': 'Shh! Na biblioteca, silêncio.',
      'de': 'Pssst! In der Bibliothek ist man leise.',
      'fr': 'Chut ! On se tait, à la bibliothèque.',
      'id': 'Ssst! Di perpustakaan harus tenang.',
      'vi': 'Suỵt! Trong thư viện phải im lặng.',
    },
    'sc_w4_1_2': {
      'en': 'Hard to win quietly.',
      'ko': '이기면서 조용하기 어려운데.',
      'ja': '勝ちながら静かにするのは難しいけど。',
      'zh': '赢着还要安静,有点难吧。',
      'es': 'Es difícil ganar en silencio.',
      'pt': 'É difícil vencer em silêncio.',
      'de': 'Schwer, beim Gewinnen leise zu sein.',
      'fr': 'C\'est dur de gagner en silence.',
      'id': 'Susah menang sambil diam.',
      'vi': 'Vừa thắng vừa im lặng khó lắm.',
    },
    'sc_w4_1_3': {
      'en': 'Then lose quietly!',
      'ko': '그럼 조용히 지든가!',
      'ja': 'じゃあ静かに負けなさいよ！',
      'zh': '那就安静地输吧！',
      'es': '¡Entonces pierde en silencio!',
      'pt': 'Então perde em silêncio!',
      'de': 'Dann verlier halt leise!',
      'fr': 'Alors perds en silence !',
      'id': 'Kalau gitu kalah aja diam-diam!',
      'vi': 'Vậy thì thua trong im lặng đi!',
    },
    'sc_w4_1_4': {
      'en': '…J-just kidding. But the librarian was smiling at us, right?',
      'ko': '…노, 농담이야. 근데 사서 선생님이 우리 보고 웃으시던데?',
      'ja': '…じょ、冗談だよ。でも司書の先生、私たち見て笑ってなかった？',
      'zh': '……开、开玩笑的。不过图书管理员老师看着我们在笑哦？',
      'es': '…E-es broma. Pero la bibliotecaria se reía al vernos, ¿no?',
      'pt': '…É-é brincadeira. Mas a bibliotecária sorriu pra gente, né?',
      'de': '…W-war nur Spaß. Aber die Bibliothekarin hat uns angelächelt, oder?',
      'fr': '…J-je rigole. Mais la bibliothécaire nous a souri, non ?',
      'id': '…B-bercanda. Tapi pustakawannya senyum-senyum lihat kita, deh?',
      'vi': '…Đ-đùa thôi. Mà cô thủ thư nhìn tụi mình cười kìa?',
    },
    'sc_w4_1_5': {
      'en': 'Why would she be smiling?',
      'ko': '왜 웃으실까.',
      'ja': 'どうして笑うんだろう。',
      'zh': '为什么会笑呢。',
      'es': '¿Por qué sonreiría?',
      'pt': 'Por que ela estaria sorrindo?',
      'de': 'Warum lächelt sie wohl?',
      'fr': 'Pourquoi elle sourirait ?',
      'id': 'Kenapa ya dia tersenyum.',
      'vi': 'Sao cô lại cười nhỉ.',
    },
    'sc_w4_1_6': {
      'en': 'I-I don\'t know! What\'s so funny! …I\'m NOT blushing.',
      'ko': '모, 몰라! 뭐가 웃긴데! …얼굴 빨개진 거 아니거든.',
      'ja': 'し、知らない！何がおかしいのよ！…顔赤くなんかなってないし。',
      'zh': '不、不知道！有什么好笑的！……我脸才没红。',
      'es': '¡N-no sé! ¡¿Qué tiene de gracioso?! …NO estoy sonrojada.',
