    'sc_w4_2_3': {
      'en': 'Alone. Here. At night. …I wasn\'t lonely!',
      'ko': '혼자서. 여기서. 밤에. …외로웠던 거 아니야!',
      'ja': '一人で。ここで。夜に。…寂しかったわけじゃないから！',
