      'fr': 'Mais toi, en dix parties… J-j\'ai décidé de plus m\'étonner !',
      'id': 'Tapi kamu cuma butuh sepuluh ronde… A-aku udah mutusin buat nggak kaget lagi!',
      'vi': 'Thế mà cậu chỉ mất mười ván… T-tớ quyết định không ngạc nhiên nữa!',
