    },
    'sc_w4_2_6': {
      'en': 'No! …I\'ll save you a stick. It has nothing to do with the match. Really!',
      'ko': '싫어! …막대과자 하나 남겨둘게. 승부랑은 상관없는 거야. 진짜로!',
