    'sc_w4_3_4': {
      'en': '…It\'s dark out, so walk with me. You\'d get lost on your own!',
      'ko': '…밤길 어두우니까 같이 가. 너 혼자 가면 길 잃을 것 같으니까!',
      'ja': '…夜道暗いから一緒に帰ろ。あんた一人だと迷いそうだし！',
      'zh': '……夜路黑，一起走吧。你一个人怕是会迷路！',
      'es': '…Afuera está oscuro, así que vamos juntos. ¡Sin mí te pierdes!',
      'pt': '…Tá escuro lá fora, então vamos juntos. Sem mim você se perde!',
      'de': '…Draußen ist es dunkel, also gehen wir zusammen. Allein verläufst du dich sonst noch!',
      'fr': '…Il fait nuit dehors, alors on rentre ensemble. Sans moi, tu vas te perdre !',
      'id': '…Jalanan malam gelap, jadi pulang bareng. Kalau sendiri, kamu pasti nyasar!',
