    'sc_w4_3_5': {
      'en': 'Worried about me?',
      'ko': '걱정돼서?',
      'ja': '心配なの?',
      'zh': '是担心我吗?',
      'es': '¿Te preocupas por mí?',
      'pt': 'Preocupada comigo?',
      'de': 'Machst du dir Sorgen?',
      'fr': 'Tu t\'inquiètes pour moi ?',
      'id': 'Khawatir sama aku?',
      'vi': 'Lo cho tớ à?',
    },
    'sc_w4_3_6': {
      'en': 'W-worried?! As if! It\'d be a problem if my rival got hurt. Th-that\'s all!',
      'ko': '걱, 걱정은 무슨! 대결 상대가 다치면 곤란하니까. 그, 그것뿐이야!',
      'ja': 'し、心配なんかしてないし！勝負の相手がケガしたら困るから。そ、それだけ！',
      'zh': '担、担心什么啊！对手受伤的话我会很困扰。就、就这样而已！',
      'es': '¡¿P-preocupada?! ¡Para nada! Sería un problema que mi rival se lastimara. ¡E-eso es todo!',
      'pt': 'P-preocupada?! Até parece! Se você se machucar, quem vai jogar comigo? S-só isso!',
