    'sc_w5_1_3': {
      'en': 'I-I did! So I\'m the cheater… hmph.',
      'ko': '그, 그랬지! 그럼 반칙은 내가 한 거네… 흥.',
      'ja': 'そ、そうだった！じゃあ反則したのは私か…ふん。',
      'zh': '是、是我说的！那犯规的是我啊……哼。',
