    },
    'sc_w5_1_5': {
      'en': 'You watched?',
      'ko': '봤어?',
      'ja': '見てたの?',
      'zh': '你看了?',
      'es': '¿Me viste?',
      'pt': 'Me viu?',
      'de': 'Du hast zugesehen?',
      'fr': 'Tu regardais ?',
      'id': 'Kamu lihat?',
      'vi': 'Cậu thấy à?',
    },
    'sc_w5_1_6': {
      'en': 'I-I just happened to see! …But your head is fast. That\'s enough.',
      'ko': '우, 우연히 본 거야! …근데 머리는 빠르네. 그거면 됐어.',
      'ja': 'ぐ、偶然見ただけ！…でも頭は速いね。それでいいよ。',
      'zh': '偶、偶然看到的！……不过脑子挺快。这就够了。',
      'es': '¡L-lo vi por casualidad! …Pero tu cabeza es rápida. Con eso basta.',
      'pt': 'E-eu vi por acaso! …Mas sua cabeça é rápida. Isso basta.',
      'de': 'D-das hab ich nur zufällig gesehen! …Aber dein Kopf ist schnell. Das reicht.',
      'fr': 'J-je l\'ai vu par hasard ! …Mais ta tête, elle est rapide. Ça suffit.',
