      'id': 'Kenangan',
      'vi': 'Ký ức',
    },
    'sc_w5_2_1': {
      'en': 'Remember the rooftop? Two rows!',
      'ko': '옥상에서 한 거 기억나? 두 줄!',
      'ja': '屋上でやったの覚えてる？二列！',
