      'es': '¿Te acuerdas de la azotea? ¡Dos filas!',
      'pt': 'Lembra do terraço? Duas fileiras!',
      'de': 'Weißt du noch, auf dem Dach? Zwei Reihen!',
      'fr': 'Tu te souviens du toit ? Deux rangées !',
      'id': 'Ingat yang di atap? Dua baris!',
      'vi': 'Nhớ hồi trên sân thượng không? Hai hàng đó!',
    },
    'sc_w5_2_2': {
      'en': 'I remember. It was windy that day.',
      'ko': '기억나. 바람 부는 날.',
      'ja': '覚えてる。風が吹いてた日。',
      'zh': '记得。刮风那天。',
      'es': 'Lo recuerdo. Fue un día ventoso.',
      'pt': 'Lembro. Foi um dia de vento.',
      'de': 'Ich erinnere mich. Ein windiger Tag.',
      'fr': 'Je m\'en souviens. C\'était un jour venteux.',
      'id': 'Ingat. Hari itu berangin.',
      'vi': 'Nhớ chứ. Hôm đó trời có gió.',
    },
    'sc_w5_2_3': {
      'en': 'You r-remember?! That day?',
      'ko': '기억, 기억난다고?! 그날을?',
      'ja': 'お、覚えてるって！？あの日のこと？',
      'zh': '记、记得？！那天的事？',
      'es': '¡¿T-te acuerdas?! ¿De ese día?',
      'pt': 'V-você lembra?! Daquele dia?',
      'de': 'D-du erinnerst dich?! An den Tag?',
      'fr': 'T-tu t\'en souviens ?! De ce jour-là ?',
      'id': 'I-ingat?! Hari itu?',
      'vi': 'C-cậu nhớ á?! Hôm đó?',
    },
    'sc_w5_2_4': {
      'en': '…It wasn\'t windy that day. Idiot.',
      'ko': '…바람 없는 날이었는데. 바보.',
      'ja': '…風のない日だったのに。バカ。',
      'zh': '……那天明明没风。笨蛋。',
      'es': '…Ese día no había viento. Idiota.',
      'pt': '…Naquele dia não ventava. Idiota.',
      'de': '…An dem Tag war gar kein Wind. Idiot.',
      'fr': '…Ce jour-là, y avait pas de vent. Idiot.',
      'id': '…Padahal hari itu nggak ada angin. Bodoh.',
      'vi': '…Hôm đó làm gì có gió. Đồ ngốc.',
    },
    'sc_w5_2_5': {
      'en': 'You\'re nitpicking too.',
      'ko': '너도 따지네.',
      'ja': 'そっちも細かいね。',
      'zh': '你也挺爱较真的嘛。',
      'es': 'Tú también eres quisquillosa.',
      'pt': 'Você também é exigente, hein.',
      'de': 'Du bist auch pingelig.',
      'fr': 'Toi aussi tu chipotes.',
      'id': 'Kamu juga suka mempermasalahkan detail ya.',
      'vi': 'Cậu cũng hay bắt bẻ ghê.',
    },
    'sc_w5_2_6': {
      'en': 'I-I said don\'t nitpick! Have another macaron. For remembering.',
      'ko': '따, 따지지 말라니까! 마카롱 하나 더 먹어. 기억해준 값이야.',
      'ja': 'つ、突っ込むなって言ったでしょ！マカロンもう一個食べな。覚えててくれたお礼。',
      'zh': '都、都说了别较真！再吃一个马卡龙。算是记得那天的谢礼。',
      'es': '¡Que no discutas, d-dije! Cómete otro macaron. Es el pago por acordarte.',
      'pt': 'E-eu disse pra não discutir! Come mais um macaron. É o pagamento por lembrar.',
      'de': 'I-ich hab gesagt, du sollst nicht nachbohren! Nimm noch ein Macaron. Fürs Erinnern.',
      'fr': 'J-je t\'ai dit de pas chipoter ! Reprends un macaron. Pour ta bonne mémoire.',
      'id': 'U-udah kubilang jangan dipermasalahin! Makan macaron satu lagi. Bayaran karena udah ingat.',
      'vi': 'Đ-đã bảo đừng bắt bẻ mà! Ăn thêm cái macaron đi. Tiền công vì nhớ đấy.',
