      'id': 'Pengakuan',
      'vi': 'Thừa nhận',
    },
    'sc_w5_3_1': {
      'en': 'That\'s the first time I\'ve admitted anything. W-write it down!',
      'ko': '내가 인정한다고 한 거 처음이야. 기, 기록해둬!',
      'ja': '私が認めるって言ったの、初めてだよ。き、記録しといて！',
      'zh': '这是我第一次说认可你。记、记下来！',
      'es': 'Es la primera vez que admito algo así. ¡A-anótalo!',
      'pt': 'É a primeira vez que eu admito algo. A-anota aí!',
      'de': 'Das ist das erste Mal, dass ich was zugebe. S-schreib\'s dir auf!',
      'fr': 'C\'est la première fois que j\'admets quelque chose. N-note-le !',
      'id': 'Baru kali ini aku bilang ngakuin. C-catat, ya!',
      'vi': 'Lần đầu tớ nói công nhận đó. G-ghi lại đi!',
    },
    'sc_w5_3_2': {
      'en': 'Admitted what?',
      'ko': '뭘 인정하는데?',
      'ja': '何を認めるの?',
      'zh': '承认什么?',
      'es': '¿Admites qué?',
      'pt': 'Admite o quê?',
      'de': 'Was gibst du zu?',
      'fr': 'Tu admets quoi ?',
      'id': 'Mengakui apa?',
      'vi': 'Thừa nhận gì cơ?',
    },
    'sc_w5_3_3': {
      'en': '…Your skill. A little! A TINY bit!',
      'ko': '…네 실력. 조금! 아주 조금!',
      'ja': '…あんたの実力。ちょっと！ほんのちょっと！',
      'zh': '……你的实力。一点点！就一点点！',
      'es': '…Tu habilidad. ¡Un poco! ¡Muy POQUITO!',
      'pt': '…Sua habilidade. Um pouco! Bem POUQUINHO!',
      'de': '…Dein Können. Ein bisschen! Ein KLITZEKLEINES bisschen!',
      'fr': '…Ton niveau. Un peu ! Un TOUT petit peu !',
      'id': '…Skill-mu. Dikit! Dikit banget!',
      'vi': '…Thực lực của cậu. Chút thôi! Chút xíu thôi!',
    },
    'sc_w5_3_4': {
      'en': 'N-no. Don\'t write it down. I take it back!',
      'ko': '아, 아니. 기록하지 마. 방금 건 취소!',
      'ja': 'や、やっぱり。記録しないで。今のは取り消し！',
      'zh': '不、不对。别记。刚才的取消！',
      'es': 'N-no. No lo anotes. ¡Lo que dije no cuenta!',
      'pt': 'N-não. Não anota. Retiro o que eu disse!',
      'de': 'N-nein. Schreib\'s nicht auf. Das nehm ich zurück!',
      'fr': 'N-non. Le note pas. Je retire ce que j\'ai dit !',
      'id': 'E-eh, nggak. Jangan dicatat. Yang barusan batal!',
      'vi': 'K-không. Đừng ghi. Câu vừa rồi hủy!',
    },
    'sc_w5_3_5': {
      'en': 'I already heard it.',
      'ko': '이미 들었는데.',
      'ja': 'もう聞いちゃったけど。',
      'zh': '已经听到了。',
      'es': 'Ya lo escuché.',
      'pt': 'Já ouvi, viu.',
      'de': 'Hab\'s schon gehört.',
      'fr': 'Je l\'ai déjà entendu.',
      'id': 'Aku udah dengar duluan.',
      'vi': 'Tớ nghe thấy rồi mà.',
    },
    'sc_w5_3_6': {
      'en': 'Can\'t help that you heard it! Just don\'t write it. Okay?',
      'ko': '들은 건 어쩔 수 없고! 적지만 마. 알았지?',
      'ja': '聞いちゃったのは仕方ないけど！書かないでよ。わかった？',
      'zh': '听到了就算了！别写下来。知道吗？',
      'es': '¡Que lo hayas oído ya no tiene remedio! Solo no lo escribas. ¿Va?',
