      'de': 'Dass du\'s gehört hast, kann ich nicht ändern! Schreib\'s bloß nicht auf. Okay?',
      'fr': 'Que tu l\'aies entendu, j\'y peux rien ! Mais l\'écris pas. D\'accord ?',
      'id': 'Udah kedengeran ya mau gimana lagi! Asal jangan ditulis. Ngerti?',
