    'sc_w5_4_1': {
      'en': 'Kayles, done. Your head\'s… faster than mine now. I\'ll admit it.',
      'ko': '카일즈 끝. 머리는… 이제 너가 나보다 빨라. 인정할게.',
      'ja': 'ケイルズ終わり。頭は…もうあんたのほうが私より速い。認める。',
      'zh': '凯尔斯结束。脑子……你现在比我快了。我承认。',
      'es': 'Kayles, terminado. Tu cabeza… ya es más rápida que la mía. Lo admito.',
