      'ko': '…과학실로 와. 황금비 얘기 해줄게.',
      'ja': '…理科室に来て。黄金比の話してあげる。',
      'zh': '……来理科教室。给你讲黄金比例。',
      'es': '…Ven al laboratorio. Te voy a hablar de la proporción áurea.',
      'pt': '…Vem pro laboratório. Vou te contar sobre a proporção áurea.',
      'de': '…Komm in den Chemieraum. Ich erzähl dir was vom Goldenen Schnitt.',
      'fr': '…Viens au labo de sciences. Je vais te parler du nombre d\'or.',
      'id': '…Datang ke lab sains. Nanti kuceritain soal rasio emas.',
      'vi': '…Đến phòng thí nghiệm đi. Tớ kể cho nghe về tỷ lệ vàng.',
    },
    'sc_w5_4_12': {
      'en': 'Today\'s the last macaron. Next is donuts! You can look forward to it.',
      'ko': '마카롱은 오늘이 마지막이야. 다음은 도넛! 기대해도 되고.',
      'ja': 'マカロンは今日で最後。次はドーナツ！期待してもいいよ。',
      'zh': '马卡龙今天是最后一次。下次是甜甜圈！可以期待哦。',
      'es': 'Hoy es el último macaron. ¡Lo siguiente son donas! Puedes ilusionarte.',
      'pt': 'Hoje é o último macaron. Depois vêm as rosquinhas! Pode ficar na expectativa.',
      'de': 'Heute gibt\'s die letzten Macarons. Als Nächstes Donuts! Darfst dich drauf freuen.',
      'fr': 'Aujourd\'hui, c\'est les derniers macarons. Ensuite, des donuts ! Tu peux avoir hâte.',
      'id': 'Macaron cuma sampai hari ini. Berikutnya donat! Boleh kok berharap.',
      'vi': 'Macaron hôm nay là cuối. Lần sau là bánh donut! Cứ mong chờ đi.',
    },
