    'sc_w6_1_4': {
      'en': 'Know the golden ratio? 1.618. Bet you didn\'t!',
      'ko': '황금비 알아? 1.618. 몰랐지?',
      'ja': '黄金比って知ってる？1.618。知らなかったでしょ？',
      'zh': '知道黄金比例吗？1.618。不知道吧？',
      'es': '¿Conoces la proporción áurea? 1.618. ¡A que no sabías!',
      'pt': 'Conhece a proporção áurea? 1,618. Aposto que não sabia!',
