      'id': 'Pernah dengar sih.',
      'vi': 'Có nghe qua.',
    },
    'sc_w6_1_6': {
      'en': 'Nature\'s favorite number. …Mine too. The NUMBER, I mean!',
      'ko': '자연이 좋아하는 숫자야. …나도 좋아하고. 숫자 얘기야!',
      'ja': '自然が好きな数なの。…私も好き。数の話だからね！',
      'zh': '是大自然喜欢的数字。……我也喜欢。说的是数字！',
      'es': 'Es el número favorito de la naturaleza. …El mío también. ¡El NÚMERO, digo!',
      'pt': 'É o número favorito da natureza. …O meu também. O NÚMERO, quero dizer!',
      'de': 'Die Lieblingszahl der Natur. …Meine auch. Die ZAHL, mein ich!',
      'fr': 'Le nombre préféré de la nature. …Le mien aussi. Le NOMBRE, hein !',
      'id': 'Angka kesukaan alam. …Aku juga suka. Angkanya, maksudku!',
      'vi': 'Con số thiên nhiên thích nhất. …Tớ cũng thích. Ý tớ là con số!',
