    'sc_w6_2_1': {
      'en': 'Sunflower seeds, seashell spirals. All golden ratio. Cool, right?',
      'ko': '해바라기 씨, 조개껍데기 나선. 전부 황금비야. 신기하지?',
      'ja': 'ひまわりの種、貝殻のらせん。全部黄金比。すごいでしょ？',
      'zh': '向日葵的种子，贝壳的螺旋。全是黄金比例。神奇吧？',
      'es': 'Semillas de girasol, espirales de caracolas. Todo es proporción áurea. Increíble, ¿no?',
      'pt': 'Sementes de girassol, espirais de conchas. Tudo proporção áurea. Incrível, né?',
      'de': 'Sonnenblumenkerne, Muschelspiralen. Alles Goldener Schnitt. Cool, oder?',
