    'sc_w6_2_3': {
      'en': 'Yeah. There\'s a pretty number hidden in this game too.',
      'ko': '응. 이 게임에도 예쁜 숫자가 숨어 있어.',
      'ja': 'うん。このゲームにもきれいな数が隠れてるの。',
      'zh': '嗯。这个游戏里也藏着漂亮的数字。',
      'es': 'Sí. En este juego también hay un número bonito escondido.',
