      'ko': '예쁘네.',
      'ja': 'きれいだね。',
      'zh': '挺漂亮的。',
      'es': 'Qué bonito.',
      'pt': 'Que bonito.',
      'de': 'Schön.',
      'fr': 'C\'est joli.',
      'id': 'Indah ya.',
      'vi': 'Đẹp thật.',
