    'sc_w6_3_1': {
      'en': 'Like a donut hole, your logic has a gap…!',
      'ko': '도넛 구멍처럼 네 논리엔 빈틈이…!',
      'ja': 'ドーナツの穴みたいに、あんたの論理には隙が…！',
      'zh': '就像甜甜圈的洞，你的逻辑也有漏洞……！',
      'es': '¡Como el agujero de una dona, tu lógica tiene un hueco…!',
