    'sc_w6_3_5': {
      'en': 'Looking forward to it?',
      'ko': '기대하는 거야?',
      'ja': '楽しみにしてるの?',
      'zh': '你在期待吗?',
      'es': '¿Lo estás esperando con ganas?',
      'pt': 'Está ansiosa por isso?',
      'de': 'Freust du dich schon darauf?',
      'fr': 'Tu as hâte ?',
      'id': 'Kamu menantikannya?',
      'vi': 'Cậu mong chờ điều đó à?',
    },
    'sc_w6_3_6': {
      'en': 'L-looking forward?! As if! …I just like finding gaps. Especially yours.',
      'ko': '기, 기대는 무슨! …빈틈 찾는 걸 좋아할 뿐이야. 네 거는 특히.',
      'ja': 'き、期待なんかしてない！…隙を探すのが好きなだけ。あんたのは特にね。',
      'zh': '期、期待什么啊！……我只是喜欢找漏洞。尤其是你的。',
      'es': '¡¿I-ilusionada?! ¡Para nada! …Solo me gusta encontrar huecos. Sobre todo los tuyos.',
      'pt': 'N-na expectativa?! Até parece! …Eu só gosto de achar brechas. Principalmente as suas.',
      'de': 'F-freuen?! Von wegen! …Ich such halt gern Lücken. Vor allem deine.',
      'fr': 'H-hâte ?! N\'importe quoi ! …J\'aime juste chercher les failles. Surtout les tiennes.',
      'id': 'N-nungguin apaan! …Aku cuma suka nyari celah. Apalagi punyamu.',
      'vi': 'M-mong chờ gì chứ! …Tớ chỉ thích tìm kẽ hở thôi. Nhất là của cậu.',
    },
    'sc_w6_4_title': {
      'en': 'Numbers in the Science Lab',
      'ko': '과학실의 숫자',
      'ja': '理科室の数字',
      'zh': '科学教室的数字',
      'es': 'Números en el laboratorio de ciencias',
      'pt': 'Números no laboratório de ciências',
      'de': 'Zahlen im Wissenschaftsraum',
      'fr': 'Les nombres dans le labo',
      'id': 'Angka di Ruang Sains',
      'vi': 'Những con số trong phòng khoa học',
    },
    'sc_w6_4_1': {
      'en': 'You cleared Wythoff too?! You learned the golden ratio by hand. Hmph.',
      'ko': '위토프까지 다 깼어?! 황금비를 손으로 익힌 거네. 흥.',
      'ja': 'ウィトフまで全部クリア！？黄金比を手で覚えたってことね。ふん。',
      'zh': '威佐夫也全通关了？！你是用手学会了黄金比例啊。哼。',
      'es': '¡¿Superaste hasta Wythoff?! Aprendiste la proporción áurea a pura práctica. Hmpf.',
      'pt': 'Você zerou até o Wythoff?! Aprendeu a proporção áurea na prática. Hmpf.',
      'de': 'Du hast sogar Wythoff geschafft?! Den Goldenen Schnitt hast du dir mit den Händen beigebracht. Hmpf.',
      'fr': 'T\'as même fini Wythoff ?! T\'as appris le nombre d\'or à la main. Pff.',
      'id': 'Wythoff juga tamat?! Kamu belajar rasio emas pakai tangan. Hmph.',
      'vi': 'Wythoff cũng phá đảo luôn?! Cậu học tỷ lệ vàng bằng tay đấy. Hừ.',
    },
    'sc_w6_4_2': {
      'en': 'Numbers were always easier for me than people. Numbers don\'t betray you.',
      'ko': '나는 숫자가 사람보다 편했어. 숫자는 배신 안 하니까.',
      'ja': '私は人より数字の方が楽だった。数字は裏切らないから。',
      'zh': '比起人,我觉得数字更让我安心。因为数字不会背叛。',
      'es': 'Para mí, los números siempre fueron más fáciles que las personas. Los números no traicionan.',
      'pt': 'Pra mim, números sempre foram mais fáceis que pessoas. Números não traem.',
      'de': 'Zahlen waren mir immer leichter als Menschen. Zahlen verraten einen nicht.',
      'fr': 'Les nombres m\'ont toujours été plus faciles que les gens. Les nombres ne trahissent pas.',
      'id': 'Bagiku, angka selalu lebih mudah daripada orang. Angka nggak berkhianat.',
      'vi': 'Với tớ, số dễ chịu hơn người. Vì số không phản bội.',
    },
    'sc_w6_4_3': {
      'en': 'Do people betray you?',
      'ko': '사람은 배신해?',
      'ja': '人は裏切るの?',
      'zh': '人会背叛吗?',
      'es': '¿Las personas traicionan?',
      'pt': 'Pessoas traem?',
      'de': 'Verraten Menschen dich?',
      'fr': 'Les gens trahissent ?',
      'id': 'Orang berkhianat?',
      'vi': 'Người phản bội à?',
    },
    'sc_w6_4_4': {
      'en': 'Hmph. Everyone says they love puzzles, but not games… that stung a bit.',
      'ko': '흥. 다들 퍼즐 좋아한다더니 게임은 안 좋아하고… 좀 그랬어.',
      'ja': 'ふん。みんなパズルは好きって言うくせに、ゲームは好きじゃなくて…ちょっと、ね。',
      'zh': '哼。大家都说喜欢解谜，却不喜欢游戏……有点难过。',
      'es': 'Hmpf. Todos dicen que aman los acertijos, pero los juegos no… eso me dolió un poco.',
      'pt': 'Hmpf. Todo mundo diz que ama quebra-cabeças, mas jogos não… isso doeu um pouco.',
      'de': 'Hmpf. Alle sagen, sie lieben Rätsel, aber Spiele mögen sie nicht… das hat ein bisschen wehgetan.',
      'fr': 'Pff. Tout le monde dit adorer les énigmes, mais pas les jeux… ça m\'a un peu blessée.',
      'id': 'Hmph. Katanya semua suka teka-teki, tapi nggak suka game… agak nyesek.',
      'vi': 'Hừ. Ai cũng bảo thích câu đố, mà lại chẳng thích trò chơi… hơi buồn.',
    },
    'sc_w6_4_5': {
      'en': 'I never left.',
      'ko': '나는 안 갔잖아.',
      'ja': '私は去らなかったじゃん。',
      'zh': '我没走啊。',
      'es': 'Yo nunca me fui.',
      'pt': 'Eu não fui embora.',
      'de': 'Ich bin nicht gegangen.',
      'fr': 'Moi, je ne suis pas partie.',
      'id': 'Aku nggak pergi, kan.',
      'vi': 'Tớ có bỏ đi đâu.',
    },
    'sc_w6_4_6': {
      'en': '…I know. You play differently every time, but you always end up here.',
      'ko': '…알아. 너는 매번 다르게 두면서도 결국 여기로 와.',
      'ja': '…わかってる。あんたは毎回違う手を打つのに、結局ここに来る。',
      'zh': '……我知道。你每次下法都不同，最后却总会走到这里。',
      'es': '…Ya sé. Juegas distinto cada vez, pero siempre terminas aquí.',
      'pt': '…Eu sei. Você joga diferente toda vez, mas sempre acaba aqui.',
      'de': '…Ich weiß. Du spielst jedes Mal anders, landest aber immer wieder hier.',
      'fr': '…Je sais. Tu joues différemment à chaque fois, mais tu finis toujours par revenir ici.',
      'id': '…Aku tahu. Kamu mainnya beda-beda tiap kali, tapi ujung-ujungnya sampai sini.',
      'vi': '…Tớ biết. Lần nào cậu cũng đánh khác, nhưng rồi vẫn tới được đây.',
    },
    'sc_w6_4_7': {
      'en': 'I guess that\'s the difference between people and numbers.',
      'ko': '그게 사람이랑 숫자의 차이인가 봐.',
      'ja': 'それが人と数字の違いなのかも。',
      'zh': '那大概就是人和数字的区别吧。',
      'es': 'Supongo que esa es la diferencia entre las personas y los números.',
      'pt': 'Acho que essa é a diferença entre pessoas e números.',
      'de': 'Das ist wohl der Unterschied zwischen Menschen und Zahlen.',
      'fr': 'C\'est peut-être ça, la différence entre les gens et les nombres.',
      'id': 'Mungkin itu bedanya orang sama angka.',
      'vi': 'Chắc đó là khác biệt giữa người và số.',
    },
    'sc_w6_4_8': {
      'en': 'A good difference?',
      'ko': '좋은 차이야?',
      'ja': 'いい違いなの?',
      'zh': '是好的区别吗?',
      'es': '¿Es una buena diferencia?',
      'pt': 'É uma boa diferença?',
      'de': 'Ein guter Unterschied?',
      'fr': 'Une bonne différence ?',
      'id': 'Perbedaan yang baik?',
      'vi': 'Là khác biệt tốt chứ?',
    },
    'sc_w6_4_9': {
      'en': 'I-I don\'t know! Not yet!',
      'ko': '모, 몰라! 아직은!',
      'ja': 'し、知らない！まだ！',
      'zh': '不、不知道！还不知道！',
      'es': '¡N-no sé! ¡Todavía no!',
      'pt': 'S-sei lá! Ainda não!',
      'de': 'K-keine Ahnung! Noch nicht!',
      'fr': 'J-j\'en sais rien ! Pas encore !',
      'id': 'N-nggak tahu! Belum!',
      'vi': 'K-không biết! Chưa đâu!',
    },
    'sc_w6_4_10': {
      'en': 'Tell me when you find out.',
      'ko': '알게 되면 말해 줘.',
      'ja': 'わかったら教えて。',
      'zh': '知道了就告诉我。',
      'es': 'Dime cuando lo sepas.',
      'pt': 'Me conta quando souber.',
      'de': 'Sag mir Bescheid, wenn du\'s weißt.',
      'fr': 'Dis-le-moi quand tu sauras.',
      'id': 'Kalau sudah tahu, kasih tahu aku.',
      'vi': 'Khi nào biết thì nói cho tớ nghe nhé.',
    },
    'sc_w6_4_11': {
      'en': 'There\'s a rabbit hutch in the backyard. There are some who need names.',
      'ko': '뒤뜰에 토끼장 있어. 이름 지어줄 애들이 있거든.',
      'ja': '裏庭にウサギ小屋があるの。名前つけてあげる子たちがいて。',
      'zh': '后院有兔笼。有几只还没取名字。',
      'es': 'Hay una conejera en el patio trasero. Hay algunos que necesitan nombre.',
      'pt': 'Tem uma gaiola de coelhos no quintal. Tem uns que precisam de nome.',
      'de': 'Hinterm Haus steht ein Kaninchenstall. Ein paar brauchen noch Namen.',
      'fr': 'Il y a un clapier derrière la maison. Il y en a qui ont besoin d\'un nom.',
      'id': 'Ada kandang kelinci di belakang. Ada beberapa yang belum dikasih nama.',
      'vi': 'Sau nhà có chuồng thỏ. Có vài con cần đặt tên.',
    },
    'sc_w6_4_12': {
      'en': 'Let\'s go together. Bring jelly! No jelly, no entry.',
      'ko': '같이 가자. 젤리 가져와! 안 가져오면 안 끼워 줄 거야.',
      'ja': '一緒に行こ。グミ持ってきて！持ってこなかったら入れてあげない。',
      'zh': '一起去吧。带软糖来！不带就不让你加入。',
      'es': 'Vamos juntos. ¡Trae gomitas! Sin gomitas, no entras.',
      'pt': 'Vamos juntos. Traz jujuba! Sem jujuba, não entra.',
      'de': 'Gehen wir zusammen. Bring Gummibärchen mit! Ohne Gummibärchen kein Einlass.',
      'fr': 'Allons-y ensemble. Apporte des bonbons gélifiés ! Sinon, t\'entres pas.',
      'id': 'Ayo pergi bareng. Bawa jeli! Nggak bawa, nggak boleh ikut.',
      'vi': 'Đi cùng nhau đi. Mang thạch theo! Không mang thì không cho theo.',
    },
    'sc_w7_1_title': {
      'en': 'Traitors',
      'ko': '배신자들',
      'ja': '裏切り者たち',
      'zh': '叛徒们',
      'es': 'Traidores',
      'pt': 'Traidores',
      'de': 'Verräter',
      'fr': 'Traîtres',
      'id': 'Para Pengkhianat',
      'vi': 'Những Kẻ Phản Bội',
    },
    'sc_w7_1_1': {
      'en': 'Even the rabbits are cheering for you!',
      'ko': '토끼들도 너 응원하더라!',
      'ja': 'ウサギたちもあんたを応援してたよ！',
      'zh': '连兔子都在给你加油！',
      'es': '¡Hasta los conejos te están animando!',
      'pt': 'Até os coelhos estão torcendo por você!',
      'de': 'Sogar die Hasen feuern dich an!',
      'fr': 'Même les lapins t\'encouragent !',
      'id': 'Kelinci-kelinci juga dukung kamu!',
      'vi': 'Cả mấy con thỏ cũng cổ vũ cậu!',
    },
    'sc_w7_1_2': {
      'en': 'The rabbits?',
      'ko': '토끼가?',
      'ja': 'ウサギが?',
      'zh': '兔子?',
      'es': '¿Los conejos?',
      'pt': 'Os coelhos?',
      'de': 'Die Kaninchen?',
      'fr': 'Les lapins ?',
      'id': 'Kelinci-kelinci?',
      'vi': 'Mấy con thỏ á?',
    },
    'sc_w7_1_3': {
      'en': 'Their ears turned your way! Traitors…',
      'ko': '귀가 네 쪽으로 돌아갔다니까! 배신자들…',
      'ja': '耳があんたのほうを向いてたんだってば！裏切り者…',
      'zh': '耳朵都转向你那边了！叛徒……',
      'es': '¡Que giraron las orejas hacia ti! Traidores…',
      'pt': 'As orelhas viraram pro seu lado! Traidores…',
      'de': 'Ihre Ohren haben sich zu dir gedreht! Verräter…',
      'fr': 'Leurs oreilles se sont tournées vers toi ! Traîtres…',
      'id': 'Telinganya ngarah ke kamu, tahu! Pengkhianat…',
      'vi': 'Tai tụi nó quay về phía cậu đó! Lũ phản bội…',
    },
    'sc_w7_1_4': {
      'en': 'I\'ll save a jelly. Prize for the next game.',
      'ko': '젤리 하나 남겨둘게. 다음 판 상금이야.',
      'ja': 'グミ一個残しとく。次の勝負の賞品ね。',
      'zh': '给你留一颗软糖。下一局的奖品。',
      'es': 'Te guardo una gomita. Es el premio de la siguiente partida.',
      'pt': 'Vou guardar uma jujuba. É o prêmio da próxima partida.',
      'de': 'Ich heb ein Gummibärchen auf. Der Preis für die nächste Runde.',
      'fr': 'Je garde un bonbon gélifié. Le prix de la prochaine partie.',
      'id': 'Aku sisain satu jeli. Hadiah ronde berikutnya.',
      'vi': 'Tớ để dành một viên thạch. Phần thưởng ván sau.',
    },
    'sc_w7_1_5': {
      'en': 'Can\'t you give it to the rabbit?',
      'ko': '토끼 주면 안 돼?',
      'ja': 'ウサギにあげちゃダメ?',
      'zh': '不能给兔子吗?',
      'es': '¿No se lo puedes dar al conejo?',
      'pt': 'Não dá pra dar pro coelho?',
      'de': 'Kannst du es nicht dem Kaninchen geben?',
      'fr': 'Tu peux pas le donner au lapin ?',
      'id': 'Nggak bisa dikasih ke kelincinya aja?',
      'vi': 'Không đưa cho con thỏ được à?',
    },
    'sc_w7_1_6': {
      'en': 'No! It\'s yours. …It\'s YOURS.',
      'ko': '안 돼! 그건 네 거야. …네 거라고.',
      'ja': 'だめ！それはあんたの。…あんたのなの。',
      'zh': '不行！那是你的。……是你的。',
      'es': '¡No! Es tuya. …Es TUYA.',
      'pt': 'Não! É sua. …É SUA.',
      'de': 'Nein! Das gehört dir. …DIR, hab ich gesagt.',
      'fr': 'Non ! Il est à toi. …À TOI, j\'ai dit.',
      'id': 'Nggak boleh! Itu punyamu. …Punyamu, tahu.',
      'vi': 'Không được! Cái đó của cậu. …Của cậu đấy.',
    },
    'sc_w7_2_title': {
      'en': 'Nim and Game',
      'ko': '님과 게임',
      'ja': 'ニムとゲーム',
      'zh': '尼姆和游戏',
      'es': 'Nim y Game',
      'pt': 'Nim e Game',
      'de': 'Nim und Game',
      'fr': 'Nim et Game',
      'id': 'Nim dan Game',
      'vi': 'Nim và Game',
    },
    'sc_w7_2_1': {
      'en': 'I named the rabbits. One\'s Nim, the other\'s Game.',
      'ko': '토끼 이름 지었어. 하나는 님, 하나는 게임.',
      'ja': '名前決めた。一匹はニム、一匹はゲーム。',
      'zh': '我给兔子取名字了。一只叫尼姆,一只叫游戏。',
      'es': 'Les puse nombre a los conejos. Uno es Nim, el otro es Game.',
      'pt': 'Dei nome aos coelhos. Um é Nim, o outro é Game.',
      'de': 'Ich hab den Kaninchen Namen gegeben. Eins heißt Nim, eins heißt Game.',
      'fr': 'J\'ai donné des noms aux lapins. L\'un s\'appelle Nim, l\'autre Game.',
      'id': 'Aku sudah kasih nama kelincinya. Satu Nim, satu lagi Game.',
      'vi': 'Tớ đặt tên cho thỏ rồi. Một con là Nim, một con là Game.',
    },
    'sc_w7_2_2': {
      'en': '...Can I laugh?',
      'ko': '…웃어도 돼?',
      'ja': '…笑っていい?',
      'zh': '……我能笑吗?',
      'es': '...¿Puedo reírme?',
      'pt': '...Posso rir?',
      'de': '...Darf ich lachen?',
      'fr': '...Je peux rire ?',
      'id': '...Boleh aku ketawa?',
      'vi': '...Tớ cười được không?',
    },
    'sc_w7_2_3': {
      'en': 'Don\'t laugh! I named them seriously!',
      'ko': '웃지 마! 진지하게 지은 거야!',
      'ja': '笑わないで！真剣につけた名前なんだから！',
      'zh': '不许笑！我是认真起的名字！',
      'es': '¡No te rías! ¡Les puse nombre en serio!',
      'pt': 'Não ri! Eu dei os nomes a sério!',
      'de': 'Lach nicht! Die Namen hab ich mir ernsthaft ausgedacht!',
      'fr': 'Rigole pas ! Je leur ai donné des noms sérieusement !',
      'id': 'Jangan ketawa! Aku kasih nama serius!',
      'vi': 'Đừng cười! Tớ đặt tên nghiêm túc đấy!',
    },
    'sc_w7_2_4': {
      'en': 'Fibonacci numbers came from counting rabbits. Th-that\'s why.',
      'ko': '피보나치 수는 토끼 세는 데서 나왔대. 그, 그래서야.',
      'ja': 'フィボナッチ数はウサギを数えるところから生まれたんだって。だ、だからよ。',
      'zh': '斐波那契数是从数兔子来的。所、所以啦。',
      'es': 'Dicen que los números de Fibonacci salieron de contar conejos. P-por eso.',
      'pt': 'Dizem que os números de Fibonacci vieram de contar coelhos. P-por isso.',
      'de': 'Die Fibonacci-Zahlen kommen vom Hasenzählen. D-deshalb.',
      'fr': 'Les nombres de Fibonacci viennent du comptage des lapins. C-c\'est pour ça.',
      'id': 'Katanya bilangan Fibonacci berasal dari ngitung kelinci. M-makanya.',
      'vi': 'Nghe nói dãy Fibonacci ra đời từ việc đếm thỏ. V-vì thế đó.',
    },
    'sc_w7_2_5': {
      'en': 'Then what about the third rabbit?',
      'ko': '그럼 세 번째 토끼는?',
      'ja': 'じゃあ三匹目のウサギは?',
      'zh': '那第三只兔子呢?',
      'es': '¿Y el tercer conejo entonces?',
      'pt': 'E o terceiro coelho, então?',
      'de': 'Und was ist mit dem dritten Kaninchen?',
      'fr': 'Et le troisième lapin, alors ?',
      'id': 'Terus kelinci yang ketiga gimana?',
      'vi': 'Vậy con thỏ thứ ba thì sao?',
    },
    'sc_w7_2_6': {
      'en': 'No name yet. You name it. …If you\'ll still be here next year.',
      'ko': '아직 이름 없어. 네가 지어. …내년에도 여기 있을 거면.',
      'ja': 'まだ名前ないの。あんたがつけて。…来年もここにいるなら。',
      'zh': '还没起名字。你来起。……如果你明年还在这里的话。',
      'es': 'Aún no tiene nombre. Pónselo tú. …Si el año que viene sigues aquí.',
      'pt': 'Ainda não tem nome. Escolhe você. …Se ano que vem você ainda estiver aqui.',
      'de': 'Hat noch keinen Namen. Du darfst ihn aussuchen. …Wenn du nächstes Jahr noch hier bist.',
      'fr': 'Il a pas encore de nom. C\'est toi qui choisis. …Si t\'es encore là l\'année prochaine.',
      'id': 'Belum ada namanya. Kamu yang kasih. …Kalau tahun depan kamu masih di sini.',
      'vi': 'Chưa có tên. Cậu đặt đi. …Nếu năm sau cậu vẫn còn ở đây.',
    },
    'sc_w7_3_title': {
      'en': 'Bragging',
      'ko': '자랑',
      'ja': '自慢',
      'zh': '炫耀',
      'es': 'Presumir',
      'pt': 'Se gabar',
      'de': 'Angeben',
      'fr': 'Se vanter',
      'id': 'Pamer',
      'vi': 'Khoe Khoang',
    },
    'sc_w7_3_1': {
      'en': 'Not many people get this far. You can brag.',
      'ko': '여기까지 온 사람 별로 없어. 자랑해도 돼.',
      'ja': 'ここまで来た人、あんまりいないよ。自慢していいよ。',
      'zh': '能走到这里的人可不多。可以炫耀一下。',
      'es': 'No mucha gente llega hasta aquí. Puedes presumir.',
      'pt': 'Pouca gente chega até aqui. Pode se gabar.',
      'de': 'Nicht viele kommen so weit. Darfst ruhig angeben.',
