    'sc_w7_4_1': {
      'en': 'All seven Nim Game lessons — finished.',
      'ko': '님게임 일곱 수업, 전부 끝났어.',
      'ja': 'ニムゲームの七つの授業、全部終わった。',
      'zh': '尼姆游戏的七堂课,全部结束了。',
