    'sc_w7_4_2': {
      'en': 'Remember the day we met? Four candies.',
      'ko': '처음 만난 날 기억나? 사탕 네 개였잖아.',
      'ja': '初めて会った日のこと覚えてる？飴四つだったよね。',
      'zh': '还记得第一次见面那天吗？四颗糖。',
      'es': '¿Te acuerdas del día que nos conocimos? Eran cuatro caramelos.',
