    'sc_w7_4_3': {
      'en': 'Didn\'t even know the rules.',
      'ko': '규칙도 몰랐지.',
      'ja': 'ルールも知らなかったな。',
      'zh': '规则都不懂。',
      'es': 'Ni siquiera sabía las reglas.',
      'pt': 'Nem sabia as regras direito.',
      'de': 'Kannte nicht mal die Regeln.',
