    },
    'sc_w7_4_4': {
      'en': 'So I thought you\'d leave soon. Honestly.',
      'ko': '그래서 금방 갈 줄 알았어. 솔직히.',
      'ja': 'だからすぐいなくなると思ってた。正直。',
      'zh': '所以我以为你很快就会走。说实话。',
      'es': 'Por eso pensé que te irías pronto. La verdad.',
      'pt': 'Por isso achei que você ia embora logo. Sinceramente.',
