    'sc_w7_4_5': {
      'en': 'Impressive, right?',
      'ko': '대견하지?',
      'ja': 'えらいでしょ？',
      'zh': '了不起吧？',
      'es': 'Impresionante, ¿no?',
      'pt': 'Impressionante, né?',
      'de': 'Ganz schön stark, oder?',
      'fr': 'Pas mal, hein ?',
      'id': 'Hebat, kan?',
      'vi': 'Giỏi ha?',
    },
    'sc_w7_4_6': {
      'en': 'Twenty games, seven times. A hundred and forty. …I w-wasn\'t counting! It\'s a record, a RECORD!',
      'ko': '스무 판씩 일곱 번. 백사십 판. …세, 세고 있었던 거 아니야! 기록이야, 기록!',
      'ja': '二十回ずつ七回。百四十回。…か、数えてたわけじゃないから！記録よ、記録！',
      'zh': '每次二十局，七次。一百四十局。……我、我才没在数！是记录，记录！',
      'es': 'Veinte partidas, siete veces. Ciento cuarenta. …¡N-no las estaba contando! ¡Es un registro, un REGISTRO!',
      'pt': 'Vinte partidas, sete vezes. Cento e quarenta. …E-eu não tava contando! É um registro, um REGISTRO!',
      'de': 'Siebenmal zwanzig Runden. Hundertvierzig. …I-ich hab nicht mitgezählt! Das ist Statistik, STATISTIK!',
      'fr': 'Vingt parties, sept fois. Cent quarante. …J-je comptais pas ! C\'est pour les stats, les STATS !',
      'id': 'Dua puluh ronde, tujuh kali. Seratus empat puluh ronde. …A-aku nggak ngitung! Ini catatan, CATATAN!',
      'vi': 'Hai mươi ván, bảy lần. Một trăm bốn mươi ván. …T-tớ không có đếm! Là ghi chép, ghi chép!',
    },
    'sc_w7_4_7': {
      'en': 'Did you decide on the third rabbit\'s name?',
      'ko': '세 번째 토끼 이름은 정했어?',
      'ja': '三匹目のウサギの名前決めた?',
      'zh': '第三只兔子的名字想好了吗?',
      'es': '¿Ya decidiste el nombre del tercer conejo?',
      'pt': 'Já decidiu o nome do terceiro coelho?',
      'de': 'Hast du dich für einen Namen für das dritte Kaninchen entschieden?',
      'fr': 'Tu as trouvé un nom pour le troisième lapin ?',
      'id': 'Kamu udah nemuin nama buat kelinci ketiga?',
      'vi': 'Cậu nghĩ ra tên cho con thỏ thứ ba chưa?',
    },
    'sc_w7_4_8': {
      'en': 'Not yet.',
      'ko': '아직.',
      'ja': 'まだ。',
      'zh': '还没。',
      'es': 'Todavía no.',
      'pt': 'Ainda não.',
      'de': 'Noch nicht.',
      'fr': 'Pas encore.',
      'id': 'Belum.',
      'vi': 'Chưa đâu.',
    },
    'sc_w7_4_9': {
      'en': 'T-take your time. There\'s time until next year.',
      'ko': '처, 천천히 해. 내년까지 시간 있으니까.',
      'ja': 'ゆ、ゆっくりでいいよ。来年まで時間あるし。',
      'zh': '慢、慢慢来。到明年还有时间。',
      'es': 'T-tómatelo con calma. Hay tiempo hasta el año que viene.',
      'pt': 'V-vai com calma. Tem tempo até o ano que vem.',
      'de': 'L-lass dir Zeit. Wir haben ja bis nächstes Jahr.',
      'fr': 'P-prends ton temps. On a jusqu\'à l\'année prochaine.',
      'id': 'P-pelan-pelan aja. Masih ada waktu sampai tahun depan.',
      'vi': 'T-từ từ thôi. Còn thời gian tới năm sau mà.',
    },
    'sc_w7_4_10': {
      'en': 'Will you still be here next year?',
      'ko': '내년에도 있을 거야?',
      'ja': '来年もいる?',
      'zh': '明年你还会在吗?',
      'es': '¿Vas a seguir aquí el año que viene?',
      'pt': 'Você vai continuar aqui ano que vem?',
      'de': 'Bist du nächstes Jahr noch hier?',
      'fr': 'Tu seras encore là l\'année prochaine ?',
      'id': 'Tahun depan kamu masih di sini?',
      'vi': 'Sang năm cậu vẫn còn ở đây chứ?',
    },
    'sc_w7_4_11': {
      'en': 'Wouldn\'t it? I\'ll wait at the board game club. Formulas don\'t work there.',
      'ko': '그, 그렇지 않을까? 보드게임부에서 기다릴게. 거긴 공식이 안 통하거든.',
      'ja': 'そ、そうじゃない？ボードゲーム部で待ってる。あそこは公式が通じないんだから。',
      'zh': '应、应该是吧？我在桌游社等你。那里公式可不管用。',
      'es': '¿N-no crees? Te espero en el club de juegos de mesa. Ahí las fórmulas no sirven.',
      'pt': 'N-não acha? Vou te esperar no clube de jogos de tabuleiro. Lá as fórmulas não funcionam.',
      'de': 'W-wär doch möglich, oder? Ich warte im Brettspielclub. Da helfen keine Formeln.',
      'fr': 'Ç-ça se pourrait, non ? Je t\'attends au club de jeux de société. Là-bas, les formules marchent pas.',
      'id': 'B-bener, kan? Aku tunggu di klub board game. Di sana rumus nggak mempan.',
      'vi': 'Ch-chắc vậy nhỉ? Tớ chờ ở câu lạc bộ board game. Ở đó công thức vô dụng.',
    },
    'sc_w7_4_12': {
      'en': 'So it\'ll be more fun. W-with you. …You didn\'t hear that, right?',
      'ko': '그래서 더 재밌을 거야. 너, 너랑이면. …방금 거 못 들었지?',
      'ja': 'だからもっと楽しいはず。あ、あんたとなら。…今の、聞こえてないよね？',
      'zh': '所以会更好玩。如、如果是和你的话。……刚才的话你没听见吧？',
      'es': 'Por eso será más divertido. C-contigo. …No oíste eso, ¿verdad?',
      'pt': 'Por isso vai ser mais divertido. C-com você. …Você não ouviu isso, né?',
      'de': 'Deshalb macht\'s da noch mehr Spaß. M-mit dir. …Das hast du nicht gehört, oder?',
      'fr': 'Du coup, ce sera encore plus drôle. A-avec toi. …T\'as rien entendu, hein ?',
      'id': 'Makanya bakal lebih seru. K-kalau sama kamu. …Barusan nggak kedengeran, kan?',
      'vi': 'Nên sẽ vui hơn. N-nếu là với cậu. …Câu vừa rồi cậu không nghe thấy chứ?',
    },
    'sc_w8_1_title': {
      'en': 'Name',
      'ko': '이름',
      'ja': '名前',
      'zh': '名字',
      'es': 'Nombre',
      'pt': 'Nome',
      'de': 'Der Name',
      'fr': 'Le prénom',
      'id': 'Nama',
      'vi': 'Tên',
    },
    'sc_w8_1_1': {
      'en': 'The snack bar lady memorized your name!',
      'ko': '매점 아줌마가 너 이름 외우셨대!',
      'ja': '売店のおばさん、あんたの名前覚えたって！',
      'zh': '小卖部阿姨记住你的名字了！',
      'es': '¡La señora del quiosco se aprendió tu nombre!',
      'pt': 'A tia da cantina decorou seu nome!',
      'de': 'Die Frau vom Kiosk kennt schon deinen Namen!',
      'fr': 'La dame de la cafétéria connaît déjà ton prénom !',
      'id': 'Ibu kantin udah hafal namamu!',
      'vi': 'Cô căng-tin nhớ tên cậu rồi đấy!',
    },
    'sc_w8_1_2': {
      'en': 'Because I buy chocolate every day.',
      'ko': '매일 초콜릿을 사니까.',
      'ja': '毎日チョコを買うから。',
      'zh': '因为我每天都买巧克力。',
      'es': 'Porque compro chocolate todos los días.',
      'pt': 'Porque eu compro chocolate todo dia.',
      'de': 'Weil ich jeden Tag Schokolade kaufe.',
      'fr': 'Parce que j\'achète du chocolat tous les jours.',
      'id': 'Soalnya aku beli cokelat tiap hari.',
      'vi': 'Vì ngày nào tớ cũng mua sô-cô-la.',
    },
    'sc_w8_1_3': {
      'en': 'She still doesn\'t know mine!',
      'ko': '내 이름은 아직 못 외우셨는데!',
      'ja': '私の名前はまだ覚えてもらってないのに！',
      'zh': '我的名字她都还没记住！',
      'es': '¡Y el mío todavía no!',
      'pt': 'E o meu ela ainda não sabe!',
      'de': 'Meinen kennt sie immer noch nicht!',
      'fr': 'Et le mien, elle le connaît toujours pas !',
      'id': 'Namaku aja belum dihafal!',
      'vi': 'Tên tớ thì cô vẫn chưa nhớ!',
    },
    'sc_w8_1_4': {
      'en': '…So unfair. Really unfair.',
      'ko': '…억울해. 진짜 억울해.',
      'ja': '…悔しい。ほんとに悔しい。',
      'zh': '……好委屈。真的好委屈。',
      'es': '…Qué injusto. De verdad, qué injusto.',
      'pt': '…Que injusto. Muito injusto mesmo.',
      'de': '…So unfair. Echt unfair.',
      'fr': '…C\'est trop injuste. Vraiment injuste.',
      'id': '…Nggak adil. Beneran nggak adil.',
      'vi': '…Ấm ức quá. Ấm ức thật sự.',
    },
    'sc_w8_1_5': {
      'en': 'Want me to buy it for you instead?',
      'ko': '내가 대신 사 줄까?',
      'ja': '私が代わりに買ってあげようか?',
      'zh': '要不要我替你买?',
      'es': '¿Quieres que te lo compre yo en tu lugar?',
      'pt': 'Quer que eu compre pra você então?',
      'de': 'Soll ich es stattdessen für dich kaufen?',
      'fr': 'Tu veux que je l\'achète à ta place ?',
      'id': 'Mau aku yang belikan buat kamu?',
      'vi': 'Để tớ mua thay cho cậu nhé?',
    },
    'sc_w8_1_6': {
      'en': 'No thanks! Just don\'t eat the poison chocolate.',
      'ko': '됐거든! 독 초콜릿이나 안 먹게 조심해.',
      'ja': '結構です！毒チョコ食べないように気をつけな。',
      'zh': '不用了！小心别吃到毒巧克力。',
      'es': '¡No, gracias! Mejor cuida de no comerte el chocolate envenenado.',
      'pt': 'Não, obrigada! Só toma cuidado pra não comer o chocolate envenenado.',
      'de': 'Nein danke! Pass lieber auf, dass du nicht die Giftschokolade isst.',
      'fr': 'Non merci ! Fais juste gaffe à pas manger le chocolat empoisonné.',
      'id': 'Nggak usah! Hati-hati aja jangan sampai makan cokelat beracun.',
      'vi': 'Khỏi! Cẩn thận đừng ăn phải sô-cô-la độc là được.',
    },
    'sc_w8_2_title': {
      'en': 'The Certain Thing',
      'ko': '확실한 것',
      'ja': '確実なこと',
      'zh': '确定的事',
      'es': 'Lo que es seguro',
      'pt': 'O que é certo',
      'de': 'Das Gewisse',
      'fr': 'Une chose certaine',
      'id': 'Hal yang Pasti',
      'vi': 'Điều Chắc Chắn',
    },
    'sc_w8_2_1': {
      'en': 'It\'s proven that the first player wins at Chomp. But nobody knows how.',
      'ko': '춉은 먼저 두는 쪽이 이긴다고 증명됐어. 근데 방법은 아무도 몰라.',
      'ja': 'チョンプは先手が勝つって証明されてる。でもその方法は誰も知らない。',
      'zh': '已经证明了抢先下的一方会赢咬饼干游戏。但没人知道方法。',
      'es': 'Está demostrado que el primero en mover gana en Chomp. Pero nadie sabe cómo.',
      'pt': 'Está provado que quem joga primeiro ganha no Chomp. Mas ninguém sabe como.',
      'de': 'Es ist bewiesen, dass beim Chomp der erste Spieler gewinnt. Aber wie, weiß keiner.',
      'fr': 'Il est prouvé que le premier joueur gagne au Chomp. Mais personne ne sait comment.',
      'id': 'Sudah terbukti kalau yang jalan duluan menang di Chomp. Tapi caranya nggak ada yang tahu.',
      'vi': 'Đã chứng minh được người đi trước sẽ thắng ở trò Chomp. Nhưng không ai biết cách.',
    },
    'sc_w8_2_2': {
      'en': 'That\'s strange.',
      'ko': '이상하네.',
      'ja': '変なの。',
      'zh': '真奇怪。',
      'es': 'Qué raro.',
      'pt': 'Que estranho.',
      'de': 'Komisch.',
      'fr': 'C\'est bizarre.',
      'id': 'Aneh juga ya.',
      'vi': 'Lạ thật đấy.',
    },
    'sc_w8_2_3': {
      'en': 'Knowing you can win but not knowing how. That\'s a thing.',
      'ko': '이기는 건 확실한데 방법을 모르는 거. 그런 게 있어.',
      'ja': '勝てるのは確実なのに、やり方がわからない。そういうのもあるの。',
      'zh': '明知能赢却不知道怎么赢。就有这种事。',
      'es': 'Saber que puedes ganar pero no saber cómo. Eso pasa.',
      'pt': 'Saber que dá pra ganhar mas não saber como. Isso existe.',
      'de': 'Wissen, dass man gewinnt, aber nicht wie. So was gibt\'s.',
      'fr': 'Savoir qu\'on peut gagner, mais pas comment. Ça existe.',
      'id': 'Tahu bakal menang, tapi nggak tahu caranya. Ada yang kayak gitu.',
      'vi': 'Biết chắc thắng mà không biết cách. Có chuyện như vậy đấy.',
    },
    'sc_w8_2_4': {
      'en': '...I have one too. Something certain, but I don\'t know how.',
      'ko': '…나도 하나 있어. 확실한데 방법을 모르는 거.',
      'ja': '…私にもある。確実なのに、方法がわからないこと。',
      'zh': '……我也有一个。确定,但不知道方法的事。',
      'es': '...Yo también tengo uno. Algo seguro, pero no sé cómo.',
      'pt': '...Eu também tenho uma. Uma coisa certa, mas eu não sei como.',
      'de': '...Ich hab auch so eins. Etwas Sicheres, bei dem ich nicht weiß, wie.',
      'fr': '...Moi aussi j\'en ai une. Une chose certaine, mais je sais pas comment.',
      'id': '...Aku juga punya satu. Hal yang pasti, tapi caranya nggak tahu.',
      'vi': '...Tớ cũng có một chuyện. Chắc chắn nhưng không biết cách.',
    },
    'sc_w8_2_5': {
      'en': 'What is it?',
      'ko': '뭔데?',
      'ja': '何?',
      'zh': '是什么?',
      'es': '¿Qué cosa?',
      'pt': 'O que é?',
      'de': 'Was denn?',
      'fr': 'C\'est quoi ?',
      'id': 'Apaan tuh?',
      'vi': 'Chuyện gì vậy?',
    },
    'sc_w8_2_6': {
      'en': 'J-just eat your chocolate!',
      'ko': '초, 초콜릿이나 먹어!',
      'ja': 'チ、チョコでも食べてなさい！',
      'zh': '巧、巧克力吃你的去！',
      'es': '¡C-cómete tu chocolate y ya!',
      'pt': 'S-só come seu chocolate!',
      'de': 'I-iss einfach deine Schokolade!',
      'fr': 'M-mange ton chocolat, toi !',
      'id': 'M-makan aja cokelatmu!',
      'vi': 'Ă-ăn sô-cô-la đi!',
    },
    'sc_w8_3_title': {
      'en': 'Scared',
      'ko': '겁',
      'ja': '怖気',
      'zh': '害怕',
      'es': 'Miedo',
      'pt': 'Medo',
      'de': 'Angst',
      'fr': 'Peur',
      'id': 'Takut',
      'vi': 'Sợ Hãi',
    },
    'sc_w8_3_1': {
      'en': 'Bigger board next time. Don\'t get scared!',
      'ko': '다음엔 더 큰 판이야. 겁먹지 마!',
      'ja': '次はもっと大きい盤だよ。ビビらないでね！',
      'zh': '下次棋盘更大。别害怕！',
      'es': 'La próxima vez, un tablero más grande. ¡No te asustes!',
      'pt': 'Da próxima vez, tabuleiro maior. Não fica com medo!',
