      'fr': 'La prochaine fois, le plateau sera plus grand. Aie pas peur !',
      'id': 'Berikutnya papan lebih besar. Jangan takut!',
      'vi': 'Lần sau bàn lớn hơn. Đừng sợ nhé!',
    },
    'sc_w8_3_2': {
      'en': 'Not scared.',
      'ko': '안 먹어.',
      'ja': '怖くない。',
      'zh': '不怕。',
      'es': 'No tengo miedo.',
      'pt': 'Não tenho medo.',
      'de': 'Hab ich nicht.',
      'fr': 'J\'ai pas peur.',
      'id': 'Nggak takut.',
      'vi': 'Không sợ đâu.',
    },
    'sc_w8_3_3': {
      'en': 'You can be. If you\'re scared… hold my hand, or whatever.',
      'ko': '먹어도 돼. 겁먹으면… 내 손 잡든가.',
      'ja': 'ビビってもいいよ。怖かったら…私の手、握れば。',
      'zh': '怕也可以。怕的话……就握着我的手吧。',
