    'sc_w8_4_title': {
      'en': 'The Snack Bar Receipts',
      'ko': '매점의 영수증',
      'ja': '売店のレシート',
      'zh': '小卖部的收据',
      'es': 'Los recibos del quiosco',
      'pt': 'Os recibos da cantina',
      'de': 'Die Kioskquittungen',
      'fr': 'Les tickets de caisse de la cantine',
      'id': 'Struk Kantin',
      'vi': 'Những Tờ Hóa Đơn Căng Tin',
    },
    'sc_w8_4_1': {
      'en': 'Twenty games of Chomp. I spent a lot on snack bar chocolate!',
      'ko': '춉 스무 판. 매점 초콜릿 값 꽤 나갔거든!',
      'ja': 'チョンプ二十回。売店のチョコ代、けっこうかかったんだからね！',
      'zh': '毒巧克力二十局。小卖部的巧克力钱花了不少呢！',
      'es': 'Veinte partidas de Chomp. ¡Gasté un montón en chocolate del quiosco!',
      'pt': 'Vinte partidas de Chomp. Gastei um monte com chocolate da cantina!',
      'de': 'Zwanzig Runden Chomp. Die Kioskschokolade hat mich einiges gekostet!',
      'fr': 'Vingt parties de Chomp. Le chocolat de la cafétéria m\'a coûté une fortune !',
      'id': 'Chomp dua puluh ronde. Uang cokelat kantin habis banyak, tahu!',
      'vi': 'Chomp hai mươi ván. Tiền sô-cô-la căng-tin tốn kha khá đấy!',
    },
    'sc_w8_4_2': {
      'en': 'I kept every receipt. Every one is a game you won.',
      'ko': '영수증 다 모아뒀어. 이거 전부 네가 이긴 판이야.',
      'ja': 'レシート全部取ってあるの。これ全部あんたが勝った回だよ。',
      'zh': '小票我全留着。这些全是你赢的局。',
      'es': 'Guardé todos los recibos. Cada uno es una partida que ganaste.',
      'pt': 'Guardei todas as notinhas. Cada uma é uma partida que você ganhou.',
      'de': 'Ich hab alle Kassenbons aufgehoben. Jeder davon ist eine Runde, die du gewonnen hast.',
      'fr': 'J\'ai gardé tous les tickets de caisse. Chacun, c\'est une partie que t\'as gagnée.',
      'id': 'Semua struknya kusimpan. Semuanya ronde yang kamu menangin.',
      'vi': 'Tớ giữ hết hóa đơn rồi. Toàn là những ván cậu thắng.',
    },
    'sc_w8_4_3': {
      'en': 'Why save them?',
      'ko': '왜 모아?',
      'ja': 'なんで集めるの?',
      'zh': '为什么要留着?',
      'es': '¿Por qué los guardas?',
      'pt': 'Por que guardar?',
      'de': 'Warum hebst du die auf?',
      'fr': 'Pourquoi tu les gardes ?',
      'id': 'Kenapa disimpan?',
      'vi': 'Sao lại giữ vậy?',
    },
    'sc_w8_4_4': {
      'en': 'Throw them out? No way! This is my record.',
      'ko': '버리라고? 싫어! 이건 내 기록이야.',
      'ja': '捨てろって？やだ！これは私の記録なの。',
      'zh': '让我扔掉？不要！这是我的记录。',
      'es': '¿Tirarlos? ¡Ni loca! Esto es mi registro.',
      'pt': 'Jogar fora? Nem pensar! Isso é meu registro.',
      'de': 'Wegwerfen? Nie im Leben! Das ist meine Chronik.',
      'fr': 'Les jeter ? Hors de question ! C\'est mes archives.',
      'id': 'Dibuang? Nggak mau! Ini catatanku.',
      'vi': 'Vứt đi á? Không đời nào! Đây là ghi chép của tớ.',
    },
    'sc_w8_4_5': {
      'en': 'It\'s a record of you losing, though.',
      'ko': '진 기록인데.',
      'ja': '負けた記録なのに。',
      'zh': '那是输的记录啊。',
      'es': 'Pero es un registro de derrotas.',
      'pt': 'Mas é registro de derrota.',
      'de': 'Aber das ist eine Aufzeichnung deiner Niederlagen.',
      'fr': 'Mais c\'est un registre de défaites.',
      'id': 'Tapi itu catatan kalah, lho.',
      'vi': 'Nhưng đó là ghi chép của những lần thua mà.',
    },
    'sc_w8_4_6': {
      'en': 'It\'s not a record of losing to y-you… it\'s a record of playing with you.',
      'ko': '너, 너한테 진 기록이 아니라… 너랑 한 기록이야.',
      'ja': 'あ、あんたに負けた記録じゃなくて…あんたと遊んだ記録なの。',
      'zh': '不、不是输给你的记录……是和你一起玩的记录。',
      'es': 'No es un registro de perder contra t-ti… es un registro de jugar contigo.',
      'pt': 'Não é um registro de perder pra v-você… é um registro de jogar com você.',
      'de': 'Das ist keine Chronik meiner Niederlagen gegen d-dich… sondern unsere gemeinsame.',
      'fr': 'C\'est pas les archives de mes défaites contre t-toi… c\'est les archives de nos parties ensemble.',
      'id': 'Ini bukan catatan kalah dari k-kamu… tapi catatan main bareng kamu.',
      'vi': 'Đây không phải ghi chép thua c-cậu… mà là ghi chép chơi cùng cậu.',
