    'sc_w8_4_7': {
      'en': 'That\'s totally different! Got it?',
      'ko': '그건 완전히 다른 거야! 알아?',
      'ja': 'それって全然違うんだから！わかる？',
      'zh': '那可完全不一样！懂吗？',
      'es': '¡Es totalmente distinto! ¿Entiendes?',
      'pt': 'É totalmente diferente! Entendeu?',
      'de': 'Das ist was völlig anderes! Kapiert?',
      'fr': 'C\'est complètement différent ! Compris ?',
      'id': 'Itu beda total! Ngerti?',
      'vi': 'Hai cái khác nhau hoàn toàn! Hiểu chưa?',
    },
    'sc_w8_4_8': {
      'en': 'It is different.',
      'ko': '다른 거네.',
      'ja': '違うね。',
      'zh': '确实不一样。',
      'es': 'Sí, es otra cosa.',
      'pt': 'É outra coisa mesmo.',
      'de': 'Stimmt, ist es.',
      'fr': 'C\'est vrai, c\'est pas pareil.',
      'id': 'Iya, beda.',
      'vi': 'Khác thật đấy.',
    },
    'sc_w8_4_9': {
      'en': 'I borrowed the art room key. It\'s a line-drawing game.',
      'ko': '미술실 열쇠 빌렸어. 선 긋는 게임이야.',
      'ja': '美術室の鍵借りた。線を引くゲームだよ。',
      'zh': '我借了美术室的钥匙。是画线的游戏。',
      'es': 'Pedí prestada la llave del salón de arte. Es un juego de trazar líneas.',
      'pt': 'Peguei a chave da sala de arte emprestada. É um jogo de traçar linhas.',
      'de': 'Ich hab mir den Schlüssel für den Kunstraum geliehen. Es ist ein Linienzieh-Spiel.',
      'fr': 'J\'ai emprunté la clé de la salle d\'art. C\'est un jeu où on trace des lignes.',
      'id': 'Aku pinjam kunci ruang seni. Ini permainan menggambar garis.',
      'vi': 'Tớ mượn chìa khóa phòng mỹ thuật rồi. Là trò chơi vẽ đường thẳng.',
    },
    'sc_w8_4_10': {
      'en': 'I can\'t draw, though.',
      'ko': '그림 못 그리는데.',
      'ja': '絵、下手なのに。',
      'zh': '我不会画画啊。',
      'es': 'Pero no sé dibujar.',
      'pt': 'Mas eu não sei desenhar.',
      'de': 'Ich kann aber nicht zeichnen.',
      'fr': 'Mais je sais pas dessiner.',
      'id': 'Tapi aku nggak bisa gambar.',
      'vi': 'Nhưng tớ vẽ dở lắm.',
    },
    'sc_w8_4_11': {
      'en': 'Just draw lines. Nicely! There\'s another fun game this time too.',
      'ko': '선만 그으면 돼. 예쁘게! 이번에도 재밌는 게임이 있다구.',
      'ja': '線を引くだけでいいの。きれいにね！今回も面白いゲームがあるんだから。',
      'zh': '只要画线就行。画漂亮点！这次也有好玩的游戏哦。',
      'es': 'Solo hay que trazar líneas. ¡Bonitas! Esta vez también hay un juego divertido.',
      'pt': 'É só traçar linhas. Bem bonitas! Dessa vez também tem um jogo divertido.',
      'de': 'Du musst nur Linien ziehen. Schön ordentlich! Diesmal gibt\'s wieder ein tolles Spiel.',
      'fr': 'Il suffit de tracer des traits. Proprement ! Cette fois aussi, y a un jeu trop bien.',
      'id': 'Tinggal tarik garis. Yang rapi! Kali ini juga ada game seru, lho.',
      'vi': 'Chỉ cần kẻ đường thôi. Kẻ cho đẹp! Lần này cũng có trò hay đấy.',
    },
    'sc_w8_4_12': {
      'en': '…Because I\'ll be watching. S-sloppy lines get scolded.',
      'ko': '…내가 볼 거니까. 대, 대충 그으면 혼나.',
      'ja': '…私が見てるからね。て、適当に引いたら怒るよ。',
      'zh': '……我会盯着的。随、随便画的话可要挨骂。',
      'es': '…Porque voy a estar mirando. S-si las trazas a lo loco, te regaño.',
      'pt': '…Porque eu vou estar olhando. S-se traçar de qualquer jeito, leva bronca.',
      'de': '…Ich schau nämlich zu. W-wer schlampig zeichnet, kriegt Ärger.',
      'fr': '…Parce que je vais regarder. G-gare aux traits bâclés.',
      'id': '…Soalnya aku bakal lihatin. K-kalau asal-asalan, kumarahin.',
      'vi': '…Vì tớ sẽ nhìn đấy. K-kẻ ẩu là bị mắng.',
    },
    'sc_w9_1_title': {
      'en': 'Lines',
      'ko': '선',
      'ja': '線',
      'zh': '线',
      'es': 'Líneas',
