      'fr': 'Les lignes',
      'id': 'Garis',
      'vi': 'Đường Kẻ',
    },
    'sc_w9_1_1': {
      'en': 'In the art room, even lines should be pretty!',
      'ko': '미술실에선 선도 예쁘게 그어야지!',
      'ja': '美術室では線もきれいに引かなきゃ！',
      'zh': '在美术教室，线也得画漂亮！',
      'es': '¡En la sala de arte hasta las líneas tienen que ser bonitas!',
      'pt': 'Na sala de arte até as linhas têm que ser bonitas!',
      'de': 'Im Kunstraum muss man auch Linien schön ziehen!',
      'fr': 'En salle d\'arts plastiques, même les traits doivent être jolis !',
