    'sc_w9_1_3': {
      'en': 'Both!',
      'ko': '둘 다!',
      'ja': '両方！',
      'zh': '都是！',
      'es': '¡Las dos cosas!',
      'pt': 'As duas coisas!',
      'de': 'Beides!',
      'fr': 'Les deux !',
      'id': 'Dua-duanya!',
      'vi': 'Cả hai!',
    },
    'sc_w9_1_4': {
      'en': 'I still haven\'t forgotten that one square you took from me.',
      'ko': '네모 하나 뺏긴 거 아직 안 잊었어.',
      'ja': '四角一個取られたの、まだ忘れてないから。',
      'zh': '被你抢走一个方格的事我还没忘。',
      'es': 'Todavía no olvidé ese cuadrado que me quitaste.',
      'pt': 'Eu ainda não esqueci aquele quadradinho que você tomou de mim.',
      'de': 'Ich hab das eine Quadrat, das du mir weggeschnappt hast, immer noch nicht vergessen.',
      'fr': 'J\'ai pas encore oublié ce carré que tu m\'as pris.',
      'id': 'Aku masih belum lupa soal kotak yang kamu rebut itu.',
      'vi': 'Tớ vẫn chưa quên chuyện cậu cướp mất một ô vuông đâu.',
    },
    'sc_w9_1_5': {
      'en': 'That was a while ago, though.',
      'ko': '아까 건데.',
      'ja': 'さっきのことなのに。',
      'zh': '那是刚才的事啊。',
      'es': 'Pero eso fue hace un rato.',
      'pt': 'Mas isso foi ainda agora.',
      'de': 'Das war doch gerade eben.',
      'fr': 'Mais c\'était il y a pas longtemps.',
      'id': 'Tapi itu kan tadi doang.',
      'vi': 'Nhưng đó là chuyện nãy giờ thôi mà.',
    },
    'sc_w9_1_6': {
      'en': 'It\'s from earlier, so it still counts! I\'m NOT holding a grudge!',
      'ko': '아까 거니까 아직이지! 뒤끝 아니거든!',
      'ja': 'さっきのだから、まだ有効なの！根に持ってるわけじゃないし！',
      'zh': '是刚才的事，所以还算数！我才没记仇！',
      'es': '¡Fue hace rato, así que todavía cuenta! ¡NO te guardo rencor!',
      'pt': 'Foi agora há pouco, então ainda conta! Eu NÃO tô guardando rancor!',
      'de': 'Das war vorhin, also zählt\'s noch! Ich bin NICHT nachtragend!',
      'fr': 'C\'était tout à l\'heure, donc ça compte encore ! Je suis PAS rancunière !',
      'id': 'Itu yang tadi, jadi masih berlaku! Bukan dendam, ya!',
      'vi': 'Chuyện lúc nãy nên vẫn tính! Không phải thù dai đâu!',
    },
    'sc_w9_2_title': {
      'en': 'Pretending to Lose Out',
      'ko': '손해 보는 척',
      'ja': '損したふり',
      'zh': '假装吃亏',
      'es': 'Fingir que pierde',
      'pt': 'Fingindo prejuízo',
      'de': 'Verlust vortäuschen',
      'fr': 'Faire semblant d\'y perdre',
      'id': 'Pura-pura Rugi',
      'vi': 'Giả Vờ Chịu Thiệt',
    },
    'sc_w9_2_1': {
      'en': 'You gave me that box on purpose just now!',
      'ko': '너 방금 일부러 네모 하나 내준 거지!',
      'ja': 'あんた今、わざと箱一個くれたでしょ！',
      'zh': '你刚才是故意让我一个格子吧！',
      'es': '¡Me regalaste esa caja a propósito!',
      'pt': 'Você me deu essa caixa de propósito agora!',
      'de': 'Du hast mir das Kästchen gerade absichtlich überlassen!',
      'fr': 'Tu m\'as laissé ce carré exprès, là !',
      'id': 'Barusan kamu sengaja ngasih satu kotak, kan!',
      'vi': 'Vừa rồi cậu cố tình nhường một ô đúng không!',
    },
    'sc_w9_2_2': {
      'en': 'Caught, huh?',
      'ko': '들켰어?',
      'ja': 'バレた?',
      'zh': '被发现了?',
      'es': '¿Me descubriste?',
      'pt': 'Percebeu, né?',
      'de': 'Erwischt?',
      'fr': 'Grillée ?',
      'id': 'Ketahuan ya?',
      'vi': 'Bị lộ rồi hả?',
    },
    'sc_w9_2_3': {
      'en': 'Totally caught! I can see you pretending to lose out.',
      'ko': '들켰거든! 손해 보는 척하는 거 다 보여.',
      'ja': 'バレバレだから！損したふりしてるの、全部見えてる。',
      'zh': '被我发现了！装吃亏我全看出来了。',
      'es': '¡Te descubrí! Se nota que finges salir perdiendo.',
      'pt': 'Te peguei! Dá pra ver que você finge que tá perdendo.',
      'de': 'Erwischt! Ich seh genau, dass du nur so tust, als würdest du was verlieren.',
      'fr': 'Grillé ! Je vois bien que tu fais semblant d\'y perdre.',
      'id': 'Ketahuan! Pura-pura rugi gitu kelihatan semua.',
      'vi': 'Lộ rồi nhé! Giả vờ chịu thiệt là tớ thấy hết.',
    },
    'sc_w9_2_4': {
      'en': '...I can\'t do that kind of thing.',
      'ko': '…나는 그런 거 못 해.',
      'ja': '…私にはそういうの無理。',
      'zh': '……我做不到那种事。',
      'es': '...Yo no puedo hacer ese tipo de cosas.',
      'pt': '...Eu não consigo fazer esse tipo de coisa.',
      'de': '...So etwas kann ich nicht.',
      'fr': '...Moi, je peux pas faire ce genre de truc.',
      'id': '...Aku nggak bisa hal kayak gitu.',
      'vi': '...Tớ không làm được chuyện đó đâu.',
    },
    'sc_w9_2_5': {
      'en': 'Why?',
      'ko': '왜?',
      'ja': 'なんで?',
      'zh': '为什么?',
      'es': '¿Por qué?',
      'pt': 'Por quê?',
      'de': 'Warum?',
      'fr': 'Pourquoi ?',
      'id': 'Kenapa?',
      'vi': 'Sao vậy?',
    },
    'sc_w9_2_6': {
      'en': 'When I lose out, it shows on my face. E-especially in front of you!',
      'ko': '손해 보면 그냥 손해 본 얼굴이 돼. 너, 너 앞에선 특히!',
      'ja': '私は損したら、そのまま顔に出ちゃうの。あ、あんたの前では特に！',
      'zh': '我吃亏了就会直接写在脸上。在、在你面前尤其是！',
      'es': 'Cuando salgo perdiendo, se me nota en la cara. ¡S-sobre todo delante de ti!',
      'pt': 'Quando eu perco, aparece na minha cara. P-principalmente na sua frente!',
      'de': 'Wenn ich was verliere, sieht man\'s mir sofort an. V-vor allem vor dir!',
      'fr': 'Quand j\'y perds, ça se voit sur ma tête. S-surtout devant toi !',
      'id': 'Kalau aku rugi, mukaku langsung kelihatan rugi. A-apalagi di depan kamu!',
      'vi': 'Tớ mà chịu thiệt là lộ hết lên mặt. N-nhất là trước mặt cậu!',
    },
    'sc_w9_3_title': {
      'en': 'Together',
      'ko': '같이',
      'ja': '一緒に',
      'zh': '一起',
      'es': 'Juntos',
      'pt': 'Juntos',
      'de': 'Zusammen',
      'fr': 'Ensemble',
      'id': 'Bersama',
      'vi': 'Cùng Nhau',
    },
    'sc_w9_3_1': {
      'en': '...It felt like we were drawing a picture together. I liked that.',
      'ko': '…같이 그림 그리는 것 같아서 좋았어.',
      'ja': '…一緒に絵を描いてるみたいで、よかった。',
      'zh': '……感觉像是一起画画一样,挺开心的。',
      'es': '...Se sentía como si estuviéramos dibujando juntos. Me gustó.',
      'pt': '...Parecia que a gente tava desenhando junto. Eu gostei.',
      'de': '...Es fühlte sich an, als würden wir zusammen zeichnen. Das hat mir gefallen.',
      'fr': '...On aurait dit qu\'on dessinait ensemble. J\'ai aimé ça.',
      'id': '...Rasanya kayak lagi gambar bareng. Aku suka.',
      'vi': '...Cảm giác như tụi mình đang cùng nhau vẽ tranh vậy. Tớ thích thế.',
    },
    'sc_w9_3_2': {
      'en': 'What did you say?',
      'ko': '뭐라고?',
      'ja': '何て言った?',
      'zh': '你说什么?',
      'es': '¿Qué dijiste?',
      'pt': 'O que você disse?',
      'de': 'Was hast du gesagt?',
      'fr': 'Qu\'est-ce que t\'as dit ?',
      'id': 'Kamu bilang apa?',
      'vi': 'Cậu vừa nói gì?',
    },
    'sc_w9_3_3': {
      'en': 'N-nothing! Forget it!',
      'ko': '아, 아무것도! 잊어!',
      'ja': 'な、なんでもない！忘れて！',
      'zh': '没、没什么！忘掉！',
      'es': '¡N-nada! ¡Olvídalo!',
      'pt': 'N-nada! Esquece!',
      'de': 'N-nichts! Vergiss es!',
      'fr': 'R-rien ! Oublie !',
      'id': 'B-bukan apa-apa! Lupain!',
      'vi': 'K-không có gì! Quên đi!',
    },
    'sc_w9_3_4': {
      'en': 'I said forget it, so why are you smiling!',
      'ko': '잊으라고 했는데 왜 웃어!',
      'ja': '忘れてって言ったのに、なんで笑うの！',
      'zh': '都叫你忘掉了，你笑什么！',
      'es': '¡Te dije que lo olvidaras! ¡¿Por qué sonríes?!',
