      'id': 'Udah kubilang lupain, kok malah senyum!',
      'vi': 'Đã bảo quên đi, sao còn cười!',
    },
    'sc_w9_3_5': {
      'en': 'I wasn\'t smiling.',
      'ko': '안 웃었어.',
      'ja': '笑ってない。',
      'zh': '我没笑。',
      'es': 'No sonreí.',
      'pt': 'Eu não sorri.',
      'de': 'Hab ich nicht.',
      'fr': 'J\'ai pas souri.',
      'id': 'Nggak kok.',
      'vi': 'Có đâu.',
    },
    'sc_w9_3_6': {
      'en': 'You did! I saw! I saw everything!',
      'ko': '웃었거든! 봤어! 다 봤어!',
      'ja': '笑ったもん！見たよ！全部見た！',
