    'sc_w9_4_1': {
      'en': 'Dots and Boxes, done. The whole board is yours…',
      'ko': '점과 상자 끝. 판이 온통 네 거잖아…',
      'ja': '点と箱終わり。盤が全部あんたのじゃない…',
      'zh': '点格棋结束。整个棋盘都是你的……',
      'es': 'Puntos y cajas, terminado. El tablero entero es tuyo…',
      'pt': 'Pontos e caixas, concluído. O tabuleiro inteiro é seu…',
      'de': 'Käsekästchen geschafft. Das ganze Brett gehört dir…',
      'fr': 'Petits carrés, terminé. Tout le plateau est à toi…',
      'id': 'Titik dan Kotak selesai. Papannya penuh punyamu semua…',
      'vi': 'Chấm và ô xong rồi. Cả bàn toàn là của cậu…',
    },
    'sc_w9_4_2': {
      'en': 'I-I drew a picture in the art room. Want to see? If you want.',
      'ko': '미, 미술실에서 그림 하나 그렸어. 보여줄까. 보고 싶으면.',
      'ja': 'び、美術室で絵を一枚描いたの。見せようか。見たいなら。',
      'zh': '我、我在美术教室画了一幅画。要看吗。想看的话。',
      'es': 'H-hice un dibujo en la sala de arte. ¿Quieres verlo? Si quieres.',
      'pt': 'E-eu fiz um desenho na sala de arte. Quer ver? Se quiser.',
      'de': 'I-ich hab im Kunstraum ein Bild gemalt. Willst du\'s sehen? Wenn du willst.',
      'fr': 'J-j\'ai fait un dessin en arts plastiques. Tu veux voir ? Si tu veux.',
      'id': 'A-aku gambar sesuatu di ruang seni. Mau lihat? Kalau mau.',
      'vi': 'T-tớ vẽ một bức ở phòng mỹ thuật. Cho xem nhé? Nếu cậu muốn.',
    },
    'sc_w9_4_3': {
      'en': 'Yeah.',
      'ko': '응.',
      'ja': 'うん。',
      'zh': '嗯。',
      'es': 'Sí.',
      'pt': 'Sim.',
      'de': 'Ja.',
      'fr': 'Ouais.',
      'id': 'Iya.',
      'vi': 'Ừ.',
    },
    'sc_w9_4_4': {
      'en': 'One desk, two people. …It\'s bad. Don\'t laugh.',
      'ko': '책상 하나, 사람 둘. …잘 못 그렸어. 웃지 마.',
      'ja': '机が一つ、人が二人。…下手だけど。笑わないで。',
      'zh': '一张桌子，两个人。……画得不好。不许笑。',
      'es': 'Un pupitre, dos personas. …Me quedó feo. No te rías.',
      'pt': 'Uma carteira, duas pessoas. …Ficou feio. Não ri.',
      'de': 'Ein Tisch, zwei Leute. …Ist nicht gut geworden. Lach nicht.',
      'fr': 'Un bureau, deux personnes. …C\'est raté. Rigole pas.',
      'id': 'Satu meja, dua orang. …Gambarnya jelek. Jangan ketawa.',
      'vi': 'Một cái bàn, hai người. …Vẽ xấu lắm. Đừng cười.',
    },
    'sc_w9_4_5': {
      'en': 'Who is it?',
      'ko': '누구야?',
      'ja': '誰?',
      'zh': '是谁?',
      'es': '¿Quiénes son?',
      'pt': 'Quem são?',
      'de': 'Wer ist das?',
      'fr': 'C\'est qui ?',
      'id': 'Ini siapa?',
      'vi': 'Là ai vậy?',
    },
    'sc_w9_4_6': {
      'en': 'I-I don\'t know! Just two people!',
      'ko': '모, 몰라! 그냥 사람 둘이야!',
      'ja': 'し、知らない！ただの二人だよ！',
      'zh': '不、不知道！就是两个人而已！',
      'es': '¡N-no sé! ¡Solo son dos personas!',
      'pt': 'S-sei lá! São só duas pessoas!',
      'de': 'K-keine Ahnung! Einfach zwei Leute!',
      'fr': 'J-j\'en sais rien ! Juste deux personnes !',
      'id': 'N-nggak tahu! Cuma dua orang!',
      'vi': 'K-không biết! Chỉ là hai người thôi!',
    },
    'sc_w9_4_7': {
      'en': 'I won\'t erase it. Even something drawn badly is still a record.',
      'ko': '지우진 않을 거야. 잘 못 그린 것도 기록이니까.',
      'ja': '消さないよ。下手なのも記録だから。',
      'zh': '不会擦掉。就算画得不好也是记录。',
      'es': 'No lo voy a borrar. Hasta algo mal dibujado es un registro.',
      'pt': 'Não vou apagar. Mesmo malfeito, ainda é um registro.',
      'de': 'Ich werd\'s nicht wegwischen. Auch schlecht Gemaltes ist eine Aufzeichnung.',
      'fr': 'Je l\'effacerai pas. Même mal dessiné, ça reste un souvenir.',
      'id': 'Nggak bakal aku hapus. Meskipun gambarnya jelek, tetap catatan kok.',
      'vi': 'Tớ sẽ không xóa đâu. Vẽ xấu cũng là một kỷ niệm mà.',
    },
    'sc_w9_4_8': {
      'en': 'Can I draw one too?',
      'ko': '나도 하나 그려도 돼?',
      'ja': '私も一枚描いていい?',
      'zh': '我也可以画一张吗?',
      'es': '¿Puedo dibujar uno yo también?',
      'pt': 'Posso desenhar um também?',
      'de': 'Darf ich auch eins malen?',
      'fr': 'Je peux en dessiner un aussi ?',
      'id': 'Aku juga boleh gambar satu?',
      'vi': 'Tớ cũng vẽ một bức được không?',
    },
    'sc_w9_4_9': {
      'en': '...That\'s for later. Come to the club room. It\'s a game about avoiding triangles.',
      'ko': '…그건 나중에. 동아리실로 와. 삼각형 피하는 게임이야.',
      'ja': '…それは今度ね。部室に来て。三角形を避けるゲームだよ。',
      'zh': '……那个下次吧。到社团教室来。是躲避三角形的游戏。',
      'es': '...Eso para luego. Ven al club. Es un juego de evitar triángulos.',
      'pt': '...Isso fica pra depois. Vem pra sala do clube. É um jogo de evitar triângulos.',
      'de': '...Das ist für später. Komm zum Clubraum. Es ist ein Spiel, bei dem man Dreiecke vermeidet.',
      'fr': '...Ça, ce sera pour plus tard. Viens à la salle du club. C\'est un jeu où il faut éviter les triangles.',
      'id': '...Itu nanti aja. Ke ruang klub, yuk. Ini permainan menghindari segitiga.',
      'vi': '...Cái đó để sau đi. Đến phòng câu lạc bộ nhé. Là trò chơi tránh hình tam giác.',
    },
    'sc_w9_4_10': {
      'en': 'Triangle?',
      'ko': '삼각형?',
      'ja': '三角形?',
      'zh': '三角形?',
      'es': '¿Triángulos?',
      'pt': 'Triângulos?',
      'de': 'Dreiecke?',
      'fr': 'Des triangles ?',
      'id': 'Segitiga?',
      'vi': 'Tam giác á?',
    },
    'sc_w9_4_11': {
      'en': 'In that game I draw the first line. It\'s a rule!',
      'ko': '그 게임은 내가 먼저 한 줄 긋고 시작해. 규칙이야!',
      'ja': 'そのゲームは私が先に一本引いてから始めるの。ルールだから！',
      'zh': '那个游戏由我先画一条线开始。这是规则！',
      'es': 'En ese juego yo trazo la primera línea. ¡Es la regla!',
      'pt': 'Nesse jogo, eu traço a primeira linha. É a regra!',
      'de': 'Bei dem Spiel zieh ich die erste Linie. Das ist die Regel!',
      'fr': 'Dans ce jeu, c\'est moi qui trace le premier trait. C\'est la règle !',
      'id': 'Di game itu, aku yang tarik garis pertama. Aturannya!',
      'vi': 'Trò đó tớ kẻ đường đầu tiên rồi mới bắt đầu. Luật đấy!',
    },
    'sc_w9_4_12': {
      'en': '…No, it\'s an excuse. Happy?',
      'ko': '…아니, 핑계야. 됐지?',
      'ja': '…ううん、言い訳。これでいい？',
      'zh': '……不对，是借口。行了吧？',
      'es': '…No, es una excusa. ¿Feliz?',
      'pt': '…Não, é desculpa. Tá bom assim?',
      'de': '…Nein, das ist eine Ausrede. Zufrieden?',
      'fr': '…Non, c\'est une excuse. Ça te va ?',
      'id': '…Nggak, itu alasan doang. Puas?',
      'vi': '…Không, là cái cớ thôi. Được chưa?',
    },
    'sc_w10_1_title': {
      'en': 'Key',
      'ko': '열쇠',
      'ja': '鍵',
      'zh': '钥匙',
      'es': 'Llave',
      'pt': 'Chave',
      'de': 'Schlüssel',
      'fr': 'Clé',
      'id': 'Kunci',
      'vi': 'Chìa khóa',
    },
    'sc_w10_1_1': {
      'en': 'I have the club room key. You can\'t escape!',
      'ko': '동아리실 열쇠는 내가 갖고 있어. 도망 못 가!',
      'ja': '部室の鍵は私が持ってるの。逃げられないよ！',
      'zh': '社团活动室的钥匙在我这。你跑不掉的！',
      'es': 'Yo tengo la llave de la sala del club. ¡No te puedes escapar!',
      'pt': 'A chave da sala do clube tá comigo. Você não tem como fugir!',
      'de': 'Ich hab den Schlüssel zum Clubraum. Kein Entkommen!',
      'fr': 'C\'est moi qui ai la clé de la salle du club. Pas moyen de t\'échapper !',
      'id': 'Kunci ruang klub ada di aku. Nggak bisa kabur!',
      'vi': 'Chìa khóa phòng câu lạc bộ tớ giữ. Đừng hòng trốn!',
    },
    'sc_w10_1_2': {
      'en': 'I wasn\'t planning to run.',
      'ko': '도망칠 생각 없는데.',
      'ja': '逃げるつもりないけど。',
      'zh': '我没打算逃跑。',
      'es': 'No pensaba escaparme.',
      'pt': 'Eu não pretendia fugir.',
      'de': 'Ich hatte nicht vor abzuhauen.',
      'fr': 'J\'avais pas l\'intention de m\'enfuir.',
      'id': 'Aku tidak berniat kabur.',
      'vi': 'Tớ đâu định trốn.',
    },
    'sc_w10_1_3': {
      'en': 'S-still! Having it makes me feel safe.',
      'ko': '그, 그래도! 갖고 있는 게 안심되니까.',
      'ja': 'で、でも！持ってると安心するから。',
      'zh': '可、可是！拿着比较安心嘛。',
      'es': '¡A-aun así! Tenerla me da tranquilidad.',
      'pt': 'M-mesmo assim! Ter ela comigo me deixa tranquila.',
      'de': 'T-trotzdem! Wenn ich ihn hab, fühl ich mich sicherer.',
      'fr': 'Q-quand même ! L\'avoir sur moi, ça me rassure.',
      'id': 'T-tetap aja! Pegang kuncinya bikin tenang.',
      'vi': 'D-dù vậy! Giữ nó tớ thấy yên tâm.',
    },
    'sc_w10_1_4': {
      'en': 'Avoiding triangles... kind of like life, don\'t you think?',
      'ko': '삼각형 피하는 거, 인생 같지 않아?',
      'ja': '三角形を避けるのって、人生みたいじゃない?',
      'zh': '躲避三角形这件事,是不是有点像人生?',
      'es': 'Evitar triángulos... ¿no se parece un poco a la vida?',
      'pt': 'Evitar triângulos... não parece um pouco com a vida?',
      'de': 'Dreiecke zu vermeiden – ist das nicht irgendwie wie das Leben?',
      'fr': 'Éviter les triangles... ça ressemble un peu à la vie, non?',
      'id': 'Menghindari segitiga itu... mirip kehidupan, bukan?',
      'vi': 'Né tam giác... có giống cuộc sống không nhỉ?',
    },
    'sc_w10_1_5': {
      'en': 'In what way?',
      'ko': '어떤 점이?',
      'ja': 'どういうところが?',
      'zh': '哪里像了?',
      'es': '¿En qué sentido?',
      'pt': 'Em que sentido?',
      'de': 'Inwiefern?',
      'fr': 'En quoi?',
      'id': 'Mirip bagaimana?',
      'vi': 'Giống ở chỗ nào?',
    },
    'sc_w10_1_6': {
      'en': 'No matter how hard you try to avoid it, if it\'s fate, you end up meeting.',
      'ko': '피하려고 피하려고 해도 운명이면 결국 만나게 된다는 점.',
      'ja': '避けようとしても避けようとしても、運命ならいつか出会っちゃうってこと。',
      'zh': '怎么躲也躲不掉，是命运的话终究会相遇。',
      'es': 'Por más que intentes evitarlo, si es el destino, al final te encuentras.',
      'pt': 'Por mais que você tente evitar, se for destino, no fim acaba encontrando.',
      'de': 'Egal wie sehr man ausweicht, wenn\'s Schicksal ist, trifft man sich am Ende doch.',
      'fr': 'On a beau l\'éviter, si c\'est le destin, on finit toujours par se croiser.',
      'id': 'Mau dihindari kayak gimana pun, kalau udah takdir, akhirnya ketemu juga.',
      'vi': 'Có né thế nào đi nữa, nếu là định mệnh thì cuối cùng vẫn gặp.',
    },
    'sc_w10_2_title': {
      'en': 'Why I Go First',
      'ko': '먼저 긋는 이유',
      'ja': '先に引く理由',
      'zh': '先落子的理由',
      'es': 'La razón para trazar primero',
      'pt': 'O motivo de traçar primeiro',
      'de': 'Der Grund, zuerst zu ziehen',
      'fr': 'La raison de tracer en premier',
      'id': 'Alasan Menggaris Duluan',
      'vi': 'Lý do vẽ trước',
    },
    'sc_w10_2_1': {
      'en': 'In Sim, going second is the advantage.',
      'ko': '심은 나중에 두는 쪽이 유리한 게임이야.',
      'ja': 'シムは後に打つ方が有利なゲームなの。',
      'zh': 'Sim游戏是后下的一方更有利。',
      'es': 'En Sim, jugar segundo es la ventaja.',
      'pt': 'No Sim, jogar por último é vantagem.',
      'de': 'Bei Sim ist es von Vorteil, als Zweiter zu ziehen.',
      'fr': 'Dans Sim, c\'est celui qui joue en second qui a l\'avantage.',
      'id': 'Dalam Sim, giliran kedua yang lebih diuntungkan.',
      'vi': 'Trong Sim, đi sau mới có lợi thế.',
    },
    'sc_w10_2_2': {
      'en': 'So that\'s why you go first?',
      'ko': '그래서 네가 먼저 긋는 거야?',
      'ja': 'だから先に引くの?',
      'zh': '所以你才先画的?',
      'es': '¿Por eso trazas tú primero?',
      'pt': 'Por isso você traça primeiro?',
      'de': 'Deshalb ziehst du zuerst?',
      'fr': 'C\'est pour ça que tu traces en premier?',
      'id': 'Makanya kau yang duluan menggaris?',
      'vi': 'Nên cậu mới vẽ trước à?',
    },
    'sc_w10_2_3': {
      'en': 'Yeah. So you can win.',
      'ko': '응. 네가 이길 수 있게.',
      'ja': 'うん。あんたが勝てるように。',
      'zh': '嗯。为了让你赢。',
      'es': 'Sí. Para que puedas ganar.',
      'pt': 'É. Pra você poder ganhar.',
      'de': 'Ja. Damit du gewinnen kannst.',
      'fr': 'Oui. Pour que tu puisses gagner.',
      'id': 'Iya. Supaya kau bisa menang.',
      'vi': 'Ừ. Để cậu có thể thắng.',
    },
    'sc_w10_2_4': {
      'en': 'I-I\'m not going easy! I\'m making it fair!',
      'ko': '보, 봐주는 거 아니야! 공평하게 만드는 거야!',
      'ja': 'て、手加減じゃないから！公平にしてるだけ！',
      'zh': '才、才不是让你！是为了公平！',
      'es': '¡N-no te estoy dejando ganar! ¡Lo estoy haciendo justo!',
      'pt': 'N-não tô pegando leve! Tô deixando justo!',
      'de': 'I-ich schone dich nicht! Ich mach\'s nur fair!',
      'fr': 'J-je te fais pas de cadeau ! Je rends juste les choses équitables !',
      'id': 'A-aku nggak ngalah! Aku bikin adil!',
      'vi': 'T-tớ không nhường! Tớ làm cho công bằng thôi!',
    },
    'sc_w10_2_5': {
      'en': 'What does \'fair\' even mean?',
      'ko': '공평한 게 뭔데?',
      'ja': '公平って何?',
      'zh': '公平是什么?',
      'es': '¿Y qué es justo?',
      'pt': 'E o que é justo?',
      'de': 'Was heißt schon fair?',
      'fr': 'C\'est quoi, équitable?',
      'id': 'Apa itu adil?',
      'vi': 'Công bằng là sao?',
    },
    'sc_w10_2_6': {
      'en': 'I\'m not sure. But… with you, I want to. J-just this once!',
      'ko': '잘 모르겠어. 근데… 너한테는 그러고 싶어. 이, 이번만!',
      'ja': 'よくわかんない。でも…あんたにはそうしたいの。こ、今回だけ！',
      'zh': '我也不太清楚。不过……对你我想这么做。就、就这一次！',
      'es': 'No sé bien. Pero… contigo quiero hacerlo. ¡S-solo esta vez!',
      'pt': 'Não sei bem. Mas… com você eu quero. S-só dessa vez!',
      'de': 'Weiß nicht genau. Aber… bei dir will ich das. N-nur dieses eine Mal!',
      'fr': 'Je sais pas trop. Mais… avec toi, j\'ai envie. J-juste cette fois !',
      'id': 'Nggak tahu. Tapi… sama kamu, aku mau gitu. K-kali ini aja!',
      'vi': 'Tớ không chắc. Nhưng… với cậu thì tớ muốn vậy. L-lần này thôi!',
    },
    'sc_w10_3_title': {
      'en': 'Side',
      'ko': '편',
      'ja': '味方',
      'zh': '阵营',
      'es': 'Bando',
      'pt': 'Lado',
      'de': 'Seite',
      'fr': 'Camp',
      'id': 'Pihak',
      'vi': 'Phe',
    },
    'sc_w10_3_1': {
      'en': 'All six dots were on your side. So unfair.',
      'ko': '여섯 개 점이 다 너 편이더라. 치사해.',
      'ja': '六つの点、全部あんたの味方だった。ずるい。',
      'zh': '六个点全站你那边。真狡猾。',
      'es': 'Los seis puntos estaban de tu lado. Qué injusto.',
      'pt': 'Os seis pontos estavam do seu lado. Injusto.',
