      'ko': '…그, 글쎄.',
      'ja': '…さ、さあね。',
      'zh': '……谁、谁知道呢。',
      'es': '…P-pues, quién sabe.',
      'pt': '…S-será?',
      'de': '…T-tja.',
      'fr': '…B-bah.',
      'id': '…E-entahlah.',
      'vi': '…C-cũng chưa chắc.',
    },
    'sc_w10_3_4': {
      'en': 'Hmm… but actually, dots don\'t take sides. The lines decide, probably?',
      'ko': '으음.. 근데, 사실 점은 편이 없어. 선이 정하는 거겠지, 아마?',
      'ja': 'うーん…でも、ほんとは点に味方なんてないの。線が決めるんだと思う、たぶん？',
      'zh': '嗯……不过其实点是不分边的。应该是线决定的吧，大概？',
      'es': 'Mmm… aunque, en realidad, los puntos no tienen bando. Lo deciden las líneas, ¿creo?',
