      'de': 'Hmm… aber eigentlich gehören Punkte zu keiner Seite. Das entscheiden wohl die Linien, oder?',
      'fr': 'Hmm… mais en fait, les points sont dans aucun camp. C\'est les traits qui décident, sans doute ?',
      'id': 'Hmm… tapi sebenarnya titik nggak punya pihak. Garis yang nentuin, mungkin?',
      'vi': 'Ừm… mà thật ra chấm đâu có phe. Chắc là đường kẻ quyết định?',
    },
    'sc_w10_3_5': {
      'en': 'Then what about the line?',
      'ko': '그럼 선은?',
      'ja': 'じゃあ線は?',
      'zh': '那线呢?',
