    'sc_w10_4_1': {
      'en': 'Twenty games of Sim. Not a single triangle. Hmph, impressive.',
      'ko': '심 스무 판. 삼각형 하나도 안 만들었네. 흥, 대단하네.',
      'ja': 'シム二十回。三角形一つも作らなかったね。ふん、すごいじゃない。',
      'zh': '西姆二十局。一个三角形都没做出来。哼，真厉害。',
      'es': 'Veinte partidas de Sim. Ni un solo triángulo. Hmpf, impresionante.',
      'pt': 'Vinte partidas de Sim. Nenhum triângulo. Hmpf, impressionante.',
