    'sc_w10_4_2': {
      'en': 'I started this club alone in first year. One member: me.',
      'ko': '동아리실은 내가 1학년 때 혼자 만들었어. 부원은 나 하나.',
      'ja': '部室は私が一年の時に一人で作ったの。部員は私だけ。',
      'zh': '活动室是我高一时一个人建的。社员只有我一个。',
      'es': 'Este club lo fundé yo sola en primer año. Miembros: solo yo.',
      'pt': 'Fundei esse clube sozinha no primeiro ano. Membros: só eu.',
      'de': 'Den Club hab ich im ersten Jahr allein gegründet. Einziges Mitglied: ich.',
      'fr': 'J\'ai fondé ce club toute seule, en première année. Unique membre : moi.',
      'id': 'Ruang klub ini aku bikin sendiri waktu kelas satu. Anggotanya cuma aku.',
      'vi': 'Phòng câu lạc bộ này tớ tự lập hồi năm nhất. Thành viên chỉ có tớ.',
