    'sc_w10_4_3': {
      'en': 'By yourself?',
      'ko': '혼자서?',
      'ja': '一人で?',
      'zh': '一个人?',
      'es': '¿Tú sola?',
      'pt': 'Sozinha?',
      'de': 'Ganz allein?',
      'fr': 'Toute seule?',
      'id': 'Sendirian?',
      'vi': 'Một mình à?',
    },
    'sc_w10_4_4': {
      'en': 'It\'s called math club, but all we did was play games. Don\'t laugh!',
      'ko': '이름은 수학 동아리인데 하는 건 게임뿐이었어. 웃지 마!',
      'ja': '名前は数学部なのに、やってたのはゲームばっかり。笑わないで！',
      'zh': '名字叫数学社，干的却全是游戏。不许笑！',
      'es': 'Se llama club de matemáticas, pero aquí solo se jugaba. ¡No te rías!',
      'pt': 'Se chama clube de matemática, mas aqui só se jogava. Não ri!',
      'de': 'Er heißt Mathe-AG, aber wir haben nur gespielt. Lach nicht!',
      'fr': 'Ça s\'appelle le club de maths, mais on faisait que jouer. Rigole pas !',
      'id': 'Namanya klub matematika, tapi kerjanya cuma main game. Jangan ketawa!',
      'vi': 'Tên là câu lạc bộ toán mà toàn chơi game. Đừng cười!',
