    'sc_w10_4_5': {
      'en': 'And now?',
      'ko': '지금은?',
      'ja': '今は?',
      'zh': '现在呢?',
      'es': '¿Y ahora?',
      'pt': 'E agora?',
      'de': 'Und jetzt?',
      'fr': 'Et maintenant?',
      'id': 'Sekarang?',
      'vi': 'Còn bây giờ?',
    },
    'sc_w10_4_6': {
      'en': '…Two members. No applications. Two is enough.',
      'ko': '…부원 두 명. 신청서는 안 받아. 그냥 두 명이면 돼.',
      'ja': '…部員は二人。入部届はいらない。二人いればそれでいいの。',
      'zh': '……社员两个人。不收申请表。两个人就够了。',
      'es': '…Dos miembros. No acepto solicitudes. Con dos basta.',
      'pt': '…Dois membros. Não aceito inscrição. Dois já basta.',
      'de': '…Zwei Mitglieder. Keine Anmeldungen. Zwei reichen.',
      'fr': '…Deux membres. Pas de candidatures. Deux, ça suffit.',
      'id': '…Anggota dua orang. Nggak terima formulir. Dua orang aja cukup.',
      'vi': '…Thành viên hai người. Không nhận đơn. Hai người là đủ.',
    },
    'sc_w10_4_7': {
      'en': 'Oh right! We\'re growing flowers in the school greenhouse.',
      'ko': '아 맞다! 우리 학교 온실에 꽃을 키우고 있거든.',
      'ja': 'あ、そうだ！うちの学校の温室で花を育ててるの。',
      'zh': '啊对了！我们在学校温室里种了花。',
      'es': '¡Ah, cierto! En el invernadero de la escuela estamos cultivando flores.',
      'pt': 'Ah, é! A gente tá cultivando flores na estufa da escola.',
      'de': 'Ach ja! Wir ziehen im Gewächshaus der Schule Blumen.',
      'fr': 'Ah oui ! On fait pousser des fleurs dans la serre de l\'école.',
      'id': 'Oh iya! Kita lagi nanam bunga di rumah kaca sekolah.',
      'vi': 'À đúng rồi! Tụi mình đang trồng hoa trong nhà kính của trường.',
    },
    'sc_w10_4_8': {
      'en': 'What kind of flowers?',
      'ko': '어떤 꽃?',
      'ja': 'どんな花？',
      'zh': '什么花？',
      'es': '¿Qué flores?',
      'pt': 'Que flores?',
      'de': 'Was für Blumen?',
      'fr': 'Quel genre de fleurs ?',
      'id': 'Bunga apa?',
      'vi': 'Hoa gì thế?',
    },
    'sc_w10_4_9': {
      'en': 'Haha. I\'ll tell you when they bloom.',
      'ko': '우하하. 다 자라면 말해줄게.',
      'ja': 'あはは。咲いたら教えてあげる。',
      'zh': '哈哈。等开花了再告诉你。',
      'es': 'Jejeje. Te digo cuando florezcan.',
      'pt': 'Hehehe. Te conto quando florescerem.',
      'de': 'Uhaha. Verrat ich dir, wenn sie blühen.',
      'fr': 'Ouhaha. Je te dirai quand elles auront fleuri.',
      'id': 'Ahaha. Nanti kukasih tahu kalau udah mekar.',
      'vi': 'Haha. Khi nào nở tớ nói cho.',
    },
    'sc_w10_4_10': {
      'en': 'Who\'s watering them?',
      'ko': '물은 누가 줘?',
      'ja': '水は誰があげるの?',
      'zh': '水谁来浇?',
      'es': '¿Y quién las riega?',
      'pt': 'E quem rega elas?',
      'de': 'Und wer gießt sie?',
      'fr': 'Et qui les arrose?',
      'id': 'Siapa yang menyiraminya?',
      'vi': 'Ai tưới nước cho chúng?',
    },
    'sc_w10_4_11': {
      'en': 'I\'ll do it. Oh, how about we play, and the loser waters them next time?',
      'ko': '내가 줄 거야. 아, 또 게임을 해서 지는 쪽이 다음에 물 주기로 하는 건 어때?',
      'ja': '私があげる。あ、またゲームして、負けたほうが次に水やりするのはどう？',
      'zh': '我来浇。啊，要不再玩一局，输的人下次浇水怎么样？',
      'es': 'Yo las riego. Ah, ¿y si jugamos y quien pierda las riega la próxima vez?',
      'pt': 'Eu rego. Ah, que tal a gente jogar e quem perder rega da próxima vez?',
      'de': 'Mach ich. Ach, wie wär\'s: Wir spielen, und wer verliert, gießt nächstes Mal?',
      'fr': 'C\'est moi qui les arrose. Oh, et si on jouait, et que le perdant arrose la prochaine fois ?',
      'id': 'Aku yang siram. Oh, gimana kalau kita main, terus yang kalah nyiram berikutnya?',
      'vi': 'Tớ tưới. À, hay mình chơi một ván, ai thua thì lần sau tưới?',
    },
    'sc_w10_4_12': {
      'en': 'Let\'s go!',
      'ko': '가보자고!',
      'ja': '行こうか！',
      'zh': '走起！',
      'es': '¡Vamos!',
      'pt': 'Bora!',
      'de': 'Na dann los!',
      'fr': 'C\'est parti !',
      'id': 'Ayo!',
      'vi': 'Chiến thôi!',
    },
    'sc_w11_1_title': {
