      'vi': 'Sinh mệnh',
    },
    'sc_w11_2_1': {
      'en': 'Up to three lines per dot. That\'s the most life a dot can have.',
      'ko': '점 하나에 선 세 개까지. 그게 그 점의 생명의 최대치라고.',
      'ja': '一つの点に線は三本まで。それがその点の命の最大値なの。',
      'zh': '一个点最多连三条线。那就是这个点生命的上限。',
      'es': 'Hasta tres líneas por punto. Esa es la vida máxima de un punto.',
