      'fr': 'Et si un nouveau point apparaît?',
      'id': 'Kalau muncul titik baru?',
      'vi': 'Nếu có chấm mới xuất hiện thì sao?',
    },
    'sc_w11_2_3': {
      'en': 'So it gains one more life.',
      'ko': '생명이 하나 느는 셈이지.',
      'ja': '命が一つ増えるってことか。',
      'zh': '等于多了一条命。',
      'es': 'O sea, gana una vida más.',
      'pt': 'Ou seja, ganha mais uma vida.',
