      'fr': 'Donc ça fait une vie de plus.',
      'id': 'Berarti nambah satu nyawa.',
      'vi': 'Coi như thêm một sinh mệnh.',
    },
    'sc_w11_2_4': {
      'en': '…Isn\'t that kind of like people? Meet, and there\'s one more… gasp!',
      'ko': '…좀 사람 같지 않아? 만나면 하나 늘어나는 거.. 헉!',
      'ja': '…ちょっと人みたいじゃない？出会うと一つ増えるって…はっ！',
      'zh': '……是不是有点像人？相遇了就多一个……啊！',
      'es': '…¿No se parece un poco a las personas? Se encuentran y hay uno más… ¡Ay!',
      'pt': '…Não parece um pouco com pessoas? Se encontram e aparece mais um… Ai!',
      'de': '…Ist das nicht ein bisschen wie bei Menschen? Man trifft sich, und es wird einer mehr… huch!',
      'fr': '…C\'est un peu comme les gens, non ? On se rencontre, et on est un de plus… oups !',
      'id': '…Agak mirip manusia, nggak? Kalau ketemu, nambah satu… eh!',
      'vi': '…Hơi giống con người nhỉ? Gặp nhau là thêm một… ối!',
    },
    'sc_w11_2_5': {
      'en': 'Human?',
      'ko': '사람?',
      'ja': '人間?',
      'zh': '人?',
      'es': '¿Personas?',
      'pt': 'Pessoas?',
      'de': 'Menschlich?',
      'fr': 'Les humains?',
      'id': 'Manusia?',
      'vi': 'Con người?',
    },
    'sc_w11_2_6': {
      'en': 'No, no! Not people, I-I\'m talking about plants! It\'s a greenhouse!',
      'ko': '아니, 아니! 사람이 아니라 시, 식물 얘기야! 온실이니까!',
      'ja': 'ち、違う違う！人じゃなくて、しょ、植物の話！温室だから！',
      'zh': '不、不对不对！不是人，是说植、植物！这里是温室嘛！',
      'es': '¡No, no! ¡No hablo de personas, hablo de p-plantas! ¡Es un invernadero!',
