    'sc_w11_3_1': {
      'en': 'You\'re growing like a sprout.',
      'ko': '너, 새싹처럼 쑥쑥 늘고 있어.',
      'ja': 'あんた、新芽みたいにぐんぐん伸びてる。',
      'zh': '你啊，像新芽一样蹭蹭地长。',
      'es': 'Estás creciendo como un brote.',
      'pt': 'Você tá crescendo feito broto.',
