    },
    'sc_w11_3_4': {
      'en': 'Sprouts grow where you can\'t see it. That\'s why you don\'t notice.',
      'ko': '새싹은 안 보이게 자라니까 모르는 거야.',
      'ja': '新芽は見えないところで育つから分かんないの。',
      'zh': '新芽是看不见的地方长大的,所以才不知道。',
      'es': 'Los brotes crecen donde no se ve, por eso no te das cuenta.',
      'pt': 'Brotos crescem onde não dá pra ver, por isso você não percebe.',
      'de': 'Sprösslinge wachsen unsichtbar, deshalb merkt man\'s nicht.',
      'fr': 'Les pousses grandissent là où on les voit pas, c\'est pour ça qu\'on remarque rien.',
      'id': 'Kecambah tumbuh tanpa terlihat, makanya kau tidak sadar.',
      'vi': 'Mầm cây lớn lên ở chỗ không thấy được, nên mới không biết đấy thôi.',
    },
    'sc_w11_3_5': {
      'en': 'I can see it, though.',
      'ko': '보이는데.',
      'ja': '見えるけど。',
      'zh': '我能看见啊。',
      'es': 'Pero se te ve.',
      'pt': 'Mas dá pra ver.',
      'de': 'Aber ich seh\'s doch.',
      'fr': 'Mais je le vois, moi.',
      'id': 'Padahal aku bisa melihatnya.',
      'vi': 'Nhưng tớ thấy được mà.',
    },
    'sc_w11_3_6': {
      'en': '…Then don\'t look! Stop staring!',
      'ko': '…그럼 보지 마! 쳐다보지 말라고!',
      'ja': '…じゃあ見ないで！じろじろ見ないでってば！',
      'zh': '……那就别看！不许盯着我看！',
      'es': '…¡Entonces no mires! ¡Deja de mirarme!',
      'pt': '…Então não olha! Para de me encarar!',
      'de': '…Dann schau nicht! Hör auf zu starren!',
      'fr': '…Alors regarde pas ! Arrête de me fixer !',
      'id': '…Kalau gitu jangan lihat! Jangan ngeliatin!',
      'vi': '…Thế thì đừng nhìn! Đừng có nhìn chằm chằm!',
    },
    'sc_w11_4_title': {
      'en': 'The Sprout in the Greenhouse',
      'ko': '온실의 새싹',
      'ja': '温室の新芽',
      'zh': '温室的新芽',
      'es': 'El brote del invernadero',
      'pt': 'O broto da estufa',
      'de': 'Der Sprössling im Gewächshaus',
      'fr': 'La pousse de la serre',
      'id': 'Kecambah di Rumah Kaca',
      'vi': 'Mầm non trong nhà kính',
    },
    'sc_w11_4_1': {
      'en': 'Sprouts, done. The greenhouse sprouts are all grown!',
      'ko': '스프라우트 끝. 온실 새싹도 다 자랐다!',
      'ja': 'スプラウト終わり。温室の新芽も全部育った！',
      'zh': '豆芽结束。温室的新芽也全长大了！',
      'es': 'Brotes, terminado. ¡Los brotes del invernadero ya crecieron!',
      'pt': 'Brotos, concluído. Os brotos da estufa já cresceram!',
      'de': 'Sprouts geschafft. Die Keimlinge im Gewächshaus sind auch groß!',
      'fr': 'Sprouts, terminé. Les pousses de la serre ont fini de grandir !',
      'id': 'Sprouts selesai. Tunas di rumah kaca juga udah tumbuh semua!',
      'vi': 'Mầm cây xong rồi. Mầm trong nhà kính cũng lớn hết rồi!',
    },
    'sc_w11_4_2': {
      'en': 'I planted them the day you first came here. The day of the four candies.',
      'ko': '네가 처음 온 날 심은 거야. 사탕 네 개 하던 날.',
      'ja': 'あんたが初めて来た日に植えたの。飴四個の日。',
      'zh': '是你第一次来的那天种下的。吃四颗糖那天。',
      'es': 'Los planté el día que viniste por primera vez. El día de los cuatro caramelos.',
      'pt': 'Plantei no dia em que você veio pela primeira vez. O dia dos quatro doces.',
      'de': 'Ich hab sie an dem Tag gepflanzt, an dem du zum ersten Mal herkamst. Der Tag mit den vier Bonbons.',
      'fr': 'Je les ai plantées le jour où t\'es venu pour la première fois. Le jour des quatre bonbons.',
      'id': 'Kutanam di hari pertama kau datang ke sini. Hari yang ada empat permennya itu.',
      'vi': 'Tớ trồng vào ngày cậu đến đây lần đầu. Ngày có bốn viên kẹo ấy.',
    },
    'sc_w11_4_3': {
      'en': 'That day?',
      'ko': '그날?',
      'ja': 'あの日?',
      'zh': '那天?',
      'es': '¿Ese día?',
      'pt': 'Naquele dia?',
      'de': 'An dem Tag?',
      'fr': 'Ce jour-là?',
      'id': 'Hari itu?',
      'vi': 'Ngày đó à?',
    },
    'sc_w11_4_4': {
      'en': 'I didn\'t say. If I did… I thought you wouldn\'t come.',
      'ko': '말 안 했지. 말하면… 네가 안 올까 봐.',
      'ja': '言わなかったの。言ったら…あんたが来なくなるかもって。',
      'zh': '我没说。要是说了……怕你就不来了。',
      'es': 'No te lo dije. Si te lo decía… pensé que no vendrías.',
      'pt': 'Eu não falei. Se eu falasse… achei que você não ia vir.',
      'de': 'Hab ich nicht gesagt. Ich dachte… sonst kommst du nicht.',
      'fr': 'Je l\'ai pas dit. Si je l\'avais dit… j\'avais peur que tu viennes pas.',
      'id': 'Nggak kubilang. Kalau kubilang… takutnya kamu nggak datang.',
      'vi': 'Tớ không nói. Nói ra thì… sợ cậu không đến.',
    },
    'sc_w11_4_5': {
      'en': 'Why wouldn\'t I come?',
      'ko': '왜 안 와?',
      'ja': 'なんで来なくなるの?',
      'zh': '为什么会不来?',
      'es': '¿Por qué no iba a volver?',
      'pt': 'Por que eu não voltaria?',
      'de': 'Warum sollte ich nicht mehr kommen?',
      'fr': 'Pourquoi je serais plus revenu?',
      'id': 'Kenapa memangnya aku jadi tidak datang?',
      'vi': 'Sao lại không đến?',
    },
    'sc_w11_4_6': {
      'en': 'I-in case it was too much! …They\'re grown now, so I can say it.',
      'ko': '부, 부담스러울까 봐! …다 자랐으니까 이제 말해도 되겠지.',
      'ja': 'お、重いかなって思って！…もう全部育ったから、言ってもいいよね。',
      'zh': '怕、怕你有负担！……现在都长大了，应该可以说了吧。',
      'es': '¡P-por si te parecía demasiado! …Ya crecieron, así que ya puedo decirlo.',
      'pt': 'P-pra não pesar pra você! …Já cresceram, então agora posso falar.',
      'de': 'F-falls es dir zu viel wäre! …Jetzt sind sie groß, da kann ich\'s ja sagen.',
      'fr': 'A-au cas où ça te mettrait la pression ! …Elles ont poussé, alors je peux le dire.',
      'id': 'T-takut kamu terbebani! …Udah tumbuh semua, jadi sekarang boleh bilang, kan.',
      'vi': 'S-sợ cậu thấy nặng nề! …Lớn hết rồi nên giờ nói được rồi nhỉ.',
    },
    'sc_w11_4_7': {
      'en': 'Last stop is the board game club. Hex. A game with no draws.',
      'ko': '마지막은 보드게임부야. 헥스. 비기는 판이 없는 게임.',
      'ja': '最後はボードゲーム部。ヘックス。引き分けのないゲーム。',
      'zh': '最后是棋牌社。Hex。一个不会平局的游戏。',
      'es': 'Lo último es el club de juegos de mesa. Hex. Un juego sin empates.',
      'pt': 'O último é o clube de jogos de tabuleiro. Hex. Um jogo sem empates.',
      'de': 'Als Letztes kommt der Brettspielclub. Hex. Ein Spiel ohne Unentschieden.',
      'fr': 'La dernière étape, c\'est le club de jeux de société. Hex. Un jeu sans match nul.',
      'id': 'Terakhir klub board game. Hex. Permainan yang tidak pernah seri.',
      'vi': 'Cuối cùng là câu lạc bộ board game. Hex. Trò chơi không có hòa.',
    },
    'sc_w11_4_8': {
      'en': 'No draws at all?',
      'ko': '비기는 게 없어?',
      'ja': '引き分けがないの?',
      'zh': '不会平局吗?',
      'es': '¿No hay empates?',
      'pt': 'Não tem empate mesmo?',
      'de': 'Gibt\'s wirklich kein Unentschieden?',
      'fr': 'Y a vraiment jamais match nul?',
      'id': 'Tidak pernah seri?',
      'vi': 'Không bao giờ hòa à?',
    },
    'sc_w11_4_9': {
      'en': 'Yeah. Someone always connects in the end.',
      'ko': '응. 누군가는 반드시 이어지는 게임이거든.',
      'ja': 'うん。誰かが必ずつながるゲームなの。',
      'zh': '嗯。这是一定会有人连通的游戏。',
      'es': 'Sí. Es un juego donde alguien siempre termina conectando.',
      'pt': 'É. É um jogo em que alguém sempre acaba conectando.',
      'de': 'Ja. Bei dem Spiel verbindet am Ende immer einer.',
      'fr': 'Ouais. Dans ce jeu, quelqu\'un finit toujours par relier.',
      'id': 'Iya. Game yang pasti ada yang nyambung.',
      'vi': 'Ừ. Trò này kiểu gì cũng có người nối được.',
    },
    'sc_w11_4_10': {
      'en': 'Us too?',
      'ko': '우리도?',
      'ja': '私たちも?',
      'zh': '我们也是吗?',
      'es': '¿Nosotros también?',
      'pt': 'A gente também?',
      'de': 'Wir auch?',
      'fr': 'Nous aussi?',
      'id': 'Kita juga begitu?',
      'vi': 'Chúng ta cũng vậy sao?',
    },
    'sc_w11_4_11': {
      'en': 'W-we\'re like that too. There\'s no draw.',
      'ko': '우, 우리도 그렇잖아. 비기는 건 없어.',
      'ja': 'わ、私たちもそうでしょ。引き分けはないの。',
      'zh': '我、我们也是这样吧。没有平局。',
      'es': 'N-nosotros también somos así. No hay empate.',
      'pt': 'A-a gente também é assim. Não tem empate.',
      'de': 'W-wir sind doch auch so. Unentschieden gibt\'s nicht.',
      'fr': 'N-nous aussi, on est comme ça. Y a pas de match nul.',
      'id': 'K-kita juga gitu, kan. Nggak ada seri.',
      'vi': 'T-tụi mình cũng vậy mà. Không có hòa.',
    },
    'sc_w11_4_12': {
      'en': '…I\'ll say it later. Don\'t run away from our club, got it?',
      'ko': '…그 말은 나중에. 우리 동아리에서 도망가면 안 돼, 알겠지?',
      'ja': '…その話はまた今度。うちの部から逃げちゃだめだよ、わかった？',
      'zh': '……那句话以后再说。不许从我们社团逃走，知道吗？',
      'es': '…Eso te lo digo después. No te escapes de nuestro club, ¿entendido?',
      'pt': '…Isso eu falo depois. Não foge do nosso clube, entendeu?',
      'de': '…Das sag ich dir später. Und hau bloß nicht aus unserem Club ab, klar?',
      'fr': '…Je te le dirai plus tard. T\'as pas intérêt à fuir notre club, compris ?',
      'id': '…Itu nanti aja. Jangan kabur dari klub kita, ngerti?',
      'vi': '…Câu đó để sau. Không được trốn khỏi câu lạc bộ của tụi mình, hiểu chưa?',
    },
    'sc_w12_1_title': {
      'en': 'New Member',
