    },
    'sc_w12_1_3': {
      'en': 'I got chills watching you connect left and right just now. You\'ve gotten so good.',
      'ko': '방금 왼쪽 오른쪽 잇는 거 보고 소름 돋았어. 많이 잘해졌잖아.',
      'ja': '今、左と右をつなぐの見て鳥肌立った。すごくうまくなったね。',
      'zh': '刚才看你把左右连起来，我起鸡皮疙瘩了。你进步好多。',
      'es': 'Me dio escalofríos verte conectar izquierda y derecha. Mejoraste muchísimo.',
      'pt': 'Me arrepiei vendo você ligar a esquerda com a direita. Você melhorou muito.',
      'de': 'Ich hab Gänsehaut gekriegt, als du gerade links und rechts verbunden hast. Du bist so viel besser geworden.',
      'fr': 'J\'ai eu des frissons en te voyant relier la gauche et la droite. T\'as fait de sacrés progrès.',
      'id': 'Barusan lihat kamu nyambungin kiri-kanan, aku merinding. Kamu jago banget sekarang.',
      'vi': 'Vừa thấy cậu nối trái phải mà tớ nổi da gà. Cậu giỏi lên nhiều rồi.',
    },
    'sc_w12_1_4': {
      'en': 'You have to keep playing with me from now on… got it?',
      'ko': '앞으로도 계속 같이 해줘야 해.. 알겠지?',
      'ja': 'これからもずっと一緒にやってくれなきゃだめだからね…わかった？',
      'zh': '以后也要一直陪我玩哦……知道吗？',
      'es': 'De ahora en adelante tienes que seguir jugando conmigo… ¿entendido?',
      'pt': 'Daqui pra frente você tem que continuar jogando comigo… entendeu?',
      'de': 'Du musst ab jetzt immer mit mir spielen… klar?',
      'fr': 'À partir de maintenant, tu dois continuer à jouer avec moi… compris ?',
      'id': 'Mulai sekarang kamu harus terus main bareng aku… ngerti?',
      'vi': 'Từ giờ cậu phải chơi cùng tớ mãi đấy… hiểu chưa?',
