    },
    'sc_w12_2_title': {
      'en': 'Bridge',
      'ko': '다리',
      'ja': '橋',
      'zh': '桥',
      'es': 'Puente',
      'pt': 'Ponte',
      'de': 'Brücke',
      'fr': 'Pont',
      'id': 'Jembatan',
      'vi': 'Cây cầu',
    },
    'sc_w12_2_1': {
      'en': 'Doesn\'t a Hex board look like a bridge? Connecting this side to that side.',
      'ko': '헥스판 보면 꼭 다리 같지 않아? 이쪽이랑 저쪽을 잇는 거.',
      'ja': 'ヘックスの盤って橋みたいじゃない？こっちとあっちをつなぐの。',
      'zh': '六贯棋的棋盘像不像一座桥？连起这边和那边。',
      'es': '¿El tablero de Hex no parece un puente? Une este lado con aquel.',
      'pt': 'O tabuleiro de Hex não parece uma ponte? Liga este lado àquele.',
      'de': 'Sieht ein Hex-Brett nicht aus wie eine Brücke? Es verbindet die eine Seite mit der anderen.',
      'fr': 'Un plateau de Hex, ça ressemble pas à un pont ? Ça relie un côté à l\'autre.',
      'id': 'Papan Hex kelihatan kayak jembatan, nggak? Nyambungin sisi sini sama sisi sana.',
      'vi': 'Bàn Hex nhìn giống cây cầu nhỉ? Nối bên này với bên kia.',
    },
    'sc_w12_2_2': {
      'en': 'A bridge?',
      'ko': '다리?',
      'ja': '橋？',
      'zh': '桥？',
      'es': '¿Un puente?',
      'pt': 'Uma ponte?',
      'de': 'Eine Brücke?',
      'fr': 'Un pont ?',
      'id': 'Jembatan?',
      'vi': 'Cây cầu?',
    },
    'sc_w12_2_3': {
      'en': 'Yeah. Something that stays connected no matter what.',
      'ko': '응. 끊으려 해도 어떻게든 이어지는 거.',
      'ja': 'うん。切ろうとしても、どうにかしてつながるもの。',
      'zh': '嗯。想切断也总会连起来的东西。',
      'es': 'Sí. Algo que sigue unido aunque intenten cortarlo.',
      'pt': 'É. Algo que continua ligado mesmo que tentem cortar.',
      'de': 'Ja. Etwas, das verbunden bleibt, egal wie man\'s zu trennen versucht.',
      'fr': 'Ouais. Un truc qui reste relié, même quand on essaie de le couper.',
      'id': 'Iya. Mau diputus gimana pun, tetap nyambung.',
      'vi': 'Ừ. Có cắt thế nào cũng vẫn nối được.',
    },
    'sc_w12_2_4': {
      'en': '...Don\'t you think we\'re at least that solid by now? We\'ve played over a hundred rounds.',
      'ko': '…나랑 너도 그 정도는 되지 않았을까. 백 판 넘게 뒀는데.',
      'ja': '…私とあんたも、それくらいにはなってるんじゃない? 百戦以上したんだから。',
      'zh': '……我和你,是不是也到那种程度了?都下了一百多局了。',
      'es': '...¿No crees que tú y yo ya hemos llegado a eso? Ya jugamos más de cien partidas.',
      'pt': '...Você não acha que a gente já chegou nesse ponto? A gente já jogou mais de cem partidas.',
      'de': '...Sind du und ich nicht auch schon so weit? Wir haben über hundert Runden gespielt.',
      'fr': '...Toi et moi, on en est pas déjà là? On a joué plus de cent parties, quand même.',
      'id': '...Kau dan aku, bukankah sudah sampai tahap itu? Sudah main lebih dari seratus ronde.',
      'vi': '...Tớ với cậu chắc cũng đến mức đó rồi nhỉ. Chơi hơn trăm ván rồi còn gì.',
    },
    'sc_w12_2_5': {
      'en': 'A bridge, huh.',
      'ko': '다리라.',
      'ja': '橋か。',
      'zh': '桥啊。',
      'es': 'Un puente, ¿eh?',
      'pt': 'Uma ponte, é?',
      'de': 'Eine Brücke, hm.',
      'fr': 'Un pont, hein.',
      'id': 'Jembatan, ya.',
      'vi': 'Cây cầu à.',
    },
    'sc_w12_2_6': {
      'en': 'Wh-what\'s that face! It\'s a metaphor, a METAPHOR!',
      'ko': '뭐, 뭐야 그 표정! 비유야, 비유!',
      'ja': 'な、何よその顔！たとえよ、たとえ！',
      'zh': '干、干嘛那副表情！是比喻，比喻！',
      'es': '¡¿Q-qué es esa cara?! ¡Es una metáfora, una METÁFORA!',
      'pt': 'Q-que cara é essa?! É uma metáfora, uma METÁFORA!',
      'de': 'W-was soll das Gesicht! Das ist eine Metapher, eine METAPHER!',
      'fr': 'Q-quoi, c\'est quoi cette tête ! C\'est une métaphore, une MÉTAPHORE !',
      'id': 'A-apa sih mukamu itu! Itu kiasan, KIASAN!',
      'vi': 'G-gì vậy, cái mặt đó! Ẩn dụ thôi, ẨN DỤ!',
    },
    'sc_w12_3_title': {
      'en': 'A Hundred Times',
      'ko': '백 번',
      'ja': '百回',
      'zh': '一百次',
      'es': 'Cien veces',
      'pt': 'Cem vezes',
      'de': 'Hundert Mal',
      'fr': 'Cent fois',
      'id': 'Seratus Kali',
      'vi': 'Trăm lần',
    },
    'sc_w12_3_1': {
      'en': 'Next time I win! For real!',
      'ko': '다음엔 내가 이겨! 진짜로!',
      'ja': '次は私が勝つ！ほんとに！',
      'zh': '下次我赢！真的！',
      'es': '¡La próxima gano yo! ¡En serio!',
      'pt': 'Da próxima eu ganho! Sério!',
      'de': 'Nächstes Mal gewinne ich! Echt jetzt!',
      'fr': 'La prochaine fois, je gagne ! Pour de vrai !',
      'id': 'Lain kali aku yang menang! Beneran!',
      'vi': 'Lần sau tớ thắng! Thật đấy!',
    },
    'sc_w12_3_2': {
      'en': 'How many times have you said that now?',
      'ko': '그 말 몇 번째야?',
      'ja': 'それ何回目?',
      'zh': '这句话你说第几次了?',
      'es': '¿Cuántas veces llevas diciendo eso?',
      'pt': 'Quantas vezes você já disse isso?',
      'de': 'Wie oft hast du das jetzt schon gesagt?',
      'fr': 'Ça fait combien de fois que tu dis ça?',
      'id': 'Sudah berapa kali kau bilang begitu?',
      'vi': 'Cậu nói câu đó bao nhiêu lần rồi?',
    },
    'sc_w12_3_3': {
      'en': '…A-about a hundred times.',
      'ko': '…배, 백 번쯤.',
      'ja': '…ひゃ、百回くらい。',
      'zh': '……一、一百次左右吧。',
      'es': '…U-unas cien veces.',
      'pt': '…U-umas cem vezes.',
      'de': '…S-so etwa hundertmal.',
      'fr': '…À p-peu près cent fois.',
      'id': '…S-sekitar seratus kali.',
      'vi': '…Kh-khoảng một trăm lần.',
    },
    'sc_w12_3_4': {
      'en': 'The thousandth, the ten-thousandth will be different! Be ready!',
      'ko': '천번, 만번째는 다를거야! 각오해!',
      'ja': '千回目、一万回目は違うんだから！覚悟して！',
      'zh': '第一千次、第一万次可就不一样了！做好觉悟！',
      'es': '¡La milésima, la diezmilésima va a ser distinta! ¡Prepárate!',
      'pt': 'A milésima, a décima milésima vai ser diferente! Se prepara!',
      'de': 'Beim tausendsten, beim zehntausendsten Mal wird\'s anders! Mach dich bereit!',
      'fr': 'La millième, la dix-millième, ce sera différent ! Prépare-toi !',
      'id': 'Yang keseribu, yang kesepuluh ribu bakal beda! Siap-siap!',
      'vi': 'Lần thứ một nghìn, một vạn sẽ khác! Chuẩn bị đi!',
    },
    'sc_w12_3_5': {
      'en': 'We\'re playing that many times together?',
      'ko': '그렇게 많이 같이 하게?',
      'ja': 'そんなにたくさん一緒にやるの？',
      'zh': '要一起玩那么多次？',
      'es': '¿Vamos a jugar tantas veces juntos?',
      'pt': 'A gente vai jogar tantas vezes juntos?',
      'de': 'So oft wollen wir zusammen spielen?',
      'fr': 'On va jouer autant de fois ensemble ?',
      'id': 'Sebanyak itu main bareng?',
      'vi': 'Chơi cùng nhau nhiều vậy luôn?',
    },
    'sc_w12_3_6': {
      'en': 'I-I don\'t know!!',
      'ko': '모, 몰라-!!',
      'ja': 'し、知らないっ！！',
      'zh': '不、不知道啦！！',
      'es': '¡¡N-no sé!!',
      'pt': 'S-sei lá!!',
      'de': 'K-keine Ahnung!!',
      'fr': 'J-j\'en sais rien !!',
      'id': 'N-nggak tahu-!!',
      'vi': 'K-không biết-!!',
    },
    'sc_w12_4_title': {
      'en': 'The End of After School, and Then',
      'ko': '방과후의 끝, 그리고',
      'ja': '放課後の終わり、そして',
      'zh': '放学后的终点,以及',
      'es': 'El final de después de clases, y luego',
      'pt': 'O fim do pós-aula, e então',
      'de': 'Das Ende des Nachmittags, und dann',
      'fr': 'La fin de l\'après-cours, et ensuite',
      'id': 'Akhir Sepulang Sekolah, dan Kemudian',
      'vi': 'Kết thúc giờ tan học, và rồi',
    },
    'sc_w12_4_1': {
      'en': 'You won them all. …So annoying.',
      'ko': '전부 네가 이겼어. …분해.',
      'ja': '全部あんたの勝ち。…悔しい。',
      'zh': '全是你赢了。……不甘心。',
      'es': 'Las ganaste todas. …Qué rabia.',
      'pt': 'Você ganhou todas. …Que raiva.',
      'de': 'Du hast alles gewonnen. …Ärgerlich.',
      'fr': 'T\'as tout gagné. …Ça m\'énerve.',
      'id': 'Semuanya kamu menang. …Kesel.',
      'vi': 'Cậu thắng hết rồi. …Tức ghê.',
    },
    'sc_w12_4_2': {
      'en': 'I\'ll hand you the president seat. For real this time.',
      'ko': '부장 자리, 너한테 물려줄게. 이번엔 진짜야.',
      'ja': '部長の座、あんたに譲る。今度は本気だよ。',
      'zh': '社长的位子让给你。这次是真的。',
      'es': 'Te cedo la presidencia del club. Esta vez va en serio.',
      'pt': 'Vou te passar a presidência do clube. Dessa vez é sério.',
      'de': 'Ich übergeb dir den Vorsitz vom Club. Diesmal im Ernst.',
      'fr': 'Je te laisse la présidence du club. Cette fois, c\'est sérieux.',
      'id': 'Posisi ketua klub, aku serahin ke kamu. Kali ini beneran.',
      'vi': 'Chức chủ nhiệm câu lạc bộ, tớ nhường cho cậu. Lần này thật đấy.',
    },
    'sc_w12_4_3': {
      'en': 'What\'s the catch?',
      'ko': '조건은?',
      'ja': '条件は?',
      'zh': '条件是?',
      'es': '¿Y la condición?',
      'pt': 'E a condição?',
      'de': 'Und die Bedingung?',
      'fr': 'Et la condition?',
      'id': 'Syaratnya?',
      'vi': 'Điều kiện là gì?',
    },
    'sc_w12_4_4': {
      'en': 'There is! I stay on as a member.',
      'ko': '있어! 내가 부원으로 남는 거.',
      'ja': 'あるの！私が部員として残ること。',
      'zh': '有！我留下来当社员。',
      'es': '¡Sí hay! Yo me quedo como miembro.',
      'pt': 'Tem sim! Eu fico como membro.',
      'de': 'Doch! Ich bleib als Mitglied.',
      'fr': 'Si ! Je reste comme membre.',
      'id': 'Ada! Aku tetap jadi anggota.',
      'vi': 'Có chứ! Tớ ở lại làm thành viên.',
    },
    'sc_w12_4_5': {
      'en': 'Of course.',
      'ko': '당연하지.',
      'ja': '当然だよ。',
      'zh': '那是当然。',
      'es': 'Por supuesto.',
      'pt': 'Claro que sim.',
      'de': 'Natürlich.',
      'fr': 'Évidemment.',
      'id': 'Tentu saja.',
      'vi': 'Đương nhiên rồi.',
    },
    'sc_w12_4_6': {
      'en': 'Without someone to beat, I\'d be playing alone again. I d-don\'t want that.',
      'ko': '이길 상대가 없으면 나는 또 혼자 두게 되니까. 그, 그건 싫어.',
      'ja': '勝つ相手がいないと、私また一人で打つことになるから。そ、それはやだ。',
      'zh': '没有可以赢的对手，我又要一个人下了。那、那我不要。',
      'es': 'Sin alguien a quien ganarle, volvería a jugar sola. N-no quiero eso.',
      'pt': 'Sem alguém pra vencer, eu ia voltar a jogar sozinha. E-eu não quero isso.',
      'de': 'Ohne jemanden zum Schlagen spiel ich wieder allein. D-das will ich nicht.',
      'fr': 'Sans personne à battre, je rejouerais toute seule. J-je veux pas ça.',
      'id': 'Kalau nggak ada lawan buat dikalahin, aku bakal main sendirian lagi. A-aku nggak mau.',
      'vi': 'Không có ai để thắng thì tớ lại chơi một mình. T-tớ không muốn vậy.',
    },
    'sc_w12_4_7': {
      'en': 'What I meant to say back at the greenhouse — I\'ll say it now.',
      'ko': '온실에서 하려던 말, 지금 할게.',
      'ja': '温室で言おうとしてたこと、今言うね。',
      'zh': '在温室想说的话,现在说。',
      'es': 'Lo que quería decirte en el invernadero, te lo digo ahora.',
      'pt': 'O que eu ia te dizer na estufa, vou dizer agora.',
      'de': 'Was ich dir im Gewächshaus sagen wollte, sag ich dir jetzt.',
      'fr': 'Ce que je voulais te dire à la serre, je te le dis maintenant.',
      'id': 'Yang ingin kukatakan di rumah kaca waktu itu, akan kukatakan sekarang.',
      'vi': 'Điều tớ định nói ở nhà kính, giờ tớ sẽ nói.',
    },
    'sc_w12_4_8': {
      'en': 'Okay.',
      'ko': '응.',
      'ja': 'うん。',
      'zh': '嗯。',
      'es': 'Está bien.',
      'pt': 'Tá.',
      'de': 'Okay.',
      'fr': 'D\'accord.',
      'id': 'Iya.',
      'vi': 'Ừ.',
    },
    'sc_w12_4_9': {
      'en': 'There\'s no draw between us. So come tomorrow too. After school. …For sure.',
      'ko': '우리는 비기는 게 없어. 그러니까 내일도 와. 방과후에. …꼭.',
      'ja': '私たちに引き分けはないの。だから明日も来て。放課後に。…絶対。',
      'zh': '我们之间没有平局。所以明天也来。放学后。……一定。',
      'es': 'Entre nosotros no hay empate. Así que ven mañana también. Después de clases. …Sin falta.',
      'pt': 'Entre a gente não tem empate. Então vem amanhã também. Depois da aula. …Sem falta.',
      'de': 'Zwischen uns gibt\'s kein Unentschieden. Also komm morgen wieder. Nach der Schule. …Ganz bestimmt.',
      'fr': 'Entre nous, y a pas de match nul. Alors reviens demain. Après les cours. …Sans faute.',
      'id': 'Di antara kita nggak ada seri. Jadi besok datang lagi. Pulang sekolah. …Harus.',
      'vi': 'Giữa tụi mình không có hòa. Nên mai cũng đến nhé. Sau giờ học. …Nhất định đấy.',
    },
    'sc_w12_4_10': {
      'en': 'I\'ll be there.',
      'ko': '갈게.',
      'ja': '行く。',
      'zh': '我会去的。',
      'es': 'Ahí estaré.',
      'pt': 'Eu vou.',
      'de': 'Ich komme.',
      'fr': 'J\'y serai.',
      'id': 'Aku akan datang.',
      'vi': 'Tớ sẽ đến.',
    },
    'sc_w12_4_11': {
      'en': 'I\'ll bring candy. Just like the first time.',
      'ko': '사탕 가져갈게. 처음처럼.',
      'ja': '飴持ってくね。最初みたいに。',
      'zh': '我会带糖来的。像第一次那样。',
      'es': 'Traeré caramelos. Como la primera vez.',
      'pt': 'Vou levar doces. Igual da primeira vez.',
      'de': 'Ich bring Bonbons mit. So wie beim ersten Mal.',
      'fr': 'J\'apporterai des bonbons. Comme la première fois.',
      'id': 'Akan kubawakan permen. Seperti waktu pertama kali.',
      'vi': 'Tớ sẽ mang kẹo theo. Như lần đầu tiên ấy.',
    },
    'sc_w12_4_12': {
      'en': '…No, a little more than at first. Wh-what! Don\'t laugh!',
      'ko': '…아니, 처음보다 조금 더. 뭐, 뭐야! 웃지 마!',
      'ja': '…ううん、最初よりちょっとだけ多く。な、何よ！笑わないで！',
      'zh': '……不对，比一开始多一点点。干、干嘛！不许笑！',
      'es': '…No, un poco más que al principio. ¡¿Q-qué?! ¡No te rías!',
      'pt': '…Não, um pouco mais que no começo. Q-que foi?! Não ri!',
      'de': '…Nein, ein bisschen mehr als am Anfang. W-was denn! Lach nicht!',
      'fr': '…Non, un peu plus qu\'au début. Q-quoi ! Rigole pas !',
      'id': '…Nggak, sedikit lebih dari pertama kali. A-apa sih! Jangan ketawa!',
      'vi': '…Không, nhiều hơn lúc đầu một chút. G-gì chứ! Đừng cười!',
    },
    'rx_w1_1': {
      'en': 'Ex: 10 candies, take 1-2 at a time. I take 2 → Yerin takes 1 → … Whoever takes the last one wins.',
      'ko': '예: 사탕 10개, 한 번에 1~2개. 내가 2개 → 예린이 1개 → … 마지막 하나를 집는 사람이 이겨.',
      'ja': '例: 飴10個、一度に1〜2個。私が2個 → イェリンが1個 → … 最後の一つを取った人が勝ち。',
      'zh': '例:糖果10个,每次拿1~2个。我拿2个 → 艺琳拿1个 → …拿到最后一个的人获胜。',
      'es': 'Ej: 10 caramelos, 1-2 por turno. Yo tomo 2 → Yerin toma 1 → … Quien tome el último gana.',
      'pt': 'Ex: 10 doces, 1-2 por vez. Eu pego 2 → Yerin pega 1 → … Quem pegar o último vence.',
      'de': 'Bsp.: 10 Bonbons, 1-2 pro Zug. Ich nehme 2 → Yerin nimmt 1 → … Wer das letzte nimmt, gewinnt.',
      'fr': 'Ex : 10 bonbons, 1 à 2 par tour. Je prends 2 → Yerin prend 1 → … Qui prend le dernier gagne.',
      'id': 'Cth: 10 permen, ambil 1-2 per giliran. Aku ambil 2 → Yerin ambil 1 → … Siapa yang ambil yang terakhir menang.',
      'vi': 'VD: 10 viên kẹo, mỗi lượt lấy 1-2 viên. Mình lấy 2 → Yerin lấy 1 → … Ai lấy viên cuối cùng thắng.',
    },
    'rx_w1_2': {
      'en': 'Anywhere from 1 up to the max. 0 isn\'t allowed.',
      'ko': '1개도 되고 최대 개수까지 아무거나. 0개는 안 돼.',
      'ja': '1個でも最大数までなら何でもいい。0個はダメ。',
      'zh': '1个也行,最多到上限都可以,但0个不行。',
      'es': 'Puedes tomar desde 1 hasta el máximo. 0 no vale.',
      'pt': 'Pode ser 1 até o máximo. 0 não vale.',
      'de': 'Von 1 bis zum Maximum ist alles erlaubt. 0 geht nicht.',
      'fr': 'De 1 jusqu\'au maximum, comme tu veux. 0 n\'est pas permis.',
      'id': 'Boleh 1 sampai jumlah maksimum, terserah. 0 tidak boleh.',
      'vi': 'Lấy từ 1 đến tối đa đều được. Không được lấy 0.',
    },
    'rx_w2_1': {
      'en': 'Two rows. Pick one row per turn, and take anywhere from 1 up to all of it.',
      'ko': '줄이 두 개. 한 번에 한 줄만 고르고, 그 줄에서는 1개부터 전부까지 마음대로.',
      'ja': '列が二つ。一度に一つの列だけ選んで、その列では1個から全部まで自由に。',
      'zh': '有两行。每次只能选一行,那一行里从1个到全部随便拿。',
      'es': 'Dos filas. Elige una fila por turno y toma desde 1 hasta todo lo que quieras de ella.',
      'pt': 'Duas fileiras. Escolha uma fileira por vez e pegue de 1 até tudo dela.',
      'de': 'Zwei Reihen. Wähle pro Zug nur eine Reihe und nimm daraus 1 bis alles.',
      'fr': 'Deux rangées. Choisis une seule rangée par tour, et prends de 1 jusqu\'à tout ce qu\'elle contient.',
      'id': 'Ada dua baris. Pilih satu baris per giliran, dan ambil dari baris itu, 1 sampai semuanya, terserah.',
      'vi': 'Có hai hàng. Mỗi lượt chỉ chọn một hàng, và lấy từ 1 đến hết hàng đó tùy ý.',
    },
    'rx_w2_2': {
      'en': 'When both rows are empty, whoever took the last one wins.',
      'ko': '두 줄 다 비었을 때 마지막을 집은 사람이 이겨.',
      'ja': '両方の列が空になったとき、最後に取った人が勝ち。',
      'zh': '两行都空了的时候,拿走最后一个的人获胜。',
      'es': 'Cuando ambas filas queden vacías, gana quien haya tomado el último.',
      'pt': 'Quando as duas fileiras ficarem vazias, quem pegou o último vence.',
      'de': 'Wenn beide Reihen leer sind, gewinnt, wer zuletzt genommen hat.',
      'fr': 'Quand les deux rangées sont vides, celui qui a pris le dernier gagne.',
      'id': 'Saat kedua baris kosong, siapa yang mengambil yang terakhir menang.',
      'vi': 'Khi cả hai hàng đều trống, ai lấy cái cuối cùng thắng.',
    },
    'rx_w3_1': {
      'en': 'Three rows. Same rules as two rows. One row per turn, as many as you like.',
      'ko': '줄이 세 개. 규칙은 두 줄과 같아. 한 번에 한 줄, 원하는 만큼.',
      'ja': '列が三つ。ルールは二列と同じ。一回に一列、好きなだけ。',
      'zh': '三行。规则和两行一样。每次一行，想拿多少都行。',
      'es': 'Tres filas. Las reglas son como con dos filas. Una fila por turno, todos los que quieras.',
      'pt': 'Três fileiras. Regras iguais às de duas. Uma fileira por vez, quantos quiser.',
      'de': 'Drei Reihen. Gleiche Regeln wie bei zwei. Eine Reihe pro Zug, so viele du willst.',
      'fr': 'Trois rangées. Mêmes règles qu\'à deux rangées. Une rangée par tour, autant que tu veux.',
      'id': 'Ada tiga baris. Aturannya sama kayak dua baris. Satu baris per giliran, berapa pun sesukamu.',
      'vi': 'Có ba hàng. Luật giống hai hàng. Mỗi lượt một hàng, lấy bao nhiêu tùy thích.',
    },
    'rx_w3_2': {
      'en': 'Each row has a different count. Which row you pick is everything.',
      'ko': '줄마다 개수가 달라. 어느 줄을 고를지가 전부야.',
      'ja': '列ごとに個数が違う。どの列を選ぶかが全て。',
      'zh': '每行的数量都不一样。选哪一行才是关键。',
      'es': 'Cada fila tiene una cantidad distinta. Todo depende de qué fila elijas.',
      'pt': 'Cada fileira tem uma quantidade diferente. Tudo depende de qual fileira você escolhe.',
      'de': 'Jede Reihe hat eine andere Anzahl. Welche Reihe du wählst, entscheidet alles.',
      'fr': 'Chaque rangée a un nombre différent. Tout dépend de la rangée que tu choisis.',
      'id': 'Setiap baris punya jumlah berbeda. Baris mana yang kamu pilih itu yang menentukan segalanya.',
      'vi': 'Mỗi hàng có số lượng khác nhau. Chọn hàng nào mới là điều quan trọng.',
    },
    'rx_w4_1': {
      'en': 'You\'re not taking — you\'re splitting. Pick one bundle and split it into two different-sized parts. 5 → 2+3 (O), 6 → 3+3 (X).',
      'ko': '가져가는 게 아니야. 한 묶음을 골라 서로 다른 크기 둘로 쪼개. 5 → 2+3 (O), 6 → 3+3 (X).',
      'ja': '取るんじゃない。一つの束を選んで、大きさの違う二つに分ける。5 → 2+3 (O)、6 → 3+3 (X)。',
      'zh': '不是拿走。选一捆,拆成大小不同的两份。5 → 2+3 (O),6 → 3+3 (X)。',
      'es': 'No se trata de tomar. Elige un paquete y divídelo en dos partes de tamaño distinto. 5 → 2+3 (O), 6 → 3+3 (X).',
      'pt': 'Não é para pegar. Escolha um pacote e divida em duas partes de tamanhos diferentes. 5 → 2+3 (O), 6 → 3+3 (X).',
      'de': 'Es geht nicht ums Nehmen. Wähle ein Bündel und teile es in zwei unterschiedlich große Teile. 5 → 2+3 (O), 6 → 3+3 (X).',
      'fr': 'Il ne s\'agit pas de prendre. Choisis un tas et divise-le en deux parties de tailles différentes. 5 → 2+3 (O), 6 → 3+3 (X).',
      'id': 'Bukan mengambil. Pilih satu ikatan dan pecah menjadi dua bagian berbeda ukuran. 5 → 2+3 (O), 6 → 3+3 (X).',
      'vi': 'Không phải lấy đi. Chọn một bó rồi chia thành hai phần kích thước khác nhau. 5 → 2+3 (O), 6 → 3+3 (X).',
    },
    'rx_w4_2': {
      'en': 'Bundles of 1 or 2 can\'t be split. If it\'s your turn and there\'s nothing left to split, you lose.',
      'ko': '1개·2개 묶음은 못 쪼개. 내 차례에 쪼갤 묶음이 하나도 없으면 내가 져.',
      'ja': '1個・2個の束は分けられない。自分の番で分けられる束が一つもなければ負け。',
